# file: app/src/webui/help_excerpts.jl
# purpose: GENERATED by tools/generate_webui_help_excerpts.jl from docs/src,
#          do not edit: the documentation sections the Web UI help pages
#          show, keyed by the registry's doc target (page/#anchor), and the
#          Web UI manual (docs/src/webui.md). Edit the documentation page
#          and regenerate.

const WEBUI_HELP_EXCERPTS = Dict{String,NamedTuple{(:title, :markdown, :truncated),Tuple{String,String,Bool}}}(
  "cgmes_export/#cgmes-export-webui" => (title = "Export from the Web UI", markdown = "The run option **Write MATPOWER export artifact** works the same way for\nevery case format: the network of the run is written as a new file\n`<case>_calc_<YYYYMMDD>.m` next to the other artifacts, with a header that\nnames the source case, the write time, the Sparlectra version and whether\nthe bus and branch columns carry the calculated state. The input file is\nnever written.", truncated = true),
  "cgmes_import/#cgmes-import-config" => (title = "Configuration (`cgmes_import`)", markdown = "The keys that steer a CGMES import: where the delivery is, the system base, whether unresolved boundary references fail the import, and the per-element handling described below. The Web UI carries the ones a delivery is usually adjusted with.", truncated = true),
  "configuration/#config-wrong-branch" => (title = "Wrong-branch detection semantics (rectangular PF)", markdown = "`power_flow.wrong_branch_detection` is a post-convergence plausibility check\nfor rectangular PF results; it is heuristic and does not prove global branch\ncorrectness.", truncated = true),
  "contingency/#contingency_screening" => (title = "Screening", markdown = "With `screening_mode = :flag` (keyword on `runContingencies!` and\n`runScenarios!`, or `contingency.screening.mode` for the service and the\nWeb UI) every non-islanding single outage is first estimated with one\nWoodbury-corrected Newton step on the factorized base Jacobian; only\nscenarios whose estimate comes within `screening.margin_pct` (default 10)\nof a limit get the full solve. Switch it on only after checking, on your\nown network, the screening share and that the flagged margins carry the\nviolations (the reported `screened` count and reason breakdown).", truncated = true),
  "matpower/#matpower-options" => (title = "Option reference", markdown = "The keys of a MATPOWER run: the case selectors, the import profile that recommends or applies the conventions a case needs, the conversion switches (phase-shift unit and sign, tap ratio, PV voltage source, shunt and tap-changer model, generator controllers), the solution export and the network preallocation.", truncated = true),
  "performance_profiling/#dishonest_newton" => (title = "Dishonest Newton", markdown = "`power_flow.jacobian_reuse: true` (keyword `jacobian_reuse = true`, Web\nUI: the checkbox \"Dishonest Newton\" under Solver backend, directly below\npower mode) keeps the factorization of the Jacobian for the next Newton\nstep while the mismatch falls by at least\n`jacobian_reuse_min_reduction` (default 10) per step, at most\n`jacobian_reuse_max_steps` (default 3) steps in a row; a reused step that\nmisses the factor is replaced by the honest step. The rules are on the\nSolver Guide. Off by default; it changes\nthe iteration count, not the solution (same tolerance, final state equal\nto honest Newton within it), and works with and without power mode.", truncated = true),
  "performance_profiling/#perf-output" => (title = "Output configuration", markdown = "What a run writes besides its result: the console summary and its diagnostics, the log files, and the detailed CSV export with its writer settings.", truncated = true),
  "performance_profiling/#perf-runtime" => (title = "Runtime", markdown = "Process-level settings read once at startup: the thread report, the Julia and BLAS thread counts, and the parallel work split of the sweeps.", truncated = true),
  "performance_profiling/#power-mode" => (title = "Power mode for repeated solves", markdown = "Power mode is for the cases where one network is solved many times: a\nbenchmark on a persistent model, the scenario engine, N-1 contingency\nsweeps, Monte Carlo, outer control loops. It is off by default; a single\nrun gains nothing from it.", truncated = true),
  "powerflow_configuration/#pf-apslf-start" => (title = "APSLF start values", markdown = "`power_flow.apslf_start.enabled` uses the AnalyticLoadFlow.jl-backed APSLF\nsolver as a guarded start-value generator ahead of the rectangular\nNewton-Raphson solve, with the same insertion point and accept/reject guard\nstyle as the current-iteration pre-solve: the candidate is only adopted\nwhen it strictly improves the rectangular mismatch, otherwise the original\nstart values are restored. Default: disabled. Diagnostic artifact:\n`apslf_start.log`.", truncated = true),
  "powerflow_configuration/#pf-current-iteration-start" => (title = "Current-iteration start options", markdown = "`power_flow.start_current_iteration.enabled` enables a guarded\ncurrent-injection/current-iteration pre-solve before the Newton-Raphson\npower-flow solver starts. This is not a separate power-flow solver and it\ndoes not replace Newton-Raphson. It is a start-value preconditioner:\nSparlectra first builds the initial voltage profile from Start Voltage Mode\nand Start Angle Mode, then optionally tries a few current-iteration steps to\nimprove that initial profile. The improved voltage profile is accepted only\nif it passes the voltage and angle guards and improves the existing\nSparlectra mismatch metric. If it does not improve the start, the original\nstart values are restored and Newton-Raphson starts normally. Default:\ndisabled. Enable this only for difficult cases where the normal start\nprofile or DC/profile-blend start is not robust enough. Diagnostic\nartifact: `current_iteration_start.log`.", truncated = true),
  "powerflow_configuration/#pf-distributed-slack" => (title = "Distributed active-power slack", markdown = "`power_flow.distributed_slack` spreads the active-power imbalance of an\nisland (load + losses − scheduled generation) over the participating\ngenerators instead of loading it onto the reference bus. Theory, augmented\nNewton system and applicability rules: [Solver Guide](SPARLECTRADOCS/solver/).", truncated = true),
  "powerflow_configuration/#pf-external-grid" => (title = "External grid source", markdown = "`power_flow.external_grid` computes the marked slack bus as a non-ideal\nexternal-grid source: before the solve, `convertSlackToExternalGrid!` moves\nthe reference voltage to a hidden internal bus `<bus>__extgrid_int` behind\nthe feeder impedance `z = Un²/Sk''` (split by the R/X ratio), and the former\nslack bus becomes an ordinary solved bus whose voltage droops under load.\nTheory (both formulations, the stiff limit, the short-circuit effect):\n[Slack Bus and External Grid Sources](SPARLECTRADOCS/slack_vs_source/).", truncated = true),
  "powerflow_configuration/#pf-merit" => (title = "Merit-function line search options", markdown = "`power_flow.merit` enables an optional Armijo sufficient-decrease acceptance\ntest inside the autodamp backtracking loop of the rectangular\nNewton-Raphson solver, not a replacement for Newton-Raphson or autodamp.\nDisabled by default (`enabled: false`), which leaves the max-mismatch\nautodamp behavior unchanged. Background:\nMerit-Function Line Search.", truncated = true),
  "powerflow_configuration/#pf-qlimits" => (title = "Q-limit options and guard", markdown = "How the reactive-power limits of PV machines are enforced: the master switch, the enforcement mode (active set or the classic outer loop), when the enforcement starts, the hysteresis around a limit, the final check that every mode ends with, and the guard that judges narrow ranges and remaining violations.", truncated = true),
  "powerflow_configuration/#pf-solver-core" => (title = "Solver core options", markdown = "The options every AC run reads: formulation and mode, flat start, tolerance and iteration cap, damping, slack promotion, the rescue ladder and the DC fallback. The Web UI form carries the ones a run is usually tuned with; the rest is YAML only.", truncated = true),
  "powerflow_configuration/#pf-solver-selection" => (title = "Solver selection (rectangular vs. APSLF)", markdown = "`power_flow.solver` selects the executing solver; `power_flow.method` fixes\nthe AC formulation family (always `rectangular`). `apslf` routes the run\nthrough the external-solver bridge (`buildPfModel`,\n`solvePf(ApslfSolver(...))`, `applyPfSolution!`) to AnalyticLoadFlow.jl's\nanalytic power-series solver (a required dependency; see `apslf_solver`).", truncated = true),
  "powerflow_configuration/#pf-start-mode" => (title = "Start mode options", markdown = "Where the Newton-Raphson iteration starts: the angle and voltage initialisation modes, the profile a start can be taken from, the start projection and the DC and blend attempts that run before the first step. A flat start switches all of them off.", truncated = true),
  "powerflow_configuration/#pf-trust-region" => (title = "Trust-region step control options", markdown = "`power_flow.trust_region` enables an optional scaled-Newton trust-region\nalternative to `power_flow.autodamp`: it caps the Newton step norm at an\nadaptive radius and accepts or rejects trials by merit-function decrease\nrather than by the max-mismatch criterion. Disabled by default\n(`enabled: false`); mutually exclusive with `power_flow.autodamp = true`\n(both control the step length, enabling both is a configuration error).\nBackground: Trust-Region Step Control.", truncated = true),
  "powsybl_import/#powsybl-import-config" => (title = "Configuration (`powsybl_import`)", markdown = "The `powsybl_import` scope (canonical section `powsybl`, alias\n`powsybl_import`), see [Configuration](SPARLECTRADOCS/configuration/):", truncated = true),
  "scf/#scf-writing" => (title = "Writing a case file", markdown = "`exportSCF` writes a network as one JSON file that reads back machine-exact, with its source, the intended calculations and, on request, the solved start state; the Web UI offers the same export from the Case page.", truncated = true),
  "state_estimation/#se-bad-data" => (title = "Bad-data thresholds and robust modes", markdown = "Both limits work on the normalized residual \$r_{n,i} = r_i / \\sqrt{\\Omega_{ii}}\$,\ncomputed with the original sigmas; only the staged knees\n`robust_k1`/`robust_k2` stay on the raw ratio \$|r_i|/\\sigma_i\$. Down-weighting\nand elimination read the same quantity, so their limits are directly\ncomparable. Rule of thumb: suppression for online smoothing, elimination for\nidentification.", truncated = true),
  "state_estimation/#se-k-report" => (title = "Residual correlations (optional K-matrix report)", markdown = "With the correlation report on, each ranking row carries the maximum", truncated = true),
  "state_estimation/#se-max-eliminations" => (title = "Sequential elimination budget", markdown = "Upper bound for the sequential bad-data elimination: while the chi-square\nband test fails and a suspicious measurement (normalized residual at or\nabove 3) is localizable (`wii` > 0.3), the worst row is deactivated and the\nestimation reruns, up to this many times. `0` disables elimination\n(diagnostics only).", truncated = true),
  "state_estimation_configuration/#se-config" => (title = "State-Estimation Configuration", markdown = "`flatstart`, `robust_mode`, `robust`, `k_eliminate`, `k_suppress`,\n`max_eliminations`, `topology_precheck`, and `report_residual_correlation`\nare case-scope keys, like `power_flow.solver`:\nthey can be saved into a case's configuration file (Web UI: the \"Save\nsettings for this case\" button on the State Estimation page, or the\nSettings page), and the State Estimation page's form fields show the\neffective value (case sidecar, else this file, else the default below)\ninstead of a fixed literal. The remaining estimator keys stay\ninstallation-wide, set here or via the API only.", truncated = true),
  "state_estimation_extensions/#se-tap-estimation" => (title = "Transformer tap estimation", markdown = "A tap position that disagrees with the model (a stale SCADA position, a\nlocal operation) poisons the estimate around the transformer: the band test\nreports `:high` and the suspects cluster there although every telemetry row\nis healthy. Releasing the tap as an estimation state resolves this. The\nestimator solves with the tap as a continuous state, rounds it to the\nnearest mechanical step, and solves once more with the tap fixed; the\nreported result is that of the fixed run.", truncated = true),
  "state_estimation_measurements/#se-case-file-measurements" => (title = "Case files carry their own measurements", markdown = "A [Sparlectra Case Format](SPARLECTRADOCS/scf/) case stores its measurement set inside\nthe file. An estimation on such a case needs no separate CSV; the run still\nwrites `measurements.csv` into its output directory for reproducibility.\nNaming a set explicitly takes precedence, and a set generated for the case\nreplaces the one the file carries (the newer data). Every other format\nrequires a CSV.", truncated = true),
  "state_estimation_measurements/#se-generator-gross-error" => (title = "Bad data (k times sigma)", markdown = "Corrupts one measurement, the first active-power flow row, by k times its\nsigma. `0` = off; `10` is a good value: one clearly detectable bad\nmeasurement (for example a stuck transducer). **Bad data rows** says how\nmany telemetry rows get the gross error; the seed decides which.", truncated = true),
  "state_estimation_measurements/#se-generator-noise" => (title = "Seeded noise", markdown = "Adds Gaussian noise at the per-quantity sigmas to every generated value.\nThe random generator is seeded, so regenerating with the same inputs\nreproduces the identical file.", truncated = true),
  "state_estimation_measurements/#se-generator-sigmas" => (title = "Measurement sigmas (U, I, P, Q)", markdown = "Measurement accuracy per quantity in percent of the measured value (like a\ntransducer accuracy class), written into the sigma column of every\ngenerated row and used for the noise, when enabled:", truncated = true),
  "state_estimation_measurements/#se-generator-tap-error" => (title = "Tap deviation", markdown = "Generates the measurements from a network state whose first in-service\ntransformer runs the given number of mechanical tap steps off the model\nposition (0 = off; whole steps only, a tap changer has no half positions).\n**Transformers (max)** bounds how many transformers deviate. The deviation\nlives on the same tap-fraction grid the estimator's fixation uses, so it is\nexactly recoverable: tap estimation finds the step and the fixation run\nends near `J = 0`.", truncated = true),
  "state_estimation_measurements/#se-generator-v2" => (title = "Measurement generator v2", markdown = "Truth state, flow placement, passive-node handling and a target number of\ncritical measurements are configurable in the Web UI form.", truncated = true),
  "state_estimation_measurements/#se-measurement-files" => (title = "Measurement files and the SE chain", markdown = "`writeMeasurementsCSV(net; file)` and\n`readMeasurementsCSV!(net; file, replace = true)` persist measurement sets\nas UTF-8 CSV. The first line is the version comment, the second the header:", truncated = true),
  "webui_reference/#webui-configuration" => (title = "Configuration", markdown = "**Check configuration** and **Refresh configuration** bring a local file up\nto a template that gained options. Check is a dry run against `src/config/configuration.yaml.example`: missing keys,\nknown deprecated aliases, duplicate YAML keys and a preview of the refreshed\nYAML, nothing written. Refresh keeps existing values, adds missing keys with\ntemplate defaults and may normalize deprecated aliases (start-mode settings,\nlegacy `matpower_*` Q-limit mode names); it never runs at startup, writes a\ntimestamped backup first, refuses on duplicate keys, and offers uploaded or\npasted YAML as a download instead of rewriting it.\n\nThe **Configuration Editor** opens the active YAML in a textarea, validates\nit with the same parser and duplicate-key checks, writes only after\nvalidation with a timestamped backup, and warns when a case configuration\nfile still overrides the global YAML through the prefilled form. After a\nsave the server reloads the file, so the form shows the new values on the\nnext page load.\n\nForm values override the YAML configuration; the order is described in\n[Configuration](SPARLECTRADOCS/configuration/). Each run writes `effective_config.yaml`.\n**Ignore Web UI settings and use configuration defaults** runs with the YAML\nvalues only. `model.auto_profile: apply` may still adjust MATPOWER import\nconventions after form and API values are assembled;\n`effective_config.yaml` records that.\n\n**Help** in the header opens the help ([Web UI](/help)) inside the Web\nUI, as shipped with the running version, and the help links to this\nreference; **Project Docs** opens the published documentation\n(`webui.docs_base_url`). The help pages behind the **?** icons carry a\nsection of the help or of this reference in full, or the lead paragraph\nof a library section with the link to it.\n\n### [Search the help](@id webui_help_search)\n\nThe search field stands at the top of the help and of this reference and\nin the header of every page. It looks through the help, the reference and\nthe help pages of the controls, headings and tables included. Every word\nentered must occur, a part of a word is enough, upper and lower case do\nnot matter. The hits appear while you type: the heading of the section\nas a link to its place, below it a line of the text with the words\nmarked, hits in a heading first. `/` puts the cursor into the search\nfield, Enter opens the first hit, Esc closes the list. Without a hit the\npage says so and links to the published documentation, which has a search\nof its own. The search runs on the own machine on an index that ships\nwith the application; it needs no network. With scripts switched off in\nthe browser the field is a plain form that answers with a page of hits.", truncated = false),
  "webui_reference/#webui-flat-start" => (title = "Flat start", markdown = "`power_flow.flatstart` starts the Newton-Raphson solve at 1.0 pu and 0\ndegrees on every bus and ignores the imported start voltages (MATPOWER\n`VM`/`VA`, CGMES `SvVoltage`, SCF `start_state`). Off, the imported values\nseed the solve; a delivery is built around its own operating point, so that\nis the better start for real networks and the default.\n\nThis checkbox is the one start switch: while it is on, a run switches\n**Use APSLF start values**, **Use DC start values**, the current-iteration\npre-solve and the start projection off and treats both start modes as\n`classic`, so the start really is flat and no projection or pre-solve moves\nit; the run log names what was switched off. The greyed controls keep their\nsaved values and come back when the flat start is unchecked.\n\nA CGMES run honours the flat start under **CGMES start values** = `auto`;\nan explicit `sv` on the Case page still starts from the delivery state\n([Power flow configuration](SPARLECTRADOCS/powerflow_configuration/#pf-solver-core)).", truncated = false),
  "webui_reference/#webui-form-options" => (title = "Form options", markdown = "The settings and run forms offer:\n\n- case name or local path, configuration template file, the read-only\n  output root (set only through `start_sparlectra_webui(; output_root)`);\n- tolerance (decimals or scientific notation such as `1e-8`; the exponent\n  spinner, buttons or Up/Down keys, steps the exponent and keeps the\n  mantissa: `1e-5` down gives `1e-6`, up gives `1e-4`), maximum iterations,\n  autodamping with its minimum factor;\n- **Q-limit handling**: the `power_flow.qlimits.enabled` checkbox and the\n  enforcement-mode selector in one block; the selector also offers **off**\n  and shows it whenever the handling is off. Below them, **PV/PQ\n  switching** shows the hysteresis and the final check bound\n  (`final_q_accept_pu`, `auto` or a value in pu; the two settings the\n  classic modes read), the first switching iteration (`start_iter`), the\n  maximum switches per bus (`guard.max_switches`), freezing after repeated\n  switching and the narrow-range guard switch (`guard.enabled`); **Advanced**\n  holds the rest of `power_flow.qlimits`: start rule and auto threshold,\n  cooldown, release voltage margin, the traced buses (bus\n  numbers of the case file) and the buses locked to PQ (case bus numbers\n  for a MATPOWER file, otherwise internal positions), the violation rule and threshold, bounded violations, and\n  the narrow- and zero-range rules with their log line\n  ([Q-limit options and guard](SPARLECTRADOCS/powerflow_configuration/#pf-qlimits)).\n  Per-unit values take scientific notation like the tolerance, bus lists\n  comma-separated numbers. Everything is grayed while the handling is off;\n  the classic modes solve completely and then check the limits, again\n  after every clamp, so they have no start iteration and gray what they do\n  not read (they use the hysteresis and the final check bound); the guard switch grays the range rules, because the switch\n  cap, freezing and the violation rule act without it. All of it saves to\n  the configuration file and per case like every other run option;\n- **Solver**: one radio group `power_flow_solver` with the peer values\n  `rectangular` (AC Newton-Raphson), `apslf` (AnalyticLoadFlow) and `dc`\n  (linear screening model), writing `power_flow.solver`, `power_flow.apslf.*`,\n  `power_flow.apslf_start.*` and `power_flow.dc.*`\n  ([solver selection](SPARLECTRADOCS/powerflow_configuration/#solver-selection-rectangular-vs-apslf),\n  [DC power flow](SPARLECTRADOCS/powerflow_configuration/#solver-selection-dc-power-flow));\n  radio buttons are never disabled, so the choice is always submitted;\n- wrong-branch detection mode, start angle and voltage modes;\n- **Advanced start values**: the current-iteration pre-solve fields\n  (`power_flow.start_current_iteration.*`,\n  [guarded pre-solve](SPARLECTRADOCS/powerflow_configuration/#guarded-current-iteration-start-pre-solve)),\n  a preconditioner between start projection and Newton-Raphson, not a new\n  start mode;\n- **Merit-function line search**: `power_flow.merit.enabled`,\n  `power_flow.merit.armijo_c1`, `power_flow.merit.fallback_max_mismatch`\n  ([options](SPARLECTRADOCS/powerflow_configuration/#merit-function-line-search-options)),\n  requires `power_flow.autodamp = true`; `scale_p`/`scale_q`/`scale_v` are\n  YAML-only; a diagnostic run writes `merit_linesearch.log`;\n- **Non-convergence handling** (Advanced): `power_flow.rescue` (retry\n  ladder), `power_flow.auto_slack` (promote a reference when the case\n  registers none; islands always find their own reference) and\n  `power_flow.dc.fallback` (standalone DC result when AC has no\n  solution), see [Power-Flow Configuration](SPARLECTRADOCS/powerflow_configuration/);\n- MATPOWER import conventions: auto-profile mode (`off`, `recommend`,\n  `apply`) plus transformer ratio, phase shift, bus shunt, PV voltage source\n  and comparison reference;\n- logfile output mode, performance timing and post-run diagnostics.\n\nOnly keys in `GUI_EDITABLE_CONFIG_KEYS` are submitted, the selected template\nis never modified, and each run writes `effective_config.yaml`. Every control\ncarries a hover text with its operation and effect; a **?** next to a\ncontrol with something technical behind it (solver options, estimator\ndiagnostics, Q-limits, formats) opens its help page in a new tab: the hint,\nthe matching section of this documentation as shipped with the running\nversion (the beginning of a long section), and a link to the section on\nthe published site. `webui.docs_base_url` (configuration file) points that\nlink at a local docs build or a pinned version. **Back** returns through\nthe browser history with the entered values intact (fallback `/powerflow`).\n\nFields that do not apply to the selected solver or step control\n(autodamp/trust-region) are grayed out in place, not hidden; a grayed field\nis `disabled` and not submitted.", truncated = false),
  "webui_reference/#webui-import-case-files" => (title = "Import case files", markdown = "**Import case files** opens the native file picker and accepts several files\nat once: MATPOWER `.m`/`.M`, DTF `.dat`/`.DAT`, CGMES `.zip` deliveries,\nCGMES profile files (`.xml`) and PowSyBl IIDM files (`.xiidm`); the\nserver validates the extension again. An uploaded `.xiidm` file runs as\nit is.\nSeveral `.xml` files (the EQ, SSH, TP and SV profiles of one delivery, such\nas a `data/cgmes_demo` folder) are packed into one `<stem>_cgmes.zip` named\nafter the common stem; the set must contain the EQ profile. A CGMES ZIP may\nhold nested ZIPs; the importer opens them in memory. A Sparlectra Case\nFormat `.json` file is parsed and validated before it is stored.\n\nImporting is copy-only: no run, no run directory, no parsing of `.m` code.\nFiles land in the case directory the form shows (`data/mpower`, in a\ncheckout too), the selector is rebuilt from disk, and the first runnable\nfile may be preselected; the run still needs **Start PowerFlow run**.\nLimits: 100 MiB per file, 250 MiB per request. An existing file is never\noverwritten (`already exists`, the other files still import), and names\nthat would resolve outside the case directory are refused. Enter in **Or\ntype case file path** resolves the value the same copy-only way: a bare\ncase name via `ensure_casefile`, `cgmes:<alias>` as below, or a full\nlocal path copied with the same validation; the file then appears in the\n**Existing case file** selector.\n\nRe-importing a saved set brings the `.config.yaml` sidecar along with the\n`.scf.json` and its measurement set(s) when all are selected together;\nthe `.yaml` is validated as a case-scope configuration file\n(`scope: case`) before it is stored, and rejected otherwise.", truncated = false),
  "webui_reference/#webui-output-modes" => (title = "Output modes", markdown = "- **Logfile output mode**: `classic` writes the result report plus a\n  compact timing and status summary (`solver_time`, `representative_time`,\n  iterations, final mismatch, outcome); `full` adds **Full run details** with the effective\n  typed configuration, artifact choices and status diagnostics. MATPOWER\n  `.m` runs also print the \"Original/Final effective MATPOWER import\n  options\" and \"MATPOWER auto-profile recommendations\" tables, because `.m`\n  files leave `shift_sign`, `shift_unit` and `ratio` ambiguous; DTF `.DAT`\n  runs never print them, so their shorter `run.log` is expected.\n- **Performance timing** (`off`, `compact`, `full`) writes\n  `performance.log` with the phases of one request (request parsing, case\n  resolution, configuration, case loading and network construction, solve,\n  postprocessing, artifact writing, solver and total time; `full` adds\n  internal profile entries). A run from the Web UI solves once; repeated\n  timing is the benchmark mode of `run_matpower_case` in a script\n  ([Performance Profiling](SPARLECTRADOCS/performance_profiling/#perf-benchmark)). Older\n  saved configurations with the former benchmark fields of the form are\n  cleaned by **Refresh configuration**, which names each removed field.\n- **Export case as CGMES delivery (EQ+TP+SSH+SV, ZIP)** writes the case as\n  one re-importable delivery into the run's artifacts, for every case format\n  and also on non-converged runs; see [CGMES Export](SPARLECTRADOCS/cgmes_export/).\n- **Write bus/branch CSV files** (API default off, because large networks\n  produce large files) writes `bus_voltages_complex.csv` (per bus `vm_pu`,\n  `va_deg`, numeric `v_re` and `v_im`, readable `v_complex`, nominal and\n  actual voltage, generation, load, Q-limit and control columns) and\n  `branch_flows.csv` (active and reactive power at both ends, losses,\n  rating, status, overload) from the `ACPFlowReport` rows.\n- **CSV format** is the machine-scope key `output.csv_format` (**Save\n  settings** writes it to the configuration file, a per-case save leaves it\n  out) and applies to every CSV of every run type, state estimation\n  included: `technical` (default: comma delimiter, decimal point, no\n  grouping), `excel_de` (semicolon, decimal comma, thousands dot),\n  `excel_us` (comma, decimal point, thousands comma, grouped numbers\n  quoted). The Excel formats avoid exponent notation where practical;\n  `v_complex` follows the decimal notation, `v_re`/`v_im` stay numeric.\n  Excel may still auto-convert identifiers like `1E5`; use **Data > From\n  Text/CSV** with text types when that matters.", truncated = false),
)

# The Web UI user help (docs/src/webui.md) and the ids of its labelled headings.
const WEBUI_HELP_MANUAL = "# Web UI\n\nThe Web UI is a local browser interface for Sparlectra: choose a case,\nstart a calculation, read the result. It runs on your own machine, is\nreachable from that machine only and has no login. Operation and details\nare on [Web UI Reference](/help/reference).\n\n## Start\n\nInstall and start in one line. Julia is installed if it is missing:\n\n```sh\ncurl -fsSL https://raw.githubusercontent.com/Welthulk/Sparlectra.jl/main/tools/install_webui.sh | sh\n```\n\n```powershell\niwr -useb https://raw.githubusercontent.com/Welthulk/Sparlectra.jl/main/tools/install_webui.bat -OutFile install_webui.bat; .\\install_webui.bat\n```\n\nFrom an installed copy or a checkout:\n\n```sh\njulia --project=. start_webui.jl\n```\n\n`start_webui.sh` and `start_webui.bat` do the same. The browser opens\n`http://127.0.0.1:8080/powerflow`. The first start prepares the\nenvironment once and offers to build a system image, which makes every\nlater start fast ([Sysimage](SPARLECTRADOCS/sysimage/)). The questions of the\ninstaller, the start from the Julia REPL and the directories the Web UI\nuses are described in the\n[reference](/help/reference#installation-and-start).\n\n## Case formats at a glance\n\n| Format | How the case gets in | Download possible | Good to know |\n|---|---|---|---|\n| MATPOWER (`.m`) | **Import case files**, or type a name into **Or type case file path** | Yes: a standard name such as `case14.m` or `case118.m` is fetched once from the MATPOWER project | The download needs an internet connection the first time, afterwards the case is local |\n| CGMES | **Import case files** with the delivery ZIP, or with the profile files (EQ, SSH, TP, SV) selected together | Yes: `cgmes:<alias>` fetches the ENTSO-E test configurations once (about 22 MB) | Every uploaded delivery is checked for completeness; the aliases are listed under [CGMES test configurations](/help/reference#webui_cgmes_test_configurations) |\n| PowSyBl IIDM (`.xiidm`) | **Import case files** | No | The file is read as it is; unpack a compressed file first. See [PowSyBl IIDM files](/help/reference#webui_powsybl) |\n| Sparlectra Case Format, power-grid-model (`.json`) | **Import case files**, or **Export as SCF case file** from any selected case | No | Scenario files and the scenario editor need this format |\n| DTF (`.DAT`) | **Import case files** | No | Experimental, for diagnostics and validation |\n| Shipped demo cases | Already in the selector | Not needed | They work offline |\n\nNothing is downloaded without a name you typed. A selected or uploaded\nfile is used as it is.\n\n## Loading a case\n\nThe **Case** page holds the case selector, the import, the exports and\nthe import options of the selected format.\n\n- **Existing case file** lists the cases of the case directory and the\n  shipped demo cases ([Shipped Demo Cases](SPARLECTRADOCS/demo_cases/)).\n- **Import case files** takes several files at once and copies them into\n  the case directory. It starts no calculation and never overwrites an\n  existing file.\n- **Or type case file path** takes a name to download (see the table) or\n  the path of a local file.\n- **Case input format** stays on **Auto** unless the extension does not\n  say what the file is.\n- **Export as SCF case file**, **Save case as** and **Download selected\n  case** write or deliver the case. **Save case as** keeps variants of one\n  network side by side.\n\nDetails: [Case selector](/help/reference#webui-case-selector),\n[Import case files](/help/reference#webui-import-case-files),\n[Save case as](/help/reference#save-case-as).\n\n## Running\n\nThe **Runs** page starts the calculations for the selected case. Every\nstart opens a status page that follows the run, and a running job can be\naborted there. The options of a run are on the **Settings** page.\n\n### Power flow\n\n**Start PowerFlow run** solves the network with the selected solver:\nNewton-Raphson, APSLF or the linear DC model. The start values come from\nthe case unless **Flat start** is set. Reactive limits of the machines are\nenforced in the mode chosen under **Q-limit handling**. See\n[Power-Flow Configuration](SPARLECTRADOCS/powerflow_configuration/).\n\n### Diagnose\n\n**Diagnose** evaluates the mismatch at the operating point the case\nbrings along, without a corrective step. The result shows where the\nimported model does not balance, bus by bus. It is the first thing to\nrun when a case does not converge. See\n[Diagnose](/help/reference#diagnose).\n\n### N-1\n\nThe outage kind (branches or generators) selects the generated outage\nlist; a case in the Sparlectra Case Format can carry scenarios of its\nown. The result ranks the cases by severity, failures first. Screening\nand weights are optional. See\n[N-1 Contingency Analysis](SPARLECTRADOCS/contingency/).\n\n### State estimation\n\nThe state-estimation section selects a measurement set, or generates one\nfrom a solved power flow. A run checks the observability, estimates the\nstate and reports suspicious measurements. The result page offers a\npower flow from the estimate. See\n[State Estimation](SPARLECTRADOCS/state_estimation/).\n\n### Short circuit\n\n**Short circuit** computes the balanced three-phase currents of every\nbus, maximum and minimum case, without a power-flow solve. The button is\noffered when the case carries source data; a run is `succeeded` only when\nevery source carries its data. See\n[Short-Circuit Analysis](SPARLECTRADOCS/short_circuit/).\n\n## Results\n\nEvery finished run has a result page with status, iterations, final\nmismatch and the list of its artifacts. A CSV artifact opens as a table,\na Markdown report rendered, and **Download all artifacts as ZIP** packs\nthe run. **Run history** lists the runs, newest first; two runs of the\nsame case can be compared side by side. The **Operation Log** records\nwhat the Web UI did and is the file to attach to an error report. See\n[Results and artifacts](/help/reference#results-and-artifacts) and\n[Output modes](/help/reference#webui-output-modes).\n\n## Settings\n\nThe **Settings** page holds the options that do not belong to a single\nrun: solver, start, output. **Save settings** writes either for the\nselected case or into the configuration file. With a case selected, every\npage shows the values a run of that case will use: case settings before\nthe configuration file before the defaults. The **Configuration Editor**\nedits the file as text and checks it before it is saved. See\n[Form options](/help/reference#webui-form-options) and\n[Configuration](/help/reference#webui-configuration).\n\n**Help** in the header opens this page inside the Web UI. **Search the\nhelp** looks through this page, the reference and the help of the\ncontrols. The **?** next to a control opens the help of that control.\n\n## Limits\n\nThe Web UI is local by design: one user, the own machine, no login and\nno public-server mode. A running job reports its progress through the\nstatus page, which refreshes by itself. There is no topology view and no\nplotting.\n"
const WEBUI_HELP_MANUAL_ANCHORS = Dict{String,String}(
  "Case formats at a glance" => "webui-case-formats",
)

# The Web UI reference (docs/src/webui_reference.md) and the ids of its labelled headings.
const WEBUI_HELP_REFERENCE = "# Web UI Reference\n\nOperation and details of the [Web UI](/help): installation,\ndirectories, every form option, the run kinds, artifacts, history and\nconfiguration. The user help is the page [Web UI](/help).\n\nThe Web UI is a local browser interface on top of the\n[PowerFlow service](SPARLECTRADOCS/powerflow_service/). It holds presentation, form\nparsing and route handling only; every calculation runs through\n`start_powerflow_run` and `run_sparlectra_api`. It binds to loopback\n(`127.0.0.1`, `localhost`, `::1`) and has no authentication: a single-user\ntool on the machine that computes; a wider binding would expose the run\ndirectory and the configuration editor.\n\n## Installation and start\n\n### One-line install\n\nInstalls Julia if missing (via juliaup), downloads the latest tagged release\ninto `Sparlectra/` in the current directory, and starts the Web UI:\n\n```sh\ncurl -fsSL https://raw.githubusercontent.com/Welthulk/Sparlectra.jl/main/tools/install_webui.sh | sh\n```\n\n```powershell\niwr -useb https://raw.githubusercontent.com/Welthulk/Sparlectra.jl/main/tools/install_webui.bat -OutFile install_webui.bat; .\\install_webui.bat\n```\n\nThe same scripts, `tools/install_webui.sh` / `tools/install_webui.bat`, ask\nthree questions:\n\n- **Update** when an existing copy is older than the latest release; the old\n  copy is kept as `Sparlectra.old`.\n- **Sysimage**: the installer leaves the [sysimage](SPARLECTRADOCS/sysimage/) build to the\n  Web UI start and builds it only with `SPARLECTRA_BUILD_SYSIMAGE=1`.\n- **Desktop shortcut** for restarting the Web UI: Windows `Sparlectra Web\n  UI.lnk`; Linux an application-menu entry plus a `.desktop` file on the\n  desktop (GNOME needs a one-time right-click \"Allow Launching\"); macOS a\n  desktop symlink.\n\nUnattended installs answer them with `SPARLECTRA_UPDATE=1/0`,\n`SPARLECTRA_BUILD_SYSIMAGE=1/0` and `SPARLECTRA_CREATE_SHORTCUT=1/0`.\n\n### Start script\n\nFrom a checkout or an installed copy:\n\n```sh\njulia --project=. start_webui.jl\n```\n\n`start_webui.sh` / `start_webui.bat` run the same script (and point at the\ninstall script when Julia is missing); a Windows desktop shortcut is\nright-click `start_webui.bat`, *Send to > Desktop (create shortcut)*.\n`start_webui.jl` delegates to `start_sparlectra_webui`. It first compares\nthe direct dependencies in `Project.toml` with `Manifest.toml`, for the\nlibrary and for `app/` (four TOML reads, no package load); a missing\ndependency or manifest is resolved, instantiated and compiled once, with the\ntime reported, and the next start compiles nothing. `Manifest.toml` is not\ntracked, so a fresh clone and an old manifest are both covered.\n`julia --project=. start_webui.jl --env-only` does only that first-start\nwork.\n\nThen it looks for a usable sysimage and offers to build one; the build,\nits flags, the staleness rules and the **Sysimage** page are on\n[Sysimage](SPARLECTRADOCS/sysimage/).\n\n### From the Julia REPL\n\n```julia\nusing Pkg\nPkg.activate(\"path/to/Sparlectra/app\")\nPkg.instantiate()   # first time only\nusing SparlectraApp\n\nserver = start_sparlectra_webui(open_browser = true)\nwait(server.task)\n```\n\nSuch a session runs without the sysimage; how to start a REPL session on\nthe image is on [Sysimage](SPARLECTRADOCS/sysimage/).\n\n`start_sparlectra_webui` returns a `SparlectraWebUIServer` handle and serves\nas soon as the socket is bound, with no hidden warm-up run.\n`open_browser = true` opens an app-style window (Microsoft Edge, Google\nChrome, Chromium or Brave); without one of them the URL\n`http://127.0.0.1:8080/powerflow` is logged. If the port is occupied, stop\nthe old Julia process or pass another `port`.\n\n### Directories and files\n\nResults go to `%LOCALAPPDATA%\\Sparlectra\\WebUI\\runs` (Windows),\n`\$XDG_STATE_HOME/sparlectra/webui/runs`, default\n`~/.local/state/sparlectra/webui/runs` (Linux) or\n`~/Library/Application Support/Sparlectra/WebUI/runs` (macOS), created\nautomatically; the operation log is in the sibling `logs`, downloaded and\ngenerated cases in the sibling `data/mpower`. That case directory is shared\nwith `ensure_casefile` and the test suite; `SPARLECTRA_LARGE_CASES_DIR`\noverrides it for all three. The bundled `warmup_case*.jl` precompile\nworkloads are copied there on first start; the reserved `warmup_` prefix\nhides them from the case selector (the sysimage workload runs the shipped\n`sp_case5`/`sp_case60`).\n\nThe first start copies the package configuration template to the\nuser-writable `config/configuration.yaml`; `output_root = \"...\"` and\n`config_file = \"...\"` override the defaults, and an explicit configuration\nfile is never overwritten. Next to it the Web UI keeps:\n\n- `configuration.template.yaml`, the template the file was last aligned\n  with: a key still at an old template default follows a new default at\n  start (reported with key, old and new value; previous file kept as\n  `configuration.yaml.template-follow.bak`), a changed value stays;\n- `configuration.yaml.user-keys.txt`, the keys the Web UI itself saved\n  (settings save, notice dismiss, configuration editor), which are never\n  followed; deleting it or the template copy only loses that memory;\n- `configuration.yaml.settings-save.bak`, the backup of a settings save.\n\nThe pages show the effective configuration, output root, case cache and\noperation log; the browser cannot change the output root. Header and footer\nshow the logo (`docs/src/assets/logo.png`) and `Sparlectra.version()`;\nheader and operation log also name the package path and Git commit. The\n**Info** panel names the serving build (`sysimage, built ...` or `native\nsession`) and links to the Sysimage page.\n\n## Importing cases\n\nThe **Case** page carries the case chooser, upload, export and the\nper-format import options.\n\n### Case selector\n\nThe selector lists the MATPOWER `.m` files and runnable DTF `.DAT`\ncandidates of the case directory, the shipped demo cases `sp_case5` to\n`sp_case188` ([Shipped Demo Cases](SPARLECTRADOCS/demo_cases/)), staged into the cache\nwith their sidecars (per-case configuration, measurement CSVs) on first\nuse, the three CGMES deliveries exported by Sparlectra itself\n(`data/cgmes_demo`: `sp_case14`, `sp_case118`, `sp_casePST`, four profile\nfiles each) as `<case>_cgmes.zip`, and PowSyBl IIDM files (`.xiidm`,\nthe four under `data/powsybl` included). Generated `.jl` cache files and\n`warmup_` files are hidden. FOR002-like `.DAT` files are not primary cases;\nthey go into the optional **FOR002 reference** field (absolute path, path\nin the case cache, or an offered candidate), used only for legacy reference\ncomparison.\n\n**Or type case file path** overrides the selector: a bare name such as\n`case14.m`, `case118.m` or `case9241pegase.m` is downloaded into the case\ndirectory, an existing absolute or relative `.m`/`.jl` path is used as\ngiven; path-like missing inputs and URLs are rejected. A generated `.jl` cache file resolves back to its `.m` source\n(the bypass is recorded) and is rejected without one: large `.jl` literal\ncases can fail while Julia loads them, so `.m` stays the canonical source.\n\n**Case input format** defaults to **Auto**: MATPOWER files, CGMES\ndeliveries (folders and ZIPs), PowSyBl IIDM files, and, where\nthe DTF reader takes the file as a network, native DTF input. **CGMES (ENTSO-E,\nfolder or ZIP)** forces the CGMES importer and is preselected for a `.zip`\nor a directory; **PowSyBl (IIDM file)** is preselected\nfor those files and shows the PowSyBl import options (HVDC mode, remote\nregulation, slack choice, base MVA; see\n[PowSyBl Import](SPARLECTRADOCS/powsybl_import/)). A `.xiidm` file is read as it is.\n**Sparlectra Case Format (.scf.json)** and **power-grid-model JSON\n(input.json)** name the same reader (the `sparlectra` block is optional);\nAuto already sends every `.json` there, so they matter only when the\nextension does not say what the file is. The native DTF path is\nexperimental, for diagnostics and validation; its **Selected DTF outage\nlabels/indices** field takes one label or index at a time, and the result\npage shows a compact outage summary while the rows stay in artifacts.\n\nThe format-bound option sections derive from the adapters' option structs,\nso the form cannot drift from what a conversion accepts; the Basic set (keys\nused in a workshop, or set in the example configuration without a default)\nrenders directly, the rest and the DTF diagnostics on the Runs page fold\ninto **Advanced**. Deleting a case removes all its companion files\n(configuration, weights, measurement CSVs).\n\nA collapsible MATPOWER acknowledgement next to the case inputs links to the\nproject, its citation guidance and the 2011 paper DOI, and notes that\nACTIVSg, PEGASE, RTE and other cases ask for additional citations in their\nheaders.\n\n### Import case files\n\n**Import case files** opens the native file picker and accepts several files\nat once: MATPOWER `.m`/`.M`, DTF `.dat`/`.DAT`, CGMES `.zip` deliveries,\nCGMES profile files (`.xml`) and PowSyBl IIDM files (`.xiidm`); the\nserver validates the extension again. An uploaded `.xiidm` file runs as\nit is.\nSeveral `.xml` files (the EQ, SSH, TP and SV profiles of one delivery, such\nas a `data/cgmes_demo` folder) are packed into one `<stem>_cgmes.zip` named\nafter the common stem; the set must contain the EQ profile. A CGMES ZIP may\nhold nested ZIPs; the importer opens them in memory. A Sparlectra Case\nFormat `.json` file is parsed and validated before it is stored.\n\nImporting is copy-only: no run, no run directory, no parsing of `.m` code.\nFiles land in the case directory the form shows (`data/mpower`, in a\ncheckout too), the selector is rebuilt from disk, and the first runnable\nfile may be preselected; the run still needs **Start PowerFlow run**.\nLimits: 100 MiB per file, 250 MiB per request. An existing file is never\noverwritten (`already exists`, the other files still import), and names\nthat would resolve outside the case directory are refused. Enter in **Or\ntype case file path** resolves the value the same copy-only way: a bare\ncase name via `ensure_casefile`, `cgmes:<alias>` as below, or a full\nlocal path copied with the same validation; the file then appears in the\n**Existing case file** selector.\n\nRe-importing a saved set brings the `.config.yaml` sidecar along with the\n`.scf.json` and its measurement set(s) when all are selected together;\nthe `.yaml` is validated as a case-scope configuration file\n(`scope: case`) before it is stored, and rejected otherwise.\n\n### Export and download\n\nThe export row writes the open case as `.scf.json` or plain PGM `.pgm.json`,\nreplacing a format suffix the case already carries (`case14.scf.json` as\nPGM gives `case14.pgm.json`); both products appear in the selector as\nrunnable cases. **Download selected case** serves what the selector shows,\nafter an export also the file just written: only plain files inside the\ncase directory (bare name, or an absolute path pointing into it), compared\nby real path because the state directory can sit behind a symlink (Flatpak);\nanything outside, and a CGMES delivery directory, is refused.\n\n### Save case as\n\n**Save case as**, next to the export buttons (also linked from the State\nEstimation section), saves the current case under a new name instead of\nexporting in place: one network with several variants, one file per\nvariant. It writes three files into the case directory:\n\n- `<name>.scf.json` via `exportSCF`, with `meta.case_name = <name>`\n  and `meta.source_reference` noting the source case; a MATPOWER or DTF\n  source is saved as SCF, the original file is never touched.\n- `<name>.config.yaml`: the source case's saved case-scope settings merged\n  with any unsaved change made on the page; the source case's sidecar file\n  is never modified.\n- `<name>.measurements.csv` for each measurement set bound to the source\n  case, with its `# case:` header rewritten to the new name; a second bound\n  set is copied as `<name>_<original stem>.measurements.csv`.\n\nAn existing `<name>.scf.json` is refused unless \"overwrite\" is ticked. The\noptional \"start from the solved state\" checkbox solves the case once with\nthe effective settings and writes the solved voltages as the copy's\n`sparlectra.start_state`. Installation-scope settings (`output.*`,\n`benchmark.*`, `runtime.*`, ...) are never written into the case\nconfiguration file. The file layout is described in\n[Sparlectra Case Format](SPARLECTRADOCS/scf/).\n\n### PowSyBl IIDM files\n\nIIDM is the network format of the PowSyBl framework; its XML form has the\nextension `.xiidm`. The Web UI reads such a file as it is.\n\n**Getting a network in.**\n\n| You have | Do this |\n|---|---|\n| no file yet | pick one of the four shipped networks in the case selector: `ieee14.xiidm`, `four_substations.xiidm`, `micro_grid_be.xiidm`, `ieee14_sc.xiidm` |\n| a `.xiidm` file | **Import case files**, select the file; it appears in the selector |\n| a compressed file (`.xiidm.bz2`, `.gz`) | unpack it first, then import the `.xiidm` |\n\n**What you can run.** Power flow, Diagnose, state estimation (generate a\nmeasurement set first, or upload one), N-1 and short circuit, and the\nexports to the Sparlectra Case Format, MATPOWER and CGMES. Scenario files\nand the scenario editor address the components of a case file: export the\nnetwork with **Export as SCF case file** and work on that file.\n\n**Import options.** With a PowSyBl case selected, the section **Input\nformat** on the Case page shows five options. The defaults fit most files.\n\n| Option | Default | Change it when |\n|---|---|---|\n| System base MVA | 100 | you compare per-unit values with another tool that uses another base |\n| HVDC converters | fixed injections | never for now: the paired controller is not available for PowSyBl files |\n| Remote voltage regulation | hold the target at the unit's own bus | a generator regulates another bus and that bus shall be held exactly: choose the outer-loop control |\n| One slack per synchronous component | on | only the first component shall be solved |\n| Slack generator ids | empty | another unit than the automatically chosen one shall carry the reference; several ids are separated by semicolons |\n\n**What the import tells you.** Every power-flow run on a PowSyBl case\nwrites the artifact `powsybl_import.log`: how many elements of each type\nwere read and built, every element that was skipped with the reason, and\nthe generator that carries the reference of each synchronous component.\nThe file's own voltages are the start of the solve. A file that was\nsolved at other tap or shunt positions than it carries has a state that\ndoes not belong to its data: the import then starts flat, and the\nartifact says so.\n\n**Short circuit.** The sources are the connected generators. The reactance\ncomes from the extension `generatorShortCircuit` of the file; a generator\nwithout it is counted with a default reactance, and the rows it feeds are\nmarked. When no generator carries the extension or a rated power, the\n**Short circuit** button is not offered and its tooltip says why. Of the\nshipped networks `ieee14_sc.xiidm` carries complete data,\n`micro_grid_be.xiidm` runs on defaults with a warning, and `ieee14.xiidm`\nand `four_substations.xiidm` carry none.\n\n**Not read.** Compressed files, time series, and the regulation data of\ntap changers (a transformer stays at the step the file names). An IIDM\nexport does not exist. Conventions and the complete list are on the page\n[PowSyBl Import](SPARLECTRADOCS/powsybl_import/).\n\n### CGMES test configurations\n\n`cgmes:<alias>` in **Or type case file path** downloads the official ENTSO-E\ntest-configuration package once (about 22 MB) into the CGMES cache\n(`data/CGMES`, overridable with `SPARLECTRA_CGMES_CACHE`) and packs the\nrequested configuration with its boundary set into `cgmes_<alias>.zip` in\nthe case directory. Aliases: `microgrid_be`, `microgrid_nl`,\n`microgrid_assembled`, `smallgrid`, `smallgrid_nb`, `fullgrid`,\n`fullgrid_nb`, `realgrid`. Repeated requests reuse the ZIP. If the download\nfails, the message names the path where the package can be placed by hand.\nThe test data is never committed.\n\n### Import analysis on upload\n\nEvery uploaded CGMES delivery is checked at once: a complete one (or one\nwhose boundary is found or supplied automatically) reports \"ready to\ncompute\", an incomplete one gets the full import analysis: the message names\nthe missing declared `md:Model.DependentOn` dependencies by model id\n(typically the boundary set), and the report (supplied models, dependency\nmatching, unresolved-reference histogram, verdict) is written next to the\ncase as `<case>.import_analysis.txt`. The same analysis is appended to\n`cgmes.log` whenever a run's CGMES import aborts. Scripted use: the run mode\n`import_analysis_mode` of `start_powerflow_run` (a non-importable delivery\nends as a failed run with reason `import_analysis_not_importable`) or\n`analyzeCGMES`.\n\n**Require boundary set** (CGMES section, saved per case) submits\n`cgmes_import.require_boundary`; unchecked, an incomplete delivery imports\nwhere possible, but buses without a resolvable `BaseVoltage` still abort,\nwith the analysis explaining why.\n\n### Long actions on a case\n\nGenerating a measurement set or adding noise runs inside the request and\ncan take a while on a large case (with **critical measurements** the\ngenerator re-reads the criticality after every removed row). Meanwhile the\ncase is busy: a second generator action or a run is refused with a message\nand the buttons show a spinner; a queued or running run blocks the\ngenerator the same way.\n\n## Starting a run\n\nRun-independent options live on the **Settings** page (solver, start,\noutput and expert options, plus the configuration block: file display,\ncheck and refresh, saved case settings, the ignore switch) and reach a run\nthrough the configuration precedence (`resolve_config`): saving with target\n\"this case\" writes case-scope keys into the case's configuration file,\ntarget \"configuration file\" merges into the general YAML (backup\n`.settings-save.bak`). The **Runs** page keeps the run parameters (modes,\nN-1 kind, scenario source, screening, DTF outage fields),\nthe state-estimation section (estimator options and measurement-set\nselection submitted with `se_mode`; measurement generator, set details with\ninline editors and measurement upload as fold-out tabs) and the N-1 editors\nas tabs: the scenario editor embeds directly (SCF cases), the weights\neditor loads on first open (seeding its element names builds the net once).\nThe SE section uses the shared case selection.\n\nThe measurement generator's fields are the generator options of\n[State Estimation Measurements](SPARLECTRADOCS/state_estimation_measurements/#Measurement-generator-v2) (sigmas per\nclass, noise, gross errors, tap deviations, truth source, flow ends, passive\nnodes as zero-injection constraints, **critical measurements**); the\nremoved and critical rows are named in the set's comment lines and the\nestimation run log.\n\n### Form options\n\nThe settings and run forms offer:\n\n- case name or local path, configuration template file, the read-only\n  output root (set only through `start_sparlectra_webui(; output_root)`);\n- tolerance (decimals or scientific notation such as `1e-8`; the exponent\n  spinner, buttons or Up/Down keys, steps the exponent and keeps the\n  mantissa: `1e-5` down gives `1e-6`, up gives `1e-4`), maximum iterations,\n  autodamping with its minimum factor;\n- **Q-limit handling**: the `power_flow.qlimits.enabled` checkbox and the\n  enforcement-mode selector in one block; the selector also offers **off**\n  and shows it whenever the handling is off. Below them, **PV/PQ\n  switching** shows the hysteresis and the final check bound\n  (`final_q_accept_pu`, `auto` or a value in pu; the two settings the\n  classic modes read), the first switching iteration (`start_iter`), the\n  maximum switches per bus (`guard.max_switches`), freezing after repeated\n  switching and the narrow-range guard switch (`guard.enabled`); **Advanced**\n  holds the rest of `power_flow.qlimits`: start rule and auto threshold,\n  cooldown, release voltage margin, the traced buses (bus\n  numbers of the case file) and the buses locked to PQ (case bus numbers\n  for a MATPOWER file, otherwise internal positions), the violation rule and threshold, bounded violations, and\n  the narrow- and zero-range rules with their log line\n  ([Q-limit options and guard](SPARLECTRADOCS/powerflow_configuration/#pf-qlimits)).\n  Per-unit values take scientific notation like the tolerance, bus lists\n  comma-separated numbers. Everything is grayed while the handling is off;\n  the classic modes solve completely and then check the limits, again\n  after every clamp, so they have no start iteration and gray what they do\n  not read (they use the hysteresis and the final check bound); the guard switch grays the range rules, because the switch\n  cap, freezing and the violation rule act without it. All of it saves to\n  the configuration file and per case like every other run option;\n- **Solver**: one radio group `power_flow_solver` with the peer values\n  `rectangular` (AC Newton-Raphson), `apslf` (AnalyticLoadFlow) and `dc`\n  (linear screening model), writing `power_flow.solver`, `power_flow.apslf.*`,\n  `power_flow.apslf_start.*` and `power_flow.dc.*`\n  ([solver selection](SPARLECTRADOCS/powerflow_configuration/#solver-selection-rectangular-vs-apslf),\n  [DC power flow](SPARLECTRADOCS/powerflow_configuration/#solver-selection-dc-power-flow));\n  radio buttons are never disabled, so the choice is always submitted;\n- wrong-branch detection mode, start angle and voltage modes;\n- **Advanced start values**: the current-iteration pre-solve fields\n  (`power_flow.start_current_iteration.*`,\n  [guarded pre-solve](SPARLECTRADOCS/powerflow_configuration/#guarded-current-iteration-start-pre-solve)),\n  a preconditioner between start projection and Newton-Raphson, not a new\n  start mode;\n- **Merit-function line search**: `power_flow.merit.enabled`,\n  `power_flow.merit.armijo_c1`, `power_flow.merit.fallback_max_mismatch`\n  ([options](SPARLECTRADOCS/powerflow_configuration/#merit-function-line-search-options)),\n  requires `power_flow.autodamp = true`; `scale_p`/`scale_q`/`scale_v` are\n  YAML-only; a diagnostic run writes `merit_linesearch.log`;\n- **Non-convergence handling** (Advanced): `power_flow.rescue` (retry\n  ladder), `power_flow.auto_slack` (promote a reference when the case\n  registers none; islands always find their own reference) and\n  `power_flow.dc.fallback` (standalone DC result when AC has no\n  solution), see [Power-Flow Configuration](SPARLECTRADOCS/powerflow_configuration/);\n- MATPOWER import conventions: auto-profile mode (`off`, `recommend`,\n  `apply`) plus transformer ratio, phase shift, bus shunt, PV voltage source\n  and comparison reference;\n- logfile output mode, performance timing and post-run diagnostics.\n\nOnly keys in `GUI_EDITABLE_CONFIG_KEYS` are submitted, the selected template\nis never modified, and each run writes `effective_config.yaml`. Every control\ncarries a hover text with its operation and effect; a **?** next to a\ncontrol with something technical behind it (solver options, estimator\ndiagnostics, Q-limits, formats) opens its help page in a new tab: the hint,\nthe matching section of this documentation as shipped with the running\nversion (the beginning of a long section), and a link to the section on\nthe published site. `webui.docs_base_url` (configuration file) points that\nlink at a local docs build or a pinned version. **Back** returns through\nthe browser history with the entered values intact (fallback `/powerflow`).\n\nFields that do not apply to the selected solver or step control\n(autodamp/trust-region) are grayed out in place, not hidden; a grayed field\nis `disabled` and not submitted.\n\n### AC, APSLF and DC\n\n`AC (Newton-Raphson, rectangular)` reveals the start-value block (**Flat\nstart**, **Use APSLF start values** with its order field, **Use DC start\nvalues**) and every AC-only option: tolerance, autodamping/merit/trust-region\nstep control, Q-limit handling, maximum iterations, wrong-branch detection,\nstart angle/voltage mode, the current-iteration pre-solve and the\ntransformer tap-changer model. By default\n(`power_flow.start_mode.angle_mode = dc`) Newton-Raphson seeds its start\nangles from an internal DC pre-solve, controlled by **Start angle mode**;\nthat pre-solve is unrelated to the standalone `DC` solver.\n\n`APSLF (AnalyticLoadFlow)` reveals the **APSLF solver options** (highest\ncoefficient/order, Padé evaluation, NR polish). **Use APSLF start values**\nin the Newton-Raphson block seeds the rectangular solver instead and is\nmutually exclusive with the APSLF solver (the configuration rejects both).\nAn unchecked checkbox (APSLF, Q-limit, current-iteration) submits `false`\nrather than omitting the key. The APSLF solver\nneeds the optional AnalyticLoadFlow.jl package in the server process;\nwithout it the run fails with a pre-solve error instead of falling back to\nthe rectangular solver.\n\n`DC` replaces Newton-Raphson with the linear model\n([DC power flow](SPARLECTRADOCS/powerflow_configuration/#solver-selection-dc-power-flow)),\nthe `dc` value of `power_flow.solver`, and grays out every AC-only option\nabove. A DC run uses the same job, abort, status, history and artifact\nmachinery; the result page marks it with a **DC solution** badge next to\n**Solver** and the history column shows `dc`, so the implicit\n`Vm = 1.0 pu` and lossless flows are never taken for an AC result;\n`iterations` is `1` (a direct solve).\n\nThe **Solver** column names the method that ran: the power-flow solver for\na plain power flow, one started from an estimate and every contingency\ncase; `wls` for a state estimation; `iec60909` for a short circuit; empty\nfor an import analysis (derived from the run kind when a run carries no\nmethod).\n\n#### Flat start\n\n`power_flow.flatstart` starts the Newton-Raphson solve at 1.0 pu and 0\ndegrees on every bus and ignores the imported start voltages (MATPOWER\n`VM`/`VA`, CGMES `SvVoltage`, SCF `start_state`). Off, the imported values\nseed the solve; a delivery is built around its own operating point, so that\nis the better start for real networks and the default.\n\nThis checkbox is the one start switch: while it is on, a run switches\n**Use APSLF start values**, **Use DC start values**, the current-iteration\npre-solve and the start projection off and treats both start modes as\n`classic`, so the start really is flat and no projection or pre-solve moves\nit; the run log names what was switched off. The greyed controls keep their\nsaved values and come back when the flat start is unchecked.\n\nA CGMES run honours the flat start under **CGMES start values** = `auto`;\nan explicit `sv` on the Case page still starts from the delivery state\n([Power flow configuration](SPARLECTRADOCS/powerflow_configuration/#pf-solver-core)).\n\n### Case-specific settings\n\nA successful result page offers **Save settings for this case**: only the\nform options of that run plus traceability metadata go into a sanitized\nYAML profile below the output root (not `effective_config.yaml`, solver\ninternals, artifact paths or convergence diagnostics). A non-converged run\nshows **Save these settings anyway** and records that override; nothing is\nsaved automatically. Reopening the case prefills the form from the profile\nwith a notice: defaults first, the global configuration untouched, only\neditable fields prefilled, and a manual edit wins for the submitted run.\n\nWith a case selected, every page (Case, Runs, Settings) shows the values a\nrun of that case will use: case settings over the configuration file over\nthe defaults. Without a case, the configuration file. **Show the\nconfiguration file's values** (`?config_view=1`) switches the Settings page\nto the file alone, **Show the case settings** back. A save with target\n\"this case\" writes what the form shows; a save to the configuration file\nsays how many of the saved keys the selected case overrides. Between configuration file and saved profile the last edit wins: a\nnewer YAML file takes precedence for the keys it sets on the next page load\n(the notice says so), other fields keep their saved values; a page refresh\nis enough.\n\nWith a Sparlectra Case Format file selected, the form is seeded from the\ncase file: it posts a value for every option it shows (explicit\noverrides, the highest precedence level), so selecting a case file moves\nits controls to the file's values, and the page says which settings came\nfrom the case. A saved settings profile for the case still wins over the\nfile, and any control the user edits wins over both.\n\n### Scenarios and N-1\n\nThe action row of the run form carries the N-1 controls: outage kind\n(branch/generator), **scenario source** (generated N-1 lists, or the\nscenarios block of an SCF case), **screening mode** (configured / off /\nflag / only) with a **margin** field (empty means the configured\n`contingency.screening.margin_pct`), and links to the weights editor and,\nfor SCF cases, the scenario editor. Screening is off by default\n([N-1 Contingency Analysis](SPARLECTRADOCS/contingency/)). The run\nsummary names the screened count and the case-list source; the result page\ntabulates the cases for every format (name, weight, convergence,\niterations, start, voltage envelope, worst loading, severity, islands, shed\nload, screened marker), ranked by severity with failures first and capped\nat 100, the linked CSV keeping the complete list in input order. A screened\nrow shows its one-step estimate (no full solve), a flagged row the estimate\nnext to the full-run values, a failed case its error text.\n\n**Weights.** The \"edit N-1 weights\" link next to the outage-kind selector\nopens a per-case weights editor. Weights live next to the case as\n`<case-stem>.contingency-weights.csv`, the two-column format\n`readContingencyWeightsCSV` parses; the file is hidden from the case list\nand deleted with the case. The editor seeds a table with the case's element\nnames and offers a raw-CSV text area and a file upload; an upload replaces\nthe existing file after validation, a malformed CSV is rejected with the\nline number. Rows left at `1.0` are omitted on save. A run picks the\nweights up whenever the file exists; names that match no element are\nreported in `run.log`, never fatal. A weight file applies to case-list runs\n(the outage-kind selector and the `n1_*` scenario sources); a scenario run\nfrom a case file's block or an external scenario JSON uses the per-scenario\n`weight` of the block and ignores the weight file. A weight only reorders\nthe severity ranking and never skips a case\n([N-1 Contingency Analysis](SPARLECTRADOCS/contingency/)).\n\nScenarios need an SCF case; for other formats the form offers the generated\nN-1 sources and says \"Scenarios need an SCF case; export this case as SCF\nfirst\" next to the export action. The **scenario editor** lists the open\ncase's scenarios (name, weight, op count; edit, duplicate, delete, new) and\nedits one as op rows: op (status/set/scale), target class, a component\nselector filled from the case as `id: name (from-to)` and filtered by\nclass, then the fields the op needs (value for status, field plus value for\nset, factor for scale). Validation is server side with the scenario rules;\nerrors name the scenario and op index, and a tap patch on a regulated\ntransformer is rejected with the controller named. **Save into case file**\nwrites the scenarios block through the SCF writer; nothing stays in the\nbrowser.\n\n### Diagnose\n\n**Diagnose** next to **Start PowerFlow run** evaluates the mismatch at the\ncase's own stored operating point (MATPOWER `VM`/`VA`, or the `SvVoltage`\nstate of a CGMES delivery) without a corrective Newton step. Every\nstart-value machine is forced off (`flatstart = false`,\n`start_projection = false`, `dc_seed_unconditional = false`,\n`start_current_iteration.enabled = false`, `apslf_start.enabled = false`,\nplus `max_iter = 1` and `qlimits.enabled = false`), so the reported residual\nreflects the imported model, not the start guess or the step control. The\nforced settings outrank the form and a case configuration file next to the\ncase. The run uses the normal pipeline (history, artifact viewer, the\n`diagnose.log` report) and adds `self_check.log` (forced settings, start\nresidual and, for CGMES, the count of buses without a usable `SvVoltage`,\nwhich start at the flat `1.0 pu / 0°` fallback), `self_check_residuals.csv`\n(per-bus P/Q residuals with SV coverage, transformer-terminal and shunt\ncounts) and `diagnose_self_check_config.yaml`. Programmatically:\n`run_fixed_reference_self_check`.\n\nOne step practically never converges; the residual is the measurement, so\nhistory and result page label the run **diagnosed** on a neutral badge (raw\nstatus in the tooltip) with a one-line explanation of the single iteration\nand non-zero mismatch. A diagnose run that could not run at all keeps the\nfailure vocabulary.\n\n### Short circuit\n\n**Short circuit** next to Diagnose evaluates the balanced three-phase\ncurrents (IEC 60909-0, `runShortCircuit!`) for every bus of a CGMES\ndelivery, maximum and minimum case in one run, without a power-flow solve.\nThe button is enabled only when the delivery carries short-circuit source\ndata (synchronous machines, feeder short-circuit currents or equivalent\nimpedances); the server checks the contents and otherwise disables it with a\ntooltip. The run writes `short_circuit_max.csv` and `short_circuit_min.csv`\n(per-bus `Ik''`, `Sk''`, `κ`, `i_p`, safety flag and reasons), a `run.log`\nwith the harvested-data coverage report and a summary row; rows with\ndefaulted or skipped data get a warning badge because a flagged `Ik''max`\nis a lower bound. A MATPOWER or DTF case carries no source data and fails\nwith `short_circuit_requires_cgmes`. A Sparlectra Case Format case runs on\nits own source entries, a PowSyBl case on its connected generators with\nthe reactances of the IIDM extension `generatorShortCircuit`\n([PowSyBl Import](SPARLECTRADOCS/powsybl_import/)). The rule for the source data of every\nformat is on Short-Circuit Analysis.\n\n### State estimation\n\nThe state-estimation section of the Runs page (`/powerflow#state-estimation`;\n`/stateestimation` redirects there) uses the shared case selection, selects a\nmeasurement set and runs observability (traffic light, structural-island\nnote), the WLS solve and the diagnostics of\n[State Estimation](SPARLECTRADOCS/state_estimation/). Uploaded `.csv` files are offered\nwhen the content sniff finds the v1 version comment. Preselection: only a set\nbound to the selected case is preselected (cases with a bound set are\nstarred, foreign sets are labeled); a case file with its own measurements\noffers those first and says how many it carries, otherwise the page asks for\na set. A set bound to the case an SCF file was exported from stays usable,\nbecause the file records its source.\n\nEvery generation and every \"add noise\" writes a new file with a time stamp\n(`<case>.measurements.<yyyymmdd-HHMMSS>.csv`, `<case>.noisy.<stamp>.csv`)\nand arms it for the next run; on a later visit the newest set bound to the\ncase is armed. **Delete measurement file** next to the download link\nremoves the armed set (measurement sets only, never a case file).\nThe set tab offers download, re-upload and an inline editor (small files,\nsaved atomically, first line must stay the version comment) and renders the\n`sparlectra-taps v1` tap table of a generated file, offered for download with\nthe file. The page names the state of a carried set (ideal or measured);\n**Add noise to this set** perturbs each value with the sigma its own row\ndeclares. **Reset saved settings** under the generator deletes the per-case\nsettings sidecar. **Estimate taps** (on by default) releases every\nin-service transformer with a ratio tap changer except machine transformers;\nthe result page shows the per-transformer table (model step, fixed step and\nthe change between them; frozen taps carry their reason in the status\ncolumn) and the fixation J drop. The form warns when\n`k_suppress < k_eliminate`, because suppressed rows then rarely reach the\nelimination.\n\nArtifacts (`measurements.csv`, `se_diagnostics.md`, `se_view.md`,\n`se_state.csv`, `shunt_estimates.csv`, `se_tap_estimates.csv`,\n`se_bad_data.csv`, `se_deltas.csv`) land in the run history with kind `se`.\nThe result page offers **Run power flow from this estimate** and the\ntopology hypothesis test behind a button (writes `topology_hypotheses.md`).\nThe summary shows `J`, the expected value (`E[J] = dof` for healthy noise)\nand the Wilson-Hilferty 3-sigma band verdict (with the `:high`/`:low`\nreason), always for the state after the elimination: eliminated rows are\nout of `J` and `dof`, suppressed rows stay in the honest `J` and surface as\n`J_active`.\n\n## Running jobs\n\nA submission starts a background worker and redirects to the status page:\nelapsed time as `HH:MM:SS` beside the status, and a details table with\n`elapsed_seconds`, requested and resolved case paths, start time and a\nmanual refresh link. Queued, running and aborting\npages refresh every two seconds (these `autorefresh=1` requests are not\nlogged as user actions); terminal pages stop refreshing. The start page and\nthe run history show a banner with **Open status** and **Abort** while a\njob is queued or running. A queued, running or aborting run cannot be\ndeleted; a terminal one can.\n\nFor large cases, the result page, `run.log`, `result.json` and\n`performance.log` show time per phase (reader, network builder, solver,\nartifacts).\n\n### Abort\n\nA queued or running job can be aborted from its status page or from the\nbanner on the start page. Abort is cooperative: an operation that cannot be\ninterrupted, such as a sparse factorization, finishes first; the status page\nshows the current phase. An aborted run keeps its run directory and is never\nreported as success.\n\nIf a run stays in `aborting` for more than 60 s, the status page offers\n**Hard reset Web UI**. It marks the run invalid and stops the server.\nRestart with `julia --project=. start_webui.jl`.\n\n### Feedback\n\nFormulas on the documentation pages are rendered by a bundled copy of\nKaTeX (served from the package, no network needed).\n\nOne-off messages (validation errors, import summary) open as a dismissible\npopup. Recent errors stay listed on the **Last errors** page.\n\n## Results and artifacts\n\nEvery finished run gets a result page: run ID, schema version, status,\nconvergence and solution flags, iterations, final mismatch, reason and\nmessage, input paths, output directory and a **Solver** entry. Artifacts come from\n`list_powerflow_artifacts` and are resolved by exact name through\n`resolve_powerflow_artifact`, never by joining browser input to a path.\nA CSV artifact opens as a table (delimiter taken from the header line), a\nMarkdown report (`se_diagnostics.md`, `se_view.md`, DTF summaries) rendered;\n**Raw text** on the page shows the file as written. Other text artifacts\n(JSON, YAML, logs, HTML) open as escaped text in a scrollable panel that\nkeeps long lines; other files download, and every artifact page offers a\ndownload. **Download all artifacts as ZIP** packs\nthe exposed artifacts into `sparlectra_run_<run_id>_artifacts.zip`, skipping\nmissing optional artifacts and unsafe names.\n\n### Output modes\n\n- **Logfile output mode**: `classic` writes the result report plus a\n  compact timing and status summary (`solver_time`, `representative_time`,\n  iterations, final mismatch, outcome); `full` adds **Full run details** with the effective\n  typed configuration, artifact choices and status diagnostics. MATPOWER\n  `.m` runs also print the \"Original/Final effective MATPOWER import\n  options\" and \"MATPOWER auto-profile recommendations\" tables, because `.m`\n  files leave `shift_sign`, `shift_unit` and `ratio` ambiguous; DTF `.DAT`\n  runs never print them, so their shorter `run.log` is expected.\n- **Performance timing** (`off`, `compact`, `full`) writes\n  `performance.log` with the phases of one request (request parsing, case\n  resolution, configuration, case loading and network construction, solve,\n  postprocessing, artifact writing, solver and total time; `full` adds\n  internal profile entries). A run from the Web UI solves once; repeated\n  timing is the benchmark mode of `run_matpower_case` in a script\n  ([Performance Profiling](SPARLECTRADOCS/performance_profiling/#perf-benchmark)). Older\n  saved configurations with the former benchmark fields of the form are\n  cleaned by **Refresh configuration**, which names each removed field.\n- **Export case as CGMES delivery (EQ+TP+SSH+SV, ZIP)** writes the case as\n  one re-importable delivery into the run's artifacts, for every case format\n  and also on non-converged runs; see [CGMES Export](SPARLECTRADOCS/cgmes_export/).\n- **Write bus/branch CSV files** (API default off, because large networks\n  produce large files) writes `bus_voltages_complex.csv` (per bus `vm_pu`,\n  `va_deg`, numeric `v_re` and `v_im`, readable `v_complex`, nominal and\n  actual voltage, generation, load, Q-limit and control columns) and\n  `branch_flows.csv` (active and reactive power at both ends, losses,\n  rating, status, overload) from the `ACPFlowReport` rows.\n- **CSV format** is the machine-scope key `output.csv_format` (**Save\n  settings** writes it to the configuration file, a per-case save leaves it\n  out) and applies to every CSV of every run type, state estimation\n  included: `technical` (default: comma delimiter, decimal point, no\n  grouping), `excel_de` (semicolon, decimal comma, thousands dot),\n  `excel_us` (comma, decimal point, thousands comma, grouped numbers\n  quoted). The Excel formats avoid exponent notation where practical;\n  `v_complex` follows the decimal notation, `v_re`/`v_im` stay numeric.\n  Excel may still auto-convert identifiers like `1E5`; use **Data > From\n  Text/CSV** with text types when that matters.\n\n### Diagnostic artifacts\n\n`diagnose.log` is written by **Diagnose** or with `run_diagnostics = true`,\nnever by a normal run. On a non-converged run it is a report: \"Diagnosis\"\nnames the worst-mismatch bus and equation and classifies the mismatch trend\n(monotonic, oscillatory, stagnant, diverging to non-finite) and the autodamp\nhealth; \"Branch anomalies at worst-mismatch bus\" scans the incident branches\nfor zero impedance, off-nominal taps, large phase shifts or an outlying\nreactance; \"Recommendations\" closes with next steps. It reuses the Q-limit\nevent, PV-limit and limit-validation printers, and a diagnostic exception\nstays in the file without changing a successful result. Old run directories\nmay still hold `diagnose.txt`, which the viewer lists as well.\nA run that attempts the current-iteration pre-solve may add\n`current_iteration_start.log`: whether the candidate was attempted, accepted,\nrejected by a guard, or rejected with the original start values restored.\n\n### Comparing two runs\n\nTick **Compare** on two history rows (two runs of the same case under\ndifferent settings: a Q-limit mode, a solver, a start strategy) and press\n**Compare selected runs**; the page shows side by side:\n\n- case file, status, converged flag, iterations and final mismatch, with a\n  link to each result page;\n- the configuration keys the runs disagree on, read from their\n  `effective_config.yaml` (the `_config_sources` bookkeeping is left out);\n- the buses each run clamped, from `q_limit_events.csv`, and which only one\n  of them clamped;\n- total active and reactive losses from `branch_flows.csv`, with the\n  difference;\n- the largest voltage deviation and the ten buses that differ most, when both\n  runs wrote `bus_voltages_complex.csv` (the detailed CSV export).\n\nEverything comes from what the runs wrote, so earlier sessions compare as\nwell; exactly two runs are required. The box appears only on finished\npower-flow runs (plain, diagnose, or started from an estimate) whose result\nis still on disk, not on state estimation, short circuit, N-1 or import\nanalysis runs. Network size is not a criterion (the same case with an\nexternal-grid source and with a slack is exactly the pair one wants); the\npage says so when the runs share no bus.\n\n## Run history and operation log\n\n`start_sparlectra_webui` refreshes `powerflow_runs_index.json` under the\noutput root before serving, so runs of an earlier process appear at once;\n**Refresh registry** reloads by hand, and missing, corrupt or unsafe entries\nare skipped without hiding the valid ones. History is newest first: local\ndate and time, run ID, status text and badge (green successful, yellow\nwarning/partial, red failed, gray unknown, blue running, always with visible\ntext), solver summary fields and actions; indexes without timestamps use\nthe `result.json` modification time. **Case file** and **Config file** show\nthe file name, the full path in the tooltip. **Delete** removes one run,\n**Delete all runs** every registered run under the configured root; both\nupdate registry and index and delete only validated run directories, never\nunrelated files.\n\nThe **Operation Log** page shows and downloads `logs/webui_operations.jsonl`,\na JSON Lines support log independent of the run directories, for error\nreports. It records page opens, submissions and validation failures, run\nlifecycle changes, artifact views and downloads, abort requests, history\nrefreshes, deletions, shutdown requests and enabled diagnostics or timing\nmodes, not static CSS or image requests. Entries carry route, method,\nstatus, run, case, artifact, message and timing fields where available,\n`sparlectra_version` and a UTC timestamp `yyyy-mm-ddTHH:MM:SS.sssZ`, never\nfile contents or configuration bodies. Logging is best effort and cannot\nfail a request; phase events stay high level, per-iteration timings belong\nto `performance.log`.\n\nEvery start drops entries older than `webui.operation_log_retention_days`\n(default 10, `0` keeps only the current session) from every operation log\nit knows, including one a service call wrote next to the runs;\n`SPARLECTRA_WEBUI_OPERATION_LOG_RETENTION_DAYS` overrides the key for\nheadless runs. On append, a log above 1 MiB is compacted and more than\n5,000 valid entries are cut to the newest 1,000, dropping malformed lines.\nThe page states its size (entries and kB) and offers **Clear operation\nlog**, which empties the file and writes one entry recording that. A large\nlog is a matter of entry count, not age; a retention of two or three days\nis the lasting remedy.\n\n## Configuration\n\n**Check configuration** and **Refresh configuration** bring a local file up\nto a template that gained options. Check is a dry run against `src/config/configuration.yaml.example`: missing keys,\nknown deprecated aliases, duplicate YAML keys and a preview of the refreshed\nYAML, nothing written. Refresh keeps existing values, adds missing keys with\ntemplate defaults and may normalize deprecated aliases (start-mode settings,\nlegacy `matpower_*` Q-limit mode names); it never runs at startup, writes a\ntimestamped backup first, refuses on duplicate keys, and offers uploaded or\npasted YAML as a download instead of rewriting it.\n\nThe **Configuration Editor** opens the active YAML in a textarea, validates\nit with the same parser and duplicate-key checks, writes only after\nvalidation with a timestamped backup, and warns when a case configuration\nfile still overrides the global YAML through the prefilled form. After a\nsave the server reloads the file, so the form shows the new values on the\nnext page load.\n\nForm values override the YAML configuration; the order is described in\n[Configuration](SPARLECTRADOCS/configuration/). Each run writes `effective_config.yaml`.\n**Ignore Web UI settings and use configuration defaults** runs with the YAML\nvalues only. `model.auto_profile: apply` may still adjust MATPOWER import\nconventions after form and API values are assembled;\n`effective_config.yaml` records that.\n\n**Help** in the header opens the help ([Web UI](/help)) inside the Web\nUI, as shipped with the running version, and the help links to this\nreference; **Project Docs** opens the published documentation\n(`webui.docs_base_url`). The help pages behind the **?** icons carry a\nsection of the help or of this reference in full, or the lead paragraph\nof a library section with the link to it.\n\n### Search the help\n\nThe search field stands at the top of the help and of this reference and\nin the header of every page. It looks through the help, the reference and\nthe help pages of the controls, headings and tables included. Every word\nentered must occur, a part of a word is enough, upper and lower case do\nnot matter. The hits appear while you type: the heading of the section\nas a link to its place, below it a line of the text with the words\nmarked, hits in a heading first. `/` puts the cursor into the search\nfield, Enter opens the first hit, Esc closes the list. Without a hit the\npage says so and links to the published documentation, which has a search\nof its own. The search runs on the own machine on an index that ships\nwith the application; it needs no network. With scripts switched off in\nthe browser the field is a plain form that answers with a page of hits.\n\n## Shutdown\n\nThe server stops with **Stop Web UI**, `close(server)` or `Ctrl+C`. With\n`auto_shutdown_on_browser_close = true` it also stops when the browser has been\ngone for `browser_heartbeat_timeout_seconds` (best effort).\n\n## Limits\n\nThe Web UI is local by design: loopback only, no authentication, no\npublic-server mode, no database. There is no push channel (WebSockets or\nserver-sent events), so a running job reports its phase through the page;\nthere is no topology view and no plotting. The HTTP layer is a compact Julia\n`Sockets` implementation, chosen to avoid a web-framework dependency.\n"
const WEBUI_HELP_REFERENCE_ANCHORS = Dict{String,String}(
  "Case selector" => "webui-case-selector",
  "Import case files" => "webui-import-case-files",
  "PowSyBl IIDM files" => "webui_powsybl",
  "CGMES test configurations" => "webui_cgmes_test_configurations",
  "Form options" => "webui-form-options",
  "Flat start" => "webui-flat-start",
  "Output modes" => "webui-output-modes",
  "Configuration" => "webui-configuration",
  "Search the help" => "webui_help_search",
)

# The search index of the help: one entry per section of the two help
# pages and per help topic of a control, the text without markup.
const WEBUI_HELP_SEARCH_INDEX = NamedTuple{(:title, :url, :kind, :text),Tuple{String,String,String,String}}[
  (title = "Start", url = "/help#start", kind = "help", text = "Install and start in one line. Julia is installed if it is missing: From an installed copy or a checkout: start_webui.sh and start_webui.bat do the same. The browser opens http://127.0.0.1:8080/powerflow . The first start prepares the environment once and offers to build a system image, which makes every later start fast (Sysimage). The questions of the installer, the start from the Julia REPL and the directories the Web UI uses are described in the reference."),
  (title = "Case formats at a glance", url = "/help#webui-case-formats", kind = "help", text = "Format How the case gets in Download possible Good to know MATPOWER ( .m ) Import case files , or type a name into Or type case file path Yes: a standard name such as case14.m or case118.m is fetched once from the MATPOWER project The download needs an internet connection the first time, afterwards the case is local CGMES Import case files with the delivery ZIP, or with the profile files (EQ, SSH, TP, SV) selected together Yes: cgmes:<alias fetches the ENTSO-E test configurations once (about 22 MB) Every uploaded delivery is checked for completeness; the aliases are listed under CGMES test configurations PowSyBl IIDM ( .xiidm ) Import case files No The file is read as it is; unpack a compressed file first. See PowSyBl IIDM files Sparlectra Case Format, power-grid-model ( .json ) Import case files , or Export as SCF case file from any selected case No Scenario files and the scenario editor need this format DTF ( .DAT ) Import case files No Experimental, for diagnostics and validation Shipped demo cases Already in the selector Not needed They work offline Nothing is downloaded without a name you typed. A selected or uploaded file is used as it is."),
  (title = "Loading a case", url = "/help#loading-a-case", kind = "help", text = "The Case page holds the case selector, the import, the exports and the import options of the selected format. - Existing case file lists the cases of the case directory and the shipped demo cases (Shipped Demo Cases). - Import case files takes several files at once and copies them into the case directory. It starts no calculation and never overwrites an existing file. - Or type case file path takes a name to download (see the table) or the path of a local file. - Case input format stays on Auto unless the extension does not say what the file is. - Export as SCF case file , Save case as and Download selected case write or deliver the case. Save case as keeps variants of one network side by side. Details: Case selector, Import case files, Save case as."),
  (title = "Running", url = "/help#running", kind = "help", text = "The Runs page starts the calculations for the selected case. Every start opens a status page that follows the run, and a running job can be aborted there. The options of a run are on the Settings page."),
  (title = "Power flow", url = "/help#power-flow", kind = "help", text = "Start PowerFlow run solves the network with the selected solver: Newton-Raphson, APSLF or the linear DC model. The start values come from the case unless Flat start is set. Reactive limits of the machines are enforced in the mode chosen under Q-limit handling . See Power-Flow Configuration."),
  (title = "Diagnose", url = "/help#diagnose", kind = "help", text = "Diagnose evaluates the mismatch at the operating point the case brings along, without a corrective step. The result shows where the imported model does not balance, bus by bus. It is the first thing to run when a case does not converge. See Diagnose."),
  (title = "N-1", url = "/help#n-1", kind = "help", text = "The outage kind (branches or generators) selects the generated outage list; a case in the Sparlectra Case Format can carry scenarios of its own. The result ranks the cases by severity, failures first. Screening and weights are optional. See N-1 Contingency Analysis."),
  (title = "State estimation", url = "/help#state-estimation", kind = "help", text = "The state-estimation section selects a measurement set, or generates one from a solved power flow. A run checks the observability, estimates the state and reports suspicious measurements. The result page offers a power flow from the estimate. See State Estimation."),
  (title = "Short circuit", url = "/help#short-circuit", kind = "help", text = "Short circuit computes the balanced three-phase currents of every bus, maximum and minimum case, without a power-flow solve. The button is offered when the case carries source data; a run is succeeded only when every source carries its data. See Short-Circuit Analysis."),
  (title = "Results", url = "/help#results", kind = "help", text = "Every finished run has a result page with status, iterations, final mismatch and the list of its artifacts. A CSV artifact opens as a table, a Markdown report rendered, and Download all artifacts as ZIP packs the run. Run history lists the runs, newest first; two runs of the same case can be compared side by side. The Operation Log records what the Web UI did and is the file to attach to an error report. See Results and artifacts and Output modes."),
  (title = "Settings", url = "/help#settings", kind = "help", text = "The Settings page holds the options that do not belong to a single run: solver, start, output. Save settings writes either for the selected case or into the configuration file. With a case selected, every page shows the values a run of that case will use: case settings before the configuration file before the defaults. The Configuration Editor edits the file as text and checks it before it is saved. See Form options and Configuration. Help in the header opens this page inside the Web UI. Search the help looks through this page, the reference and the help of the controls. The ? next to a control opens the help of that control."),
  (title = "Limits", url = "/help#limits", kind = "help", text = "The Web UI is local by design: one user, the own machine, no login and no public-server mode. A running job reports its progress through the status page, which refreshes by itself. There is no topology view and no plotting."),
  (title = "Installation and start", url = "/help/reference#installation-and-start", kind = "reference", text = ""),
  (title = "One-line install", url = "/help/reference#one-line-install", kind = "reference", text = "Installs Julia if missing (via juliaup), downloads the latest tagged release into Sparlectra/ in the current directory, and starts the Web UI: The same scripts, tools/install_webui.sh / tools/install_webui.bat , ask three questions: - Update when an existing copy is older than the latest release; the old copy is kept as Sparlectra.old . - Sysimage : the installer leaves the sysimage build to the Web UI start and builds it only with SPARLECTRA_BUILD_SYSIMAGE=1 . - Desktop shortcut for restarting the Web UI: Windows Sparlectra Web UI.lnk ; Linux an application-menu entry plus a .desktop file on the desktop (GNOME needs a one-time right-click \"Allow Launching\"); macOS a desktop symlink. Unattended installs answer them with SPARLECTRA_UPDATE=1/0 , SPARLECTRA_BUILD_SYSIMAGE=1/0 and SPARLECTRA_CREATE_SHORTCUT=1/0 ."),
  (title = "Start script", url = "/help/reference#start-script", kind = "reference", text = "From a checkout or an installed copy: start_webui.sh / start_webui.bat run the same script (and point at the install script when Julia is missing); a Windows desktop shortcut is right-click start_webui.bat , Send to Desktop (create shortcut) . start_webui.jl delegates to start_sparlectra_webui . It first compares the direct dependencies in Project.toml with Manifest.toml , for the library and for app/ (four TOML reads, no package load); a missing dependency or manifest is resolved, instantiated and compiled once, with the time reported, and the next start compiles nothing. Manifest.toml is not tracked, so a fresh clone and an old manifest are both covered. julia --project=. start_webui.jl --env-only does only that first-start work. Then it looks for a usable sysimage and offers to build one; the build, its flags, the staleness rules and the Sysimage page are on Sysimage."),
  (title = "From the Julia REPL", url = "/help/reference#from-the-julia-repl", kind = "reference", text = "Such a session runs without the sysimage; how to start a REPL session on the image is on Sysimage. start_sparlectra_webui returns a SparlectraWebUIServer handle and serves as soon as the socket is bound, with no hidden warm-up run. open_browser = true opens an app-style window (Microsoft Edge, Google Chrome, Chromium or Brave); without one of them the URL http://127.0.0.1:8080/powerflow is logged. If the port is occupied, stop the old Julia process or pass another port ."),
  (title = "Directories and files", url = "/help/reference#directories-and-files", kind = "reference", text = "Results go to %LOCALAPPDATA%\\Sparlectra\\WebUI\\runs (Windows), \$XDG_STATE_HOME/sparlectra/webui/runs , default ~/.local/state/sparlectra/webui/runs (Linux) or ~/Library/Application Support/Sparlectra/WebUI/runs (macOS), created automatically; the operation log is in the sibling logs , downloaded and generated cases in the sibling data/mpower . That case directory is shared with ensure_casefile and the test suite; SPARLECTRA_LARGE_CASES_DIR overrides it for all three. The bundled warmup_case .jl precompile workloads are copied there on first start; the reserved warmup_ prefix hides them from the case selector (the sysimage workload runs the shipped sp_case5 / sp_case60 ). The first start copies the package configuration template to the user-writable config/configuration.yaml ; output_root = \"...\" and config_file = \"...\" override the defaults, and an explicit configuration file is never overwritten. Next to it the Web UI keeps: - configuration.template.yaml , the template the file was last aligned with: a key still at an old template default follows a new default at start (reported with key, old and new value; previous file kept as configuration.yaml.template-follow.bak ), a changed value stays; - configuration.yaml.user-keys.txt , the keys the Web UI itself saved (settings save, notice dismiss, configuration editor), which are never followed; deleting it or the template copy only loses that memory; - configuration.yaml.settings-save.bak , the backup of a settings save. The pages show the effective configuration, output root, case cache and operation log; the browser cannot change the output root. Header and footer show the logo ( docs/src/assets/logo.png ) and Sparlectra.version() ; header and operation log also name the package path and Git commit. The Info panel names the serving build ( sysimage, built ... or native session ) and links to the Sysimage page."),
  (title = "Importing cases", url = "/help/reference#importing-cases", kind = "reference", text = "The Case page carries the case chooser, upload, export and the per-format import options."),
  (title = "Case selector", url = "/help/reference#webui-case-selector", kind = "reference", text = "The selector lists the MATPOWER .m files and runnable DTF .DAT candidates of the case directory, the shipped demo cases sp_case5 to sp_case188 (Shipped Demo Cases), staged into the cache with their sidecars (per-case configuration, measurement CSVs) on first use, the three CGMES deliveries exported by Sparlectra itself ( data/cgmes_demo : sp_case14 , sp_case118 , sp_casePST , four profile files each) as <case _cgmes.zip , and PowSyBl IIDM files ( .xiidm , the four under data/powsybl included). Generated .jl cache files and warmup_ files are hidden. FOR002-like .DAT files are not primary cases; they go into the optional FOR002 reference field (absolute path, path in the case cache, or an offered candidate), used only for legacy reference comparison. Or type case file path overrides the selector: a bare name such as case14.m , case118.m or case9241pegase.m is downloaded into the case directory, an existing absolute or relative .m / .jl path is used as given; path-like missing inputs and URLs are rejected. A generated .jl cache file resolves back to its .m source (the bypass is recorded) and is rejected without one: large .jl literal cases can fail while Julia loads them, so .m stays the canonical source. Case input format defaults to Auto : MATPOWER files, CGMES deliveries (folders and ZIPs), PowSyBl IIDM files, and, where the DTF reader takes the file as a network, native DTF input. CGMES (ENTSO-E, folder or ZIP) forces the CGMES importer and is preselected for a .zip or a directory; PowSyBl (IIDM file) is preselected for those files and shows the PowSyBl import options (HVDC mode, remote regulation, slack choice, base MVA; see PowSyBl Import). A .xiidm file is read as it is. Sparlectra Case Format (.scf.json) and power-grid-model JSON (input.json) name the same reader (the sparlectra block is optional); Auto already sends every .json there, so they matter only when the extension does not say what the file is. The native DTF path is experimental, for diagnostics and validation; its Selected DTF outage labels/indices field takes one label or index at a time, and the result page shows a compact outage summary while the rows stay in artifacts. The format-bound option sections derive from the adapters' option structs, so the form cannot drift from what a conversion accepts; the Basic set (keys used in a workshop, or set in the example configuration without a default) renders directly, the rest and the DTF diagnostics on the Runs page fold into Advanced . Deleting a case removes all its companion files (configuration, weights, measurement CSVs). A collapsible MATPOWER acknowledgement next to the case inputs links to the project, its citation guidance and the 2011 paper DOI, and notes that ACTIVSg, PEGASE, RTE and other cases ask for additional citations in their headers."),
  (title = "Import case files", url = "/help/reference#webui-import-case-files", kind = "reference", text = "Import case files opens the native file picker and accepts several files at once: MATPOWER .m / .M , DTF .dat / .DAT , CGMES .zip deliveries, CGMES profile files ( .xml ) and PowSyBl IIDM files ( .xiidm ); the server validates the extension again. An uploaded .xiidm file runs as it is. Several .xml files (the EQ, SSH, TP and SV profiles of one delivery, such as a data/cgmes_demo folder) are packed into one <stem _cgmes.zip named after the common stem; the set must contain the EQ profile. A CGMES ZIP may hold nested ZIPs; the importer opens them in memory. A Sparlectra Case Format .json file is parsed and validated before it is stored. Importing is copy-only: no run, no run directory, no parsing of .m code. Files land in the case directory the form shows ( data/mpower , in a checkout too), the selector is rebuilt from disk, and the first runnable file may be preselected; the run still needs Start PowerFlow run . Limits: 100 MiB per file, 250 MiB per request. An existing file is never overwritten ( already exists , the other files still import), and names that would resolve outside the case directory are refused. Enter in Or type case file path resolves the value the same copy-only way: a bare case name via ensure_casefile , cgmes:<alias as below, or a full local path copied with the same validation; the file then appears in the Existing case file selector. Re-importing a saved set brings the .config.yaml sidecar along with the .scf.json and its measurement set(s) when all are selected together; the .yaml is validated as a case-scope configuration file ( scope: case ) before it is stored, and rejected otherwise."),
  (title = "Export and download", url = "/help/reference#export-and-download", kind = "reference", text = "The export row writes the open case as .scf.json or plain PGM .pgm.json , replacing a format suffix the case already carries ( case14.scf.json as PGM gives case14.pgm.json ); both products appear in the selector as runnable cases. Download selected case serves what the selector shows, after an export also the file just written: only plain files inside the case directory (bare name, or an absolute path pointing into it), compared by real path because the state directory can sit behind a symlink (Flatpak); anything outside, and a CGMES delivery directory, is refused."),
  (title = "Save case as", url = "/help/reference#save-case-as", kind = "reference", text = "Save case as , next to the export buttons (also linked from the State Estimation section), saves the current case under a new name instead of exporting in place: one network with several variants, one file per variant. It writes three files into the case directory: - <name .scf.json via exportSCF , with meta.case_name = <name and meta.source_reference noting the source case; a MATPOWER or DTF source is saved as SCF, the original file is never touched. - <name .config.yaml : the source case's saved case-scope settings merged with any unsaved change made on the page; the source case's sidecar file is never modified. - <name .measurements.csv for each measurement set bound to the source case, with its case: header rewritten to the new name; a second bound set is copied as <name _<original stem .measurements.csv . An existing <name .scf.json is refused unless \"overwrite\" is ticked. The optional \"start from the solved state\" checkbox solves the case once with the effective settings and writes the solved voltages as the copy's sparlectra.start_state . Installation-scope settings ( output. , benchmark. , runtime. , ...) are never written into the case configuration file. The file layout is described in Sparlectra Case Format."),
  (title = "PowSyBl IIDM files", url = "/help/reference#webui_powsybl", kind = "reference", text = "IIDM is the network format of the PowSyBl framework; its XML form has the extension .xiidm . The Web UI reads such a file as it is. Getting a network in. You have Do this no file yet pick one of the four shipped networks in the case selector: ieee14.xiidm , four_substations.xiidm , micro_grid_be.xiidm , ieee14_sc.xiidm a .xiidm file Import case files , select the file; it appears in the selector a compressed file ( .xiidm.bz2 , .gz ) unpack it first, then import the .xiidm What you can run. Power flow, Diagnose, state estimation (generate a measurement set first, or upload one), N-1 and short circuit, and the exports to the Sparlectra Case Format, MATPOWER and CGMES. Scenario files and the scenario editor address the components of a case file: export the network with Export as SCF case file and work on that file. Import options. With a PowSyBl case selected, the section Input format on the Case page shows five options. The defaults fit most files. Option Default Change it when System base MVA 100 you compare per-unit values with another tool that uses another base HVDC converters fixed injections never for now: the paired controller is not available for PowSyBl files Remote voltage regulation hold the target at the unit's own bus a generator regulates another bus and that bus shall be held exactly: choose the outer-loop control One slack per synchronous component on only the first component shall be solved Slack generator ids empty another unit than the automatically chosen one shall carry the reference; several ids are separated by semicolons What the import tells you. Every power-flow run on a PowSyBl case writes the artifact powsybl_import.log : how many elements of each type were read and built, every element that was skipped with the reason, and the generator that carries the reference of each synchronous component. The file's own voltages are the start of the solve. A file that was solved at other tap or shunt positions than it carries has a state that does not belong to its data: the import then starts flat, and the artifact says so. Short circuit. The sources are the connected generators. The reactance comes from the extension generatorShortCircuit of the file; a generator without it is counted with a default reactance, and the rows it feeds are marked. When no generator carries the extension or a rated power, the Short circuit button is not offered and its tooltip says why. Of the shipped networks ieee14_sc.xiidm carries complete data, micro_grid_be.xiidm runs on defaults with a warning, and ieee14.xiidm and four_substations.xiidm carry none. Not read. Compressed files, time series, and the regulation data of tap changers (a transformer stays at the step the file names). An IIDM export does not exist. Conventions and the complete list are on the page PowSyBl Import."),
  (title = "CGMES test configurations", url = "/help/reference#webui_cgmes_test_configurations", kind = "reference", text = "cgmes:<alias in Or type case file path downloads the official ENTSO-E test-configuration package once (about 22 MB) into the CGMES cache ( data/CGMES , overridable with SPARLECTRA_CGMES_CACHE ) and packs the requested configuration with its boundary set into cgmes_<alias .zip in the case directory. Aliases: microgrid_be , microgrid_nl , microgrid_assembled , smallgrid , smallgrid_nb , fullgrid , fullgrid_nb , realgrid . Repeated requests reuse the ZIP. If the download fails, the message names the path where the package can be placed by hand. The test data is never committed."),
  (title = "Import analysis on upload", url = "/help/reference#import-analysis-on-upload", kind = "reference", text = "Every uploaded CGMES delivery is checked at once: a complete one (or one whose boundary is found or supplied automatically) reports \"ready to compute\", an incomplete one gets the full import analysis: the message names the missing declared md:Model.DependentOn dependencies by model id (typically the boundary set), and the report (supplied models, dependency matching, unresolved-reference histogram, verdict) is written next to the case as <case .import_analysis.txt . The same analysis is appended to cgmes.log whenever a run's CGMES import aborts. Scripted use: the run mode import_analysis_mode of start_powerflow_run (a non-importable delivery ends as a failed run with reason import_analysis_not_importable ) or analyzeCGMES . Require boundary set (CGMES section, saved per case) submits cgmes_import.require_boundary ; unchecked, an incomplete delivery imports where possible, but buses without a resolvable BaseVoltage still abort, with the analysis explaining why."),
  (title = "Long actions on a case", url = "/help/reference#long-actions-on-a-case", kind = "reference", text = "Generating a measurement set or adding noise runs inside the request and can take a while on a large case (with critical measurements the generator re-reads the criticality after every removed row). Meanwhile the case is busy: a second generator action or a run is refused with a message and the buttons show a spinner; a queued or running run blocks the generator the same way."),
  (title = "Starting a run", url = "/help/reference#starting-a-run", kind = "reference", text = "Run-independent options live on the Settings page (solver, start, output and expert options, plus the configuration block: file display, check and refresh, saved case settings, the ignore switch) and reach a run through the configuration precedence ( resolve_config ): saving with target \"this case\" writes case-scope keys into the case's configuration file, target \"configuration file\" merges into the general YAML (backup .settings-save.bak ). The Runs page keeps the run parameters (modes, N-1 kind, scenario source, screening, DTF outage fields), the state-estimation section (estimator options and measurement-set selection submitted with se_mode ; measurement generator, set details with inline editors and measurement upload as fold-out tabs) and the N-1 editors as tabs: the scenario editor embeds directly (SCF cases), the weights editor loads on first open (seeding its element names builds the net once). The SE section uses the shared case selection. The measurement generator's fields are the generator options of State Estimation Measurements (sigmas per class, noise, gross errors, tap deviations, truth source, flow ends, passive nodes as zero-injection constraints, critical measurements ); the removed and critical rows are named in the set's comment lines and the estimation run log."),
  (title = "Form options", url = "/help/reference#webui-form-options", kind = "reference", text = "The settings and run forms offer: - case name or local path, configuration template file, the read-only output root (set only through start_sparlectra_webui(; output_root) ); - tolerance (decimals or scientific notation such as 1e-8 ; the exponent spinner, buttons or Up/Down keys, steps the exponent and keeps the mantissa: 1e-5 down gives 1e-6 , up gives 1e-4 ), maximum iterations, autodamping with its minimum factor; - Q-limit handling : the power_flow.qlimits.enabled checkbox and the enforcement-mode selector in one block; the selector also offers off and shows it whenever the handling is off. Below them, PV/PQ switching shows the hysteresis and the final check bound ( final_q_accept_pu , auto or a value in pu; the two settings the classic modes read), the first switching iteration ( start_iter ), the maximum switches per bus ( guard.max_switches ), freezing after repeated switching and the narrow-range guard switch ( guard.enabled ); Advanced holds the rest of power_flow.qlimits : start rule and auto threshold, cooldown, release voltage margin, the traced buses (bus numbers of the case file) and the buses locked to PQ (case bus numbers for a MATPOWER file, otherwise internal positions), the violation rule and threshold, bounded violations, and the narrow- and zero-range rules with their log line (Q-limit options and guard). Per-unit values take scientific notation like the tolerance, bus lists comma-separated numbers. Everything is grayed while the handling is off; the classic modes solve completely and then check the limits, again after every clamp, so they have no start iteration and gray what they do not read (they use the hysteresis and the final check bound); the guard switch grays the range rules, because the switch cap, freezing and the violation rule act without it. All of it saves to the configuration file and per case like every other run option; - Solver : one radio group power_flow_solver with the peer values rectangular (AC Newton-Raphson), apslf (AnalyticLoadFlow) and dc (linear screening model), writing power_flow.solver , power_flow.apslf. , power_flow.apslf_start. and power_flow.dc. (solver selection, DC power flow); radio buttons are never disabled, so the choice is always submitted; - wrong-branch detection mode, start angle and voltage modes; - Advanced start values : the current-iteration pre-solve fields ( power_flow.start_current_iteration. , guarded pre-solve), a preconditioner between start projection and Newton-Raphson, not a new start mode; - Merit-function line search : power_flow.merit.enabled , power_flow.merit.armijo_c1 , power_flow.merit.fallback_max_mismatch (options), requires power_flow.autodamp = true ; scale_p / scale_q / scale_v are YAML-only; a diagnostic run writes merit_linesearch.log ; - Non-convergence handling (Advanced): power_flow.rescue (retry ladder), power_flow.auto_slack (promote a reference when the case registers none; islands always find their own reference) and power_flow.dc.fallback (standalone DC result when AC has no solution), see Power-Flow Configuration; - MATPOWER import conventions: auto-profile mode ( off , recommend , apply ) plus transformer ratio, phase shift, bus shunt, PV voltage source and comparison reference; - logfile output mode, performance timing and post-run diagnostics. Only keys in GUI_EDITABLE_CONFIG_KEYS are submitted, the selected template is never modified, and each run writes effective_config.yaml . Every control carries a hover text with its operation and effect; a ? next to a control with something technical behind it (solver options, estimator diagnostics, Q-limits, formats) opens its help page in a new tab: the hint, the matching section of this documentation as shipped with the running version (the beginning of a long section), and a link to the section on the published site. webui.docs_base_url (configuration file) points that link at a local docs build or a pinned version. Back returns through the browser history with the entered values intact (fallback /powerflow ). Fields that do not apply to the selected solver or step control (autodamp/trust-region) are grayed out in place, not hidden; a grayed field is disabled and not submitted."),
  (title = "AC, APSLF and DC", url = "/help/reference#ac-apslf-and-dc", kind = "reference", text = "AC (Newton-Raphson, rectangular) reveals the start-value block ( Flat start , Use APSLF start values with its order field, Use DC start values ) and every AC-only option: tolerance, autodamping/merit/trust-region step control, Q-limit handling, maximum iterations, wrong-branch detection, start angle/voltage mode, the current-iteration pre-solve and the transformer tap-changer model. By default ( power_flow.start_mode.angle_mode = dc ) Newton-Raphson seeds its start angles from an internal DC pre-solve, controlled by Start angle mode ; that pre-solve is unrelated to the standalone DC solver. APSLF (AnalyticLoadFlow) reveals the APSLF solver options (highest coefficient/order, Padé evaluation, NR polish). Use APSLF start values in the Newton-Raphson block seeds the rectangular solver instead and is mutually exclusive with the APSLF solver (the configuration rejects both). An unchecked checkbox (APSLF, Q-limit, current-iteration) submits false rather than omitting the key. The APSLF solver needs the optional AnalyticLoadFlow.jl package in the server process; without it the run fails with a pre-solve error instead of falling back to the rectangular solver. DC replaces Newton-Raphson with the linear model (DC power flow), the dc value of power_flow.solver , and grays out every AC-only option above. A DC run uses the same job, abort, status, history and artifact machinery; the result page marks it with a DC solution badge next to Solver and the history column shows dc , so the implicit Vm = 1.0 pu and lossless flows are never taken for an AC result; iterations is 1 (a direct solve). The Solver column names the method that ran: the power-flow solver for a plain power flow, one started from an estimate and every contingency case; wls for a state estimation; iec60909 for a short circuit; empty for an import analysis (derived from the run kind when a run carries no method)."),
  (title = "Flat start", url = "/help/reference#webui-flat-start", kind = "reference", text = "power_flow.flatstart starts the Newton-Raphson solve at 1.0 pu and 0 degrees on every bus and ignores the imported start voltages (MATPOWER VM / VA , CGMES SvVoltage , SCF start_state ). Off, the imported values seed the solve; a delivery is built around its own operating point, so that is the better start for real networks and the default. This checkbox is the one start switch: while it is on, a run switches Use APSLF start values , Use DC start values , the current-iteration pre-solve and the start projection off and treats both start modes as classic , so the start really is flat and no projection or pre-solve moves it; the run log names what was switched off. The greyed controls keep their saved values and come back when the flat start is unchecked. A CGMES run honours the flat start under CGMES start values = auto ; an explicit sv on the Case page still starts from the delivery state (Power flow configuration)."),
  (title = "Case-specific settings", url = "/help/reference#case-specific-settings", kind = "reference", text = "A successful result page offers Save settings for this case : only the form options of that run plus traceability metadata go into a sanitized YAML profile below the output root (not effective_config.yaml , solver internals, artifact paths or convergence diagnostics). A non-converged run shows Save these settings anyway and records that override; nothing is saved automatically. Reopening the case prefills the form from the profile with a notice: defaults first, the global configuration untouched, only editable fields prefilled, and a manual edit wins for the submitted run. With a case selected, every page (Case, Runs, Settings) shows the values a run of that case will use: case settings over the configuration file over the defaults. Without a case, the configuration file. Show the configuration file's values ( ?config_view=1 ) switches the Settings page to the file alone, Show the case settings back. A save with target \"this case\" writes what the form shows; a save to the configuration file says how many of the saved keys the selected case overrides. Between configuration file and saved profile the last edit wins: a newer YAML file takes precedence for the keys it sets on the next page load (the notice says so), other fields keep their saved values; a page refresh is enough. With a Sparlectra Case Format file selected, the form is seeded from the case file: it posts a value for every option it shows (explicit overrides, the highest precedence level), so selecting a case file moves its controls to the file's values, and the page says which settings came from the case. A saved settings profile for the case still wins over the file, and any control the user edits wins over both."),
  (title = "Scenarios and N-1", url = "/help/reference#scenarios-and-n-1", kind = "reference", text = "The action row of the run form carries the N-1 controls: outage kind (branch/generator), scenario source (generated N-1 lists, or the scenarios block of an SCF case), screening mode (configured / off / flag / only) with a margin field (empty means the configured contingency.screening.margin_pct ), and links to the weights editor and, for SCF cases, the scenario editor. Screening is off by default (N-1 Contingency Analysis). The run summary names the screened count and the case-list source; the result page tabulates the cases for every format (name, weight, convergence, iterations, start, voltage envelope, worst loading, severity, islands, shed load, screened marker), ranked by severity with failures first and capped at 100, the linked CSV keeping the complete list in input order. A screened row shows its one-step estimate (no full solve), a flagged row the estimate next to the full-run values, a failed case its error text. Weights. The \"edit N-1 weights\" link next to the outage-kind selector opens a per-case weights editor. Weights live next to the case as <case-stem .contingency-weights.csv , the two-column format readContingencyWeightsCSV parses; the file is hidden from the case list and deleted with the case. The editor seeds a table with the case's element names and offers a raw-CSV text area and a file upload; an upload replaces the existing file after validation, a malformed CSV is rejected with the line number. Rows left at 1.0 are omitted on save. A run picks the weights up whenever the file exists; names that match no element are reported in run.log , never fatal. A weight file applies to case-list runs (the outage-kind selector and the n1_ scenario sources); a scenario run from a case file's block or an external scenario JSON uses the per-scenario weight of the block and ignores the weight file. A weight only reorders the severity ranking and never skips a case (N-1 Contingency Analysis). Scenarios need an SCF case; for other formats the form offers the generated N-1 sources and says \"Scenarios need an SCF case; export this case as SCF first\" next to the export action. The scenario editor lists the open case's scenarios (name, weight, op count; edit, duplicate, delete, new) and edits one as op rows: op (status/set/scale), target class, a component selector filled from the case as id: name (from-to) and filtered by class, then the fields the op needs (value for status, field plus value for set, factor for scale). Validation is server side with the scenario rules; errors name the scenario and op index, and a tap patch on a regulated transformer is rejected with the controller named. Save into case file writes the scenarios block through the SCF writer; nothing stays in the browser."),
  (title = "Diagnose", url = "/help/reference#diagnose", kind = "reference", text = "Diagnose next to Start PowerFlow run evaluates the mismatch at the case's own stored operating point (MATPOWER VM / VA , or the SvVoltage state of a CGMES delivery) without a corrective Newton step. Every start-value machine is forced off ( flatstart = false , start_projection = false , dc_seed_unconditional = false , start_current_iteration.enabled = false , apslf_start.enabled = false , plus max_iter = 1 and qlimits.enabled = false ), so the reported residual reflects the imported model, not the start guess or the step control. The forced settings outrank the form and a case configuration file next to the case. The run uses the normal pipeline (history, artifact viewer, the diagnose.log report) and adds self_check.log (forced settings, start residual and, for CGMES, the count of buses without a usable SvVoltage , which start at the flat 1.0 pu / 0° fallback), self_check_residuals.csv (per-bus P/Q residuals with SV coverage, transformer-terminal and shunt counts) and diagnose_self_check_config.yaml . Programmatically: run_fixed_reference_self_check . One step practically never converges; the residual is the measurement, so history and result page label the run diagnosed on a neutral badge (raw status in the tooltip) with a one-line explanation of the single iteration and non-zero mismatch. A diagnose run that could not run at all keeps the failure vocabulary."),
  (title = "Short circuit", url = "/help/reference#short-circuit", kind = "reference", text = "Short circuit next to Diagnose evaluates the balanced three-phase currents (IEC 60909-0, runShortCircuit! ) for every bus of a CGMES delivery, maximum and minimum case in one run, without a power-flow solve. The button is enabled only when the delivery carries short-circuit source data (synchronous machines, feeder short-circuit currents or equivalent impedances); the server checks the contents and otherwise disables it with a tooltip. The run writes short_circuit_max.csv and short_circuit_min.csv (per-bus Ik'' , Sk'' , κ , i_p , safety flag and reasons), a run.log with the harvested-data coverage report and a summary row; rows with defaulted or skipped data get a warning badge because a flagged Ik''max is a lower bound. A MATPOWER or DTF case carries no source data and fails with short_circuit_requires_cgmes . A Sparlectra Case Format case runs on its own source entries, a PowSyBl case on its connected generators with the reactances of the IIDM extension generatorShortCircuit (PowSyBl Import). The rule for the source data of every format is on Short-Circuit Analysis."),
  (title = "State estimation", url = "/help/reference#state-estimation", kind = "reference", text = "The state-estimation section of the Runs page ( /powerflow state-estimation ; /stateestimation redirects there) uses the shared case selection, selects a measurement set and runs observability (traffic light, structural-island note), the WLS solve and the diagnostics of State Estimation. Uploaded .csv files are offered when the content sniff finds the v1 version comment. Preselection: only a set bound to the selected case is preselected (cases with a bound set are starred, foreign sets are labeled); a case file with its own measurements offers those first and says how many it carries, otherwise the page asks for a set. A set bound to the case an SCF file was exported from stays usable, because the file records its source. Every generation and every \"add noise\" writes a new file with a time stamp ( <case .measurements.<yyyymmdd-HHMMSS .csv , <case .noisy.<stamp .csv ) and arms it for the next run; on a later visit the newest set bound to the case is armed. Delete measurement file next to the download link removes the armed set (measurement sets only, never a case file). The set tab offers download, re-upload and an inline editor (small files, saved atomically, first line must stay the version comment) and renders the sparlectra-taps v1 tap table of a generated file, offered for download with the file. The page names the state of a carried set (ideal or measured); Add noise to this set perturbs each value with the sigma its own row declares. Reset saved settings under the generator deletes the per-case settings sidecar. Estimate taps (on by default) releases every in-service transformer with a ratio tap changer except machine transformers; the result page shows the per-transformer table (model step, fixed step and the change between them; frozen taps carry their reason in the status column) and the fixation J drop. The form warns when k_suppress < k_eliminate , because suppressed rows then rarely reach the elimination. Artifacts ( measurements.csv , se_diagnostics.md , se_view.md , se_state.csv , shunt_estimates.csv , se_tap_estimates.csv , se_bad_data.csv , se_deltas.csv ) land in the run history with kind se . The result page offers Run power flow from this estimate and the topology hypothesis test behind a button (writes topology_hypotheses.md ). The summary shows J , the expected value ( E[J] = dof for healthy noise) and the Wilson-Hilferty 3-sigma band verdict (with the :high / :low reason), always for the state after the elimination: eliminated rows are out of J and dof , suppressed rows stay in the honest J and surface as J_active ."),
  (title = "Running jobs", url = "/help/reference#running-jobs", kind = "reference", text = "A submission starts a background worker and redirects to the status page: elapsed time as HH:MM:SS beside the status, and a details table with elapsed_seconds , requested and resolved case paths, start time and a manual refresh link. Queued, running and aborting pages refresh every two seconds (these autorefresh=1 requests are not logged as user actions); terminal pages stop refreshing. The start page and the run history show a banner with Open status and Abort while a job is queued or running. A queued, running or aborting run cannot be deleted; a terminal one can. For large cases, the result page, run.log , result.json and performance.log show time per phase (reader, network builder, solver, artifacts)."),
  (title = "Abort", url = "/help/reference#abort", kind = "reference", text = "A queued or running job can be aborted from its status page or from the banner on the start page. Abort is cooperative: an operation that cannot be interrupted, such as a sparse factorization, finishes first; the status page shows the current phase. An aborted run keeps its run directory and is never reported as success. If a run stays in aborting for more than 60 s, the status page offers Hard reset Web UI . It marks the run invalid and stops the server. Restart with julia --project=. start_webui.jl ."),
  (title = "Feedback", url = "/help/reference#feedback", kind = "reference", text = "Formulas on the documentation pages are rendered by a bundled copy of KaTeX (served from the package, no network needed). One-off messages (validation errors, import summary) open as a dismissible popup. Recent errors stay listed on the Last errors page."),
  (title = "Results and artifacts", url = "/help/reference#results-and-artifacts", kind = "reference", text = "Every finished run gets a result page: run ID, schema version, status, convergence and solution flags, iterations, final mismatch, reason and message, input paths, output directory and a Solver entry. Artifacts come from list_powerflow_artifacts and are resolved by exact name through resolve_powerflow_artifact , never by joining browser input to a path. A CSV artifact opens as a table (delimiter taken from the header line), a Markdown report ( se_diagnostics.md , se_view.md , DTF summaries) rendered; Raw text on the page shows the file as written. Other text artifacts (JSON, YAML, logs, HTML) open as escaped text in a scrollable panel that keeps long lines; other files download, and every artifact page offers a download. Download all artifacts as ZIP packs the exposed artifacts into sparlectra_run_<run_id _artifacts.zip , skipping missing optional artifacts and unsafe names."),
  (title = "Output modes", url = "/help/reference#webui-output-modes", kind = "reference", text = "- Logfile output mode : classic writes the result report plus a compact timing and status summary ( solver_time , representative_time , iterations, final mismatch, outcome); full adds Full run details with the effective typed configuration, artifact choices and status diagnostics. MATPOWER .m runs also print the \"Original/Final effective MATPOWER import options\" and \"MATPOWER auto-profile recommendations\" tables, because .m files leave shift_sign , shift_unit and ratio ambiguous; DTF .DAT runs never print them, so their shorter run.log is expected. - Performance timing ( off , compact , full ) writes performance.log with the phases of one request (request parsing, case resolution, configuration, case loading and network construction, solve, postprocessing, artifact writing, solver and total time; full adds internal profile entries). A run from the Web UI solves once; repeated timing is the benchmark mode of run_matpower_case in a script (Performance Profiling). Older saved configurations with the former benchmark fields of the form are cleaned by Refresh configuration , which names each removed field. - Export case as CGMES delivery (EQ+TP+SSH+SV, ZIP) writes the case as one re-importable delivery into the run's artifacts, for every case format and also on non-converged runs; see CGMES Export. - Write bus/branch CSV files (API default off, because large networks produce large files) writes bus_voltages_complex.csv (per bus vm_pu , va_deg , numeric v_re and v_im , readable v_complex , nominal and actual voltage, generation, load, Q-limit and control columns) and branch_flows.csv (active and reactive power at both ends, losses, rating, status, overload) from the ACPFlowReport rows. - CSV format is the machine-scope key output.csv_format ( Save settings writes it to the configuration file, a per-case save leaves it out) and applies to every CSV of every run type, state estimation included: technical (default: comma delimiter, decimal point, no grouping), excel_de (semicolon, decimal comma, thousands dot), excel_us (comma, decimal point, thousands comma, grouped numbers quoted). The Excel formats avoid exponent notation where practical; v_complex follows the decimal notation, v_re / v_im stay numeric. Excel may still auto-convert identifiers like 1E5 ; use Data From Text/CSV with text types when that matters."),
  (title = "Diagnostic artifacts", url = "/help/reference#diagnostic-artifacts", kind = "reference", text = "diagnose.log is written by Diagnose or with run_diagnostics = true , never by a normal run. On a non-converged run it is a report: \"Diagnosis\" names the worst-mismatch bus and equation and classifies the mismatch trend (monotonic, oscillatory, stagnant, diverging to non-finite) and the autodamp health; \"Branch anomalies at worst-mismatch bus\" scans the incident branches for zero impedance, off-nominal taps, large phase shifts or an outlying reactance; \"Recommendations\" closes with next steps. It reuses the Q-limit event, PV-limit and limit-validation printers, and a diagnostic exception stays in the file without changing a successful result. Old run directories may still hold diagnose.txt , which the viewer lists as well. A run that attempts the current-iteration pre-solve may add current_iteration_start.log : whether the candidate was attempted, accepted, rejected by a guard, or rejected with the original start values restored."),
  (title = "Comparing two runs", url = "/help/reference#comparing-two-runs", kind = "reference", text = "Tick Compare on two history rows (two runs of the same case under different settings: a Q-limit mode, a solver, a start strategy) and press Compare selected runs ; the page shows side by side: - case file, status, converged flag, iterations and final mismatch, with a link to each result page; - the configuration keys the runs disagree on, read from their effective_config.yaml (the _config_sources bookkeeping is left out); - the buses each run clamped, from q_limit_events.csv , and which only one of them clamped; - total active and reactive losses from branch_flows.csv , with the difference; - the largest voltage deviation and the ten buses that differ most, when both runs wrote bus_voltages_complex.csv (the detailed CSV export). Everything comes from what the runs wrote, so earlier sessions compare as well; exactly two runs are required. The box appears only on finished power-flow runs (plain, diagnose, or started from an estimate) whose result is still on disk, not on state estimation, short circuit, N-1 or import analysis runs. Network size is not a criterion (the same case with an external-grid source and with a slack is exactly the pair one wants); the page says so when the runs share no bus."),
  (title = "Run history and operation log", url = "/help/reference#run-history-and-operation-log", kind = "reference", text = "start_sparlectra_webui refreshes powerflow_runs_index.json under the output root before serving, so runs of an earlier process appear at once; Refresh registry reloads by hand, and missing, corrupt or unsafe entries are skipped without hiding the valid ones. History is newest first: local date and time, run ID, status text and badge (green successful, yellow warning/partial, red failed, gray unknown, blue running, always with visible text), solver summary fields and actions; indexes without timestamps use the result.json modification time. Case file and Config file show the file name, the full path in the tooltip. Delete removes one run, Delete all runs every registered run under the configured root; both update registry and index and delete only validated run directories, never unrelated files. The Operation Log page shows and downloads logs/webui_operations.jsonl , a JSON Lines support log independent of the run directories, for error reports. It records page opens, submissions and validation failures, run lifecycle changes, artifact views and downloads, abort requests, history refreshes, deletions, shutdown requests and enabled diagnostics or timing modes, not static CSS or image requests. Entries carry route, method, status, run, case, artifact, message and timing fields where available, sparlectra_version and a UTC timestamp yyyy-mm-ddTHH:MM:SS.sssZ , never file contents or configuration bodies. Logging is best effort and cannot fail a request; phase events stay high level, per-iteration timings belong to performance.log . Every start drops entries older than webui.operation_log_retention_days (default 10, 0 keeps only the current session) from every operation log it knows, including one a service call wrote next to the runs; SPARLECTRA_WEBUI_OPERATION_LOG_RETENTION_DAYS overrides the key for headless runs. On append, a log above 1 MiB is compacted and more than 5,000 valid entries are cut to the newest 1,000, dropping malformed lines. The page states its size (entries and kB) and offers Clear operation log , which empties the file and writes one entry recording that. A large log is a matter of entry count, not age; a retention of two or three days is the lasting remedy."),
  (title = "Configuration", url = "/help/reference#webui-configuration", kind = "reference", text = "Check configuration and Refresh configuration bring a local file up to a template that gained options. Check is a dry run against src/config/configuration.yaml.example : missing keys, known deprecated aliases, duplicate YAML keys and a preview of the refreshed YAML, nothing written. Refresh keeps existing values, adds missing keys with template defaults and may normalize deprecated aliases (start-mode settings, legacy matpower_ Q-limit mode names); it never runs at startup, writes a timestamped backup first, refuses on duplicate keys, and offers uploaded or pasted YAML as a download instead of rewriting it. The Configuration Editor opens the active YAML in a textarea, validates it with the same parser and duplicate-key checks, writes only after validation with a timestamped backup, and warns when a case configuration file still overrides the global YAML through the prefilled form. After a save the server reloads the file, so the form shows the new values on the next page load. Form values override the YAML configuration; the order is described in Configuration. Each run writes effective_config.yaml . Ignore Web UI settings and use configuration defaults runs with the YAML values only. model.auto_profile: apply may still adjust MATPOWER import conventions after form and API values are assembled; effective_config.yaml records that. Help in the header opens the help (Web UI) inside the Web UI, as shipped with the running version, and the help links to this reference; Project Docs opens the published documentation ( webui.docs_base_url ). The help pages behind the ? icons carry a section of the help or of this reference in full, or the lead paragraph of a library section with the link to it."),
  (title = "Search the help", url = "/help/reference#webui_help_search", kind = "reference", text = "The search field stands at the top of the help and of this reference and in the header of every page. It looks through the help, the reference and the help pages of the controls, headings and tables included. Every word entered must occur, a part of a word is enough, upper and lower case do not matter. The hits appear while you type: the heading of the section as a link to its place, below it a line of the text with the words marked, hits in a heading first. / puts the cursor into the search field, Enter opens the first hit, Esc closes the list. Without a hit the page says so and links to the published documentation, which has a search of its own. The search runs on the own machine on an index that ships with the application; it needs no network. With scripts switched off in the browser the field is a plain form that answers with a page of hits."),
  (title = "Shutdown", url = "/help/reference#shutdown", kind = "reference", text = "The server stops with Stop Web UI , close(server) or Ctrl+C . With auto_shutdown_on_browser_close = true it also stops when the browser has been gone for browser_heartbeat_timeout_seconds (best effort)."),
  (title = "Limits", url = "/help/reference#limits", kind = "reference", text = "The Web UI is local by design: loopback only, no authentication, no public-server mode, no database. There is no push channel (WebSockets or server-sent events), so a running job reports its phase through the page; there is no topology view and no plotting. The HTTP layer is a compact Julia Sockets implementation, chosen to avoid a web-framework dependency."),
  (title = "HVDC converters", url = "/help/cgmes_import.hvdc_mode", kind = "control", text = "HVDC converter model: fixed injections reproduce the delivery snapshot; a paired controller couples both converters of a link and makes the transfer steerable. The keys that steer a CGMES import: where the delivery is, the system base, whether unresolved boundary references fail the import, and the per-element handling described below. The Web UI carries the ones a delivery is usually adjusted with."),
  (title = "Infer missing base voltages", url = "/help/cgmes_import.infer_base_voltages", kind = "control", text = "Reconstruct missing nominal voltages from SV voltages and transformer ratings when the delivery has no BaseVoltage catalog. Pair with an unchecked boundary set. The keys that steer a CGMES import: where the delivery is, the system base, whether unresolved boundary references fail the import, and the per-element handling described below. The Web UI carries the ones a delivery is usually adjusted with."),
  (title = "Require boundary set", url = "/help/cgmes_import.require_boundary", kind = "control", text = "Fail the CGMES import when topology references stay unresolved (boundary set missing). Uncheck to import an incomplete delivery anyway. The keys that steer a CGMES import: where the delivery is, the system base, whether unresolved boundary references fail the import, and the per-element handling described below. The Web UI carries the ones a delivery is usually adjusted with."),
  (title = "CGMES start values", url = "/help/cgmes_import.start_values", kind = "control", text = "auto starts from the delivery's SvVoltage state when it carries one, else flat; sv always uses the imported state, flat always starts flat. The keys that steer a CGMES import: where the delivery is, the system base, whether unresolved boundary references fail the import, and the per-element handling described below. The Web UI carries the ones a delivery is usually adjusted with."),
  (title = "Screening margin (percent)", url = "/help/contingency.screening.margin_pct", kind = "control", text = "An outage is solved in full when its estimate comes within this margin of a loading or voltage limit (default 10). With screening_mode = :flag (keyword on runContingencies! and runScenarios! , or contingency.screening.mode for the service and the Web UI) every non-islanding single outage is first estimated with one Woodbury-corrected Newton step on the factorized base Jacobian; only scenarios whose estimate comes within screening.margin_pct (default 10) of a limit get the full solve. Switch it on only after checking, on your own network, the screening share and that the flagged margins carry the violations (the reported screened count and reason breakdown)."),
  (title = "N-1 screening", url = "/help/contingency.screening.mode", kind = "control", text = "off: every outage solved in full. flag: estimate each outage first, solve only those near a limit. only: estimates. Check the share once. With screening_mode = :flag (keyword on runContingencies! and runScenarios! , or contingency.screening.mode for the service and the Web UI) every non-islanding single outage is first estimated with one Woodbury-corrected Newton step on the factorized base Jacobian; only scenarios whose estimate comes within screening.margin_pct (default 10) of a limit get the full solve. Switch it on only after checking, on your own network, the screening share and that the flagged margins carry the violations (the reported screened count and reason breakdown)."),
  (title = "Write solution into MATPOWER export", url = "/help/matpower_export.write_solution", kind = "control", text = "Write the solved bus VM/VA state and the branch flow columns into the MATPOWER export. Off exports a pure model file with flat voltages. The keys of a MATPOWER run: the case selectors, the import profile that recommends or applies the conventions a case needs, the conversion switches (phase-shift unit and sign, tap ratio, PV voltage source, shunt and tap-changer model, generator controllers), the solution export and the network preallocation."),
  (title = "Apply bus names", url = "/help/matpower_import.apply_bus_names", kind = "control", text = "Use the case file's mpc.bus_name entries as bus names in results and logs instead of numeric BUS_I ids. Requires a bus_name block matching the bus count. The keys of a MATPOWER run: the case selectors, the import profile that recommends or applies the conventions a case needs, the conversion switches (phase-shift unit and sign, tap ratio, PV voltage source, shunt and tap-changer model, generator controllers), the solution export and the network preallocation."),
  (title = "Voltage reference comparison", url = "/help/matpower_import.compare_voltage_reference", kind = "control", text = "Voltage reference used when results are compared with the case data: bus VM, generator VG, the imported setpoint, or hybrid when VM and VG disagree. The keys of a MATPOWER run: the case selectors, the import profile that recommends or applies the conventions a case needs, the conversion switches (phase-shift unit and sign, tap ratio, PV voltage source, shunt and tap-changer model, generator controllers), the solution export and the network preallocation."),
  (title = "DC-line mode", url = "/help/matpower_import.matpower_dcline_mode", kind = "control", text = "Model of active mpc.dcline rows: pf_injections adds two fixed terminal injections per row; paired_control also couples each pair as a steerable HVDC link. The keys of a MATPOWER run: the case selectors, the import profile that recommends or applies the conventions a case needs, the conversion switches (phase-shift unit and sign, tap ratio, PV voltage source, shunt and tap-changer model, generator controllers), the solution export and the network preallocation."),
  (title = "PV voltage source", url = "/help/matpower_import.pv_voltage_source", kind = "control", text = "Source of the PV voltage setpoint: the generator VG (standard MATPOWER) or the bus VM; auto and strict_check use VG and warn when VG and VM differ. The keys of a MATPOWER run: the case selectors, the import profile that recommends or applies the conventions a case needs, the conversion switches (phase-shift unit and sign, tap ratio, PV voltage source, shunt and tap-changer model, generator controllers), the solution export and the network preallocation."),
  (title = "Transformer ratio convention", url = "/help/matpower_import.ratio", kind = "control", text = "Interpretation of the branch ratio column: normal is the standard MATPOWER convention, reciprocal inverts it. Change it only for a known alternate convention. The keys of a MATPOWER run: the case selectors, the import profile that recommends or applies the conventions a case needs, the conversion switches (phase-shift unit and sign, tap ratio, PV voltage source, shunt and tap-changer model, generator controllers), the solution export and the network preallocation."),
  (title = "Phase-shift sign", url = "/help/matpower_import.shift_sign", kind = "control", text = "Sign convention of the phase-shift column, 1 or -1. Flip it only to align with another tool's convention. The keys of a MATPOWER run: the case selectors, the import profile that recommends or applies the conventions a case needs, the conversion switches (phase-shift unit and sign, tap ratio, PV voltage source, shunt and tap-changer model, generator controllers), the solution export and the network preallocation."),
  (title = "Phase-shift unit", url = "/help/matpower_import.shift_unit", kind = "control", text = "Unit of the phase-shift column, degrees or radians. A wrong declaration shifts every phase shifter. The keys of a MATPOWER run: the case selectors, the import profile that recommends or applies the conventions a case needs, the conversion switches (phase-shift unit and sign, tap ratio, PV voltage source, shunt and tap-changer model, generator controllers), the solution export and the network preallocation."),
  (title = "MATPOWER auto-profile", url = "/help/model.auto_profile", kind = "control", text = "Experimental scan of the stored voltages, off by default: recommend logs convention recommendations, apply changes only safe conventions with clear evidence. The keys of a MATPOWER run: the case selectors, the import profile that recommends or applies the conventions a case needs, the conversion switches (phase-shift unit and sign, tap ratio, PV voltage source, shunt and tap-changer model, generator controllers), the solution export and the network preallocation."),
  (title = "Bus-shunt model", url = "/help/model.bus_shunt_model", kind = "control", text = "Interpretation of bus shunts: constant admittance (default) or a voltage-dependent injection. Change it only with residual evidence. The keys of a MATPOWER run: the case selectors, the import profile that recommends or applies the conventions a case needs, the conversion switches (phase-shift unit and sign, tap ratio, PV voltage source, shunt and tap-changer model, generator controllers), the solution export and the network preallocation."),
  (title = "Tap-changer model", url = "/help/model.tap_changer_model", kind = "control", text = "Tap-changer model applied to all transformers after import: ideal, or impedance correction that scales R and X with the tap position. The keys of a MATPOWER run: the case selectors, the import profile that recommends or applies the conventions a case needs, the conversion switches (phase-shift unit and sign, tap ratio, PV voltage source, shunt and tap-changer model, generator controllers), the solution export and the network preallocation."),
  (title = "Logfile output mode", url = "/help/output.logfile_results", kind = "control", text = "Detail of the solved result tables in run.log: off, compact, classic (result report plus timing summary) or full (adds the effective configuration). What a run writes besides its result: the console summary and its diagnostics, the log files, and the detailed CSV export with its writer settings."),
  (title = "APSLF convergence radius", url = "/help/power_flow.apslf.convergence_radius", kind = "control", text = "Evaluate the APSLF convergence radius, the distance of the nearest Padé pole to the evaluation point. Costs about as much as the solve; shown with the result. power_flow.solver selects the executing solver; power_flow.method fixes the AC formulation family (always rectangular ). apslf routes the run through the external-solver bridge ( buildPfModel , solvePf(ApslfSolver(...)) , applyPfSolution! ) to AnalyticLoadFlow.jl's analytic power-series solver (a required dependency; see apslf_solver )."),
  (title = "APSLF NR polish", url = "/help/power_flow.apslf.nr_polish", kind = "control", text = "Run a Newton-Raphson polishing step on the APSLF series result. Default off: the series alone is a load-flow solution. power_flow.solver selects the executing solver; power_flow.method fixes the AC formulation family (always rectangular ). apslf routes the run through the external-solver bridge ( buildPfModel , solvePf(ApslfSolver(...)) , applyPfSolution! ) to AnalyticLoadFlow.jl's analytic power-series solver (a required dependency; see apslf_solver )."),
  (title = "APSLF highest coefficient (order)", url = "/help/power_flow.apslf.order", kind = "control", text = "Highest power-series coefficient computed by the APSLF solver. Higher orders help stressed cases but increase the solve cost. power_flow.solver selects the executing solver; power_flow.method fixes the AC formulation family (always rectangular ). apslf routes the run through the external-solver bridge ( buildPfModel , solvePf(ApslfSolver(...)) , applyPfSolution! ) to AnalyticLoadFlow.jl's analytic power-series solver (a required dependency; see apslf_solver )."),
  (title = "APSLF Padé evaluation", url = "/help/power_flow.apslf.use_pade", kind = "control", text = "Evaluate the voltage series via Padé approximants instead of direct Taylor summation. Usually better accuracy per order at a small overhead. power_flow.solver selects the executing solver; power_flow.method fixes the AC formulation family (always rectangular ). apslf routes the run through the external-solver bridge ( buildPfModel , solvePf(ApslfSolver(...)) , applyPfSolution! ) to AnalyticLoadFlow.jl's analytic power-series solver (a required dependency; see apslf_solver )."),
  (title = "Use APSLF start values", url = "/help/power_flow.apslf_start.enabled", kind = "control", text = "APSLF solver as a guarded start-value generator ahead of Newton-Raphson: the candidate is kept only if it improves the mismatch. Not with solver APSLF. power_flow.apslf_start.enabled uses the AnalyticLoadFlow.jl-backed APSLF solver as a guarded start-value generator ahead of the rectangular Newton-Raphson solve, with the same insertion point and accept/reject guard style as the current-iteration pre-solve: the candidate is only adopted when it strictly improves the rectangular mismatch, otherwise the original start values are restored. Default: disabled. Diagnostic artifact: apslf_start.log ."),
  (title = "APSLF start highest coefficient (order)", url = "/help/power_flow.apslf_start.order", kind = "control", text = "Highest series coefficient of the APSLF start-value generator; higher orders cost more before the candidate is judged. No effect unless the generator is on. power_flow.apslf_start.enabled uses the AnalyticLoadFlow.jl-backed APSLF solver as a guarded start-value generator ahead of the rectangular Newton-Raphson solve, with the same insertion point and accept/reject guard style as the current-iteration pre-solve: the candidate is only adopted when it strictly improves the rectangular mismatch, otherwise the original start values are restored. Default: disabled. Diagnostic artifact: apslf_start.log ."),
  (title = "Auto slack: promote a reference when none is registered", url = "/help/power_flow.auto_slack", kind = "control", text = "Case without a slack bus: promote the strongest unit as reference (logged); off aborts such a run. Islands always pick their own reference, with or without it. The options every AC run reads: formulation and mode, flat start, tolerance and iteration cap, damping, slack promotion, the rescue ladder and the DC fallback. The Web UI form carries the ones a run is usually tuned with; the rest is YAML only."),
  (title = "Autodamping enabled", url = "/help/power_flow.autodamp", kind = "control", text = "Adaptive damping of the Newton step. Helps difficult convergence at a small overhead; switch it off only for strict algorithm comparisons. The options every AC run reads: formulation and mode, flat start, tolerance and iteration cap, damping, slack promotion, the rescue ladder and the DC fallback. The Web UI form carries the ones a run is usually tuned with; the rest is YAML only."),
  (title = "Autodamping minimum", url = "/help/power_flow.autodamp_min", kind = "control", text = "Minimum damping factor while autodamping is active. Lower values stabilize hard cases but can increase the iteration count. The options every AC run reads: formulation and mode, flat start, tolerance and iteration cap, damping, slack promotion, the rescue ladder and the DC fallback. The Web UI form carries the ones a run is usually tuned with; the rest is YAML only."),
  (title = "Standalone-DC fallback", url = "/help/power_flow.dc.fallback", kind = "control", text = "When AC and the rescue ladder fail, keep a standalone DC result: angles and branch P flows at 1 pu, no reactive results. The AC status stays non-converged. The options every AC run reads: formulation and mode, flat start, tolerance and iteration cap, damping, slack promotion, the rescue ladder and the DC fallback. The Web UI form carries the ones a run is usually tuned with; the rest is YAML only."),
  (title = "Distributed active-power slack enabled", url = "/help/power_flow.distributed_slack.enabled", kind = "control", text = "Spread the active-power imbalance over participating generators instead of the single slack bus. Off is bit-identical to the classical single-slack solver. power_flow.distributed_slack spreads the active-power imbalance of an island (load + losses − scheduled generation) over the participating generators instead of loading it onto the reference bus. Theory, augmented Newton system and applicability rules: Solver Guide."),
  (title = "Distributed-slack weight mode", url = "/help/power_flow.distributed_slack.p_mode", kind = "control", text = "Weight source of the participation factors: scheduled Pg, maximum P, remaining headroom, the imported factors, or an explicit weights table from the YAML. power_flow.distributed_slack spreads the active-power imbalance of an island (load + losses − scheduled generation) over the participating generators instead of loading it onto the reference bus. Theory, augmented Newton system and applicability rules: Solver Guide."),
  (title = "External grid source enabled", url = "/help/power_flow.external_grid.enabled", kind = "control", text = "Model the slack as a non-ideal source behind a feeder impedance, so its voltage droops under load. Off keeps the ideal slack; not with the distributed slack. power_flow.external_grid computes the marked slack bus as a non-ideal external-grid source: before the solve, convertSlackToExternalGrid! moves the reference voltage to a hidden internal bus <bus __extgrid_int behind the feeder impedance z = Un²/Sk'' (split by the R/X ratio), and the former slack bus becomes an ordinary solved bus whose voltage droops under load. Theory (both formulations, the stiff limit, the short-circuit effect): Slack Bus and External Grid Sources."),
  (title = "External grid R/X ratio", url = "/help/power_flow.external_grid.rx", kind = "control", text = "R/X ratio of the feeder impedance of the external grid source. power_flow.external_grid computes the marked slack bus as a non-ideal external-grid source: before the solve, convertSlackToExternalGrid! moves the reference voltage to a hidden internal bus <bus __extgrid_int behind the feeder impedance z = Un²/Sk'' (split by the R/X ratio), and the former slack bus becomes an ordinary solved bus whose voltage droops under load. Theory (both formulations, the stiff limit, the short-circuit effect): Slack Bus and External Grid Sources."),
  (title = "External grid short-circuit power Sk'' [MVA]", url = "/help/power_flow.external_grid.sk_MVA", kind = "control", text = "Initial symmetrical short-circuit power of the feeder in MVA. It sets the series impedance of the external grid source (z = baseMVA/Sk''). power_flow.external_grid computes the marked slack bus as a non-ideal external-grid source: before the solve, convertSlackToExternalGrid! moves the reference voltage to a hidden internal bus <bus __extgrid_int behind the feeder impedance z = Un²/Sk'' (split by the R/X ratio), and the former slack bus becomes an ordinary solved bus whose voltage droops under load. Theory (both formulations, the stiff limit, the short-circuit effect): Slack Bus and External Grid Sources."),
  (title = "External grid Sk''/R-X source", url = "/help/power_flow.external_grid.source", kind = "control", text = "Where Sk'' and R/X come from: auto prefers values the case declares on the slack bus, else the numbers below; config always uses the numbers below. power_flow.external_grid computes the marked slack bus as a non-ideal external-grid source: before the solve, convertSlackToExternalGrid! moves the reference voltage to a hidden internal bus <bus __extgrid_int behind the feeder impedance z = Un²/Sk'' (split by the R/X ratio), and the former slack bus becomes an ordinary solved bus whose voltage droops under load. Theory (both formulations, the stiff limit, the short-circuit effect): Slack Bus and External Grid Sources."),
  (title = "Flat start", url = "/help/power_flow.flatstart", kind = "control", text = "Start every bus at 1.0 pu and 0 degrees and ignore the imported start voltages. While on, the APSLF and DC start values and the pre-solve are switched off. power_flow.flatstart starts the Newton-Raphson solve at 1.0 pu and 0 degrees on every bus and ignores the imported start voltages (MATPOWER VM / VA , CGMES SvVoltage , SCF start_state ). Off, the imported values seed the solve; a delivery is built around its own operating point, so that is the better start for real networks and the default. This checkbox is the one start switch: while it is on, a run switches Use APSLF start values , Use DC start values , the current-iteration pre-solve and the start projection off and treats both start modes as classic , so the start really is flat and no projection or pre-solve moves it; the run log names what was switched off. The greyed controls keep their saved values and come back when the flat start is unchecked. A CGMES run honours the flat start under CGMES start values = auto ; an explicit sv on the Case page still starts from the delivery state (Power flow configuration)."),
  (title = "Dishonest Newton (reuse Jacobian factorisation)", url = "/help/power_flow.jacobian_reuse", kind = "control", text = "Reuses the previous LU while the mismatch falls fast; changes iteration counts, not the solution. For repeated solves of one large case, not for N-1. power_flow.jacobian_reuse: true (keyword jacobian_reuse = true , Web UI: the checkbox \"Dishonest Newton\" under Solver backend, directly below power mode) keeps the factorization of the Jacobian for the next Newton step while the mismatch falls by at least jacobian_reuse_min_reduction (default 10) per step, at most jacobian_reuse_max_steps (default 3) steps in a row; a reused step that misses the factor is replaced by the honest step. The rules are on the Solver Guide. Off by default; it changes the iteration count, not the solution (same tolerance, final state equal to honest Newton within it), and works with and without power mode."),
  (title = "Maximum reused steps in a row", url = "/help/power_flow.jacobian_reuse_max_steps", kind = "control", text = "Reused steps in a row before a forced refactorisation (default 3). power_flow.jacobian_reuse: true (keyword jacobian_reuse = true , Web UI: the checkbox \"Dishonest Newton\" under Solver backend, directly below power mode) keeps the factorization of the Jacobian for the next Newton step while the mismatch falls by at least jacobian_reuse_min_reduction (default 10) per step, at most jacobian_reuse_max_steps (default 3) steps in a row; a reused step that misses the factor is replaced by the honest step. The rules are on the Solver Guide. Off by default; it changes the iteration count, not the solution (same tolerance, final state equal to honest Newton within it), and works with and without power mode."),
  (title = "Minimum mismatch reduction per step", url = "/help/power_flow.jacobian_reuse_min_reduction", kind = "control", text = "Factor by which a step must cut the maximum mismatch so that the next step reuses the factorisation (default 10, above 1). power_flow.jacobian_reuse: true (keyword jacobian_reuse = true , Web UI: the checkbox \"Dishonest Newton\" under Solver backend, directly below power mode) keeps the factorization of the Jacobian for the next Newton step while the mismatch falls by at least jacobian_reuse_min_reduction (default 10) per step, at most jacobian_reuse_max_steps (default 3) steps in a row; a reused step that misses the factor is replaced by the honest step. The rules are on the Solver Guide. Off by default; it changes the iteration count, not the solution (same tolerance, final state equal to honest Newton within it), and works with and without power mode."),
  (title = "Linear solver backend", url = "/help/power_flow.linear_solver", kind = "control", text = "Sparse backend of the Newton step. umfpack_reuse keeps the symbolic analysis across iterations, faster on large cases; umfpack analyzes every iteration anew. The options every AC run reads: formulation and mode, flat start, tolerance and iteration cap, damping, slack promotion, the rescue ladder and the DC fallback. The Web UI form carries the ones a run is usually tuned with; the rest is YAML only."),
  (title = "Maximum iterations", url = "/help/power_flow.max_iter", kind = "control", text = "Iteration cap of the Newton-Raphson solve; a run that reaches it ends as non-converged. Very low values cut off hard cases. The options every AC run reads: formulation and mode, flat start, tolerance and iteration cap, damping, slack promotion, the rescue ladder and the DC fallback. The Web UI form carries the ones a run is usually tuned with; the rest is YAML only."),
  (title = "Armijo sufficient-decrease constant", url = "/help/power_flow.merit.armijo_c1", kind = "control", text = "Sufficient-decrease constant of the Armijo condition. Larger values reject more trial steps and increase the backtracking. power_flow.merit enables an optional Armijo sufficient-decrease acceptance test inside the autodamp backtracking loop of the rectangular Newton-Raphson solver, not a replacement for Newton-Raphson or autodamp. Disabled by default ( enabled: false ), which leaves the max-mismatch autodamp behavior unchanged. Background: Merit-Function Line Search."),
  (title = "Enable Armijo merit-function line search", url = "/help/power_flow.merit.enabled", kind = "control", text = "Armijo merit-function line search for step acceptance on difficult flat-start cases. Requires autodamping; adds one residual-norm evaluation per trial. power_flow.merit enables an optional Armijo sufficient-decrease acceptance test inside the autodamp backtracking loop of the rectangular Newton-Raphson solver, not a replacement for Newton-Raphson or autodamp. Disabled by default ( enabled: false ), which leaves the max-mismatch autodamp behavior unchanged. Background: Merit-Function Line Search."),
  (title = "Merit fallback behavior", url = "/help/power_flow.merit.fallback_max_mismatch", kind = "control", text = "When no trial satisfies the Armijo condition, fall back to the max-mismatch criterion (first improving trial). Off takes the most conservative finite trial. power_flow.merit enables an optional Armijo sufficient-decrease acceptance test inside the autodamp backtracking loop of the rectangular Newton-Raphson solver, not a replacement for Newton-Raphson or autodamp. Disabled by default ( enabled: false ), which leaves the max-mismatch autodamp behavior unchanged. Background: Merit-Function Line Search."),
  (title = "Newton update", url = "/help/power_flow.newton_update", kind = "control", text = "How a Newton step is applied: polar (default) as magnitude and angle, MATPOWER's update, safer on flat starts; rectangular adds it to the complex voltage. The options every AC run reads: formulation and mode, flat start, tolerance and iteration cap, damping, slack promotion, the rescue ladder and the DC fallback. The Web UI form carries the ones a run is usually tuned with; the rest is YAML only."),
  (title = "Power mode for repeated solves", url = "/help/power_flow.power_mode", kind = "control", text = "Keeps Ybus, LU analysis and work arrays on the network between solves and skips the ranked mismatch diagnostics. Same solution; off for a single run. Power mode is for the cases where one network is solved many times: a benchmark on a persistent model, the scenario engine, N-1 contingency sweeps, Monte Carlo, outer control loops. It is off by default; a single run gains nothing from it."),
  (title = "Auto start threshold (pu)", url = "/help/power_flow.qlimits.auto_q_delta_pu", kind = "control", text = "Reactive-power change per iteration below which the auto start rule lets switching begin. Used by the start rules auto and iteration_or_auto. How the reactive-power limits of PV machines are enforced: the master switch, the enforcement mode (active set or the classic outer loop), when the enforcement starts, the hysteresis around a limit, the final check that every mode ends with, and the guard that judges narrow ranges and remaining violations."),
  (title = "Cooldown iterations", url = "/help/power_flow.qlimits.cooldown_iters", kind = "control", text = "Iterations a bus waits after a switch before it may switch again. Reduces back-and-forth on machines close to a limit. How the reactive-power limits of PV machines are enforced: the master switch, the enforcement mode (active set or the classic outer loop), when the enforcement starts, the hysteresis around a limit, the final check that every mode ends with, and the guard that judges narrow ranges and remaining violations."),
  (title = "Q-limit handling enabled", url = "/help/power_flow.qlimits.enabled", kind = "control", text = "Master switch for generator Q-limit enforcement (PV to PQ switching). Off gives an unconstrained power flow; on can add switching iterations. How the reactive-power limits of PV machines are enforced: the master switch, the enforcement mode (active set or the classic outer loop), when the enforcement starts, the hysteresis around a limit, the final check that every mode ends with, and the guard that judges narrow ranges and remaining violations."),
  (title = "Q-limit enforcement mode", url = "/help/power_flow.qlimits.enforcement_mode", kind = "control", text = "Selects active-set or classical Q-limit switching; the classical modes may need repeated solves. off disables the handling like the checkbox above. How the reactive-power limits of PV machines are enforced: the master switch, the enforcement mode (active set or the classic outer loop), when the enforcement starts, the hysteresis around a limit, the final check that every mode ends with, and the guard that judges narrow ranges and remaining violations."),
  (title = "Final check bound (pu)", url = "/help/power_flow.qlimits.final_q_accept_pu", kind = "control", text = "Bound of the final Q-limit check every mode ends with, the classic ones too: an overshoot up to it is accepted with a warning. auto: twice the hysteresis. How the reactive-power limits of PV machines are enforced: the master switch, the enforcement mode (active set or the classic outer loop), when the enforcement starts, the hysteresis around a limit, the final check that every mode ends with, and the guard that judges narrow ranges and remaining violations."),
  (title = "Accept bounded violations", url = "/help/power_flow.qlimits.guard.accept_bounded_violations", kind = "control", text = "Accept a converged run with up to the allowed number of remaining Q-limit violations instead of rejecting it. How the reactive-power limits of PV machines are enforced: the master switch, the enforcement mode (active set or the classic outer loop), when the enforcement starts, the hysteresis around a limit, the final check that every mode ends with, and the guard that judges narrow ranges and remaining violations."),
  (title = "Narrow-range guard enabled", url = "/help/power_flow.qlimits.guard.enabled", kind = "control", text = "Before the solve, run machines with a narrow or zero Q range as PQ (the range rules below). The switch cap, freezing and violation rule act without it. How the reactive-power limits of PV machines are enforced: the master switch, the enforcement mode (active set or the classic outer loop), when the enforcement starts, the hysteresis around a limit, the final check that every mode ends with, and the guard that judges narrow ranges and remaining violations."),
  (title = "Freeze after repeated switching", url = "/help/power_flow.qlimits.guard.freeze_after_repeated_switching", kind = "control", text = "Freeze a bus that reached the maximum switch count in its current type. The run then ends as max_switching_exceeded unless the Q check passes. How the reactive-power limits of PV machines are enforced: the master switch, the enforcement mode (active set or the classic outer loop), when the enforcement starts, the hysteresis around a limit, the final check that every mode ends with, and the guard that judges narrow ranges and remaining violations."),
  (title = "Guard log line", url = "/help/power_flow.qlimits.guard.log", kind = "control", text = "Print how many narrow-range machines the guard locked as PQ; appears with verbose console output. How the reactive-power limits of PV machines are enforced: the master switch, the enforcement mode (active set or the classic outer loop), when the enforcement starts, the hysteresis around a limit, the final check that every mode ends with, and the guard that judges narrow ranges and remaining violations."),
  (title = "Accepted remaining violations", url = "/help/power_flow.qlimits.guard.max_remaining_violations", kind = "control", text = "How many PV buses may still violate a Q limit at the end when bounded violations are accepted. 0 accepts none. How the reactive-power limits of PV machines are enforced: the master switch, the enforcement mode (active set or the classic outer loop), when the enforcement starts, the hysteresis around a limit, the final check that every mode ends with, and the guard that judges narrow ranges and remaining violations."),
  (title = "Maximum switches per bus", url = "/help/power_flow.qlimits.guard.max_switches", kind = "control", text = "Switches of one bus after which it counts as oscillating. With freezing on, a converged run that reaches it ends as max_switching_exceeded. How the reactive-power limits of PV machines are enforced: the master switch, the enforcement mode (active set or the classic outer loop), when the enforcement starts, the hysteresis around a limit, the final check that every mode ends with, and the guard that judges narrow ranges and remaining violations."),
  (title = "Narrow Q range (pu)", url = "/help/power_flow.qlimits.guard.min_q_range_pu", kind = "control", text = "A machine whose Q range (Qmax minus Qmin) lies below this counts as narrow and follows the narrow-range rule. Needs the guard. How the reactive-power limits of PV machines are enforced: the master switch, the enforcement mode (active set or the classic outer loop), when the enforcement starts, the hysteresis around a limit, the final check that every mode ends with, and the guard that judges narrow ranges and remaining violations."),
  (title = "Narrow-range rule", url = "/help/power_flow.qlimits.guard.narrow_range_mode", kind = "control", text = "lock_pq and prefer_pq both run a narrow-range machine as PQ at the middle of its Q range from the start; the two currently behave alike. How the reactive-power limits of PV machines are enforced: the master switch, the enforcement mode (active set or the classic outer loop), when the enforcement starts, the hysteresis around a limit, the final check that every mode ends with, and the guard that judges narrow ranges and remaining violations."),
  (title = "Violation rule", url = "/help/power_flow.qlimits.guard.violation_mode", kind = "control", text = "lock_pq switches a machine once Q exceeds its limit by the violation threshold; delayed_switch waits until Q exceeds the limit by the hysteresis. How the reactive-power limits of PV machines are enforced: the master switch, the enforcement mode (active set or the classic outer loop), when the enforcement starts, the hysteresis around a limit, the final check that every mode ends with, and the guard that judges narrow ranges and remaining violations."),
  (title = "Violation threshold (pu)", url = "/help/power_flow.qlimits.guard.violation_threshold_pu", kind = "control", text = "Q overshoot beyond the limit from which the lock_pq violation rule switches a machine to PQ. Unused under delayed_switch. How the reactive-power limits of PV machines are enforced: the master switch, the enforcement mode (active set or the classic outer loop), when the enforcement starts, the hysteresis around a limit, the final check that every mode ends with, and the guard that judges narrow ranges and remaining violations."),
  (title = "Zero-range rule", url = "/help/power_flow.qlimits.guard.zero_range_mode", kind = "control", text = "A machine with Qmin equal to Qmax cannot hold a voltage; lock_pq runs it as PQ at that Q from the start. The only rule offered. How the reactive-power limits of PV machines are enforced: the master switch, the enforcement mode (active set or the classic outer loop), when the enforcement starts, the hysteresis around a limit, the final check that every mode ends with, and the guard that judges narrow ranges and remaining violations."),
  (title = "Q hysteresis (pu)", url = "/help/power_flow.qlimits.hysteresis_pu", kind = "control", text = "Margin beyond a Q limit before a machine switches, and the overshoot the final check still counts as within limits. Larger values damp chattering. How the reactive-power limits of PV machines are enforced: the master switch, the enforcement mode (active set or the classic outer loop), when the enforcement starts, the hysteresis around a limit, the final check that every mode ends with, and the guard that judges narrow ranges and remaining violations."),
  (title = "Buses locked to PQ", url = "/help/power_flow.qlimits.lock_pv_to_pq_buses", kind = "control", text = "Comma-separated buses run as PQ from the start: case bus numbers for a MATPOWER file, otherwise internal positions (1 = first bus of the network). How the reactive-power limits of PV machines are enforced: the master switch, the enforcement mode (active set or the classic outer loop), when the enforcement starts, the hysteresis around a limit, the final check that every mode ends with, and the guard that judges narrow ranges and remaining violations."),
  (title = "Release voltage margin (pu)", url = "/help/power_flow.qlimits.reenable_v_hyst_pu", kind = "control", text = "Voltage margin for releasing a clamped machine back to PV: at Qmax when Vm exceeds Vset by it, at Qmin when Vm falls below Vset by it. How the reactive-power limits of PV machines are enforced: the master switch, the enforcement mode (active set or the classic outer loop), when the enforcement starts, the hysteresis around a limit, the final check that every mode ends with, and the guard that judges narrow ranges and remaining violations."),
  (title = "First switching iteration", url = "/help/power_flow.qlimits.start_iter", kind = "control", text = "Newton iteration from which PV to PQ switching may run. Later values let the solve settle first; the classic modes switch between solves and ignore it. How the reactive-power limits of PV machines are enforced: the master switch, the enforcement mode (active set or the classic outer loop), when the enforcement starts, the hysteresis around a limit, the final check that every mode ends with, and the guard that judges narrow ranges and remaining violations."),
  (title = "Switching start rule", url = "/help/power_flow.qlimits.start_mode", kind = "control", text = "iteration starts at the first switching iteration, auto once the Q change falls below the auto threshold, iteration_or_auto at whichever comes first. How the reactive-power limits of PV machines are enforced: the master switch, the enforcement mode (active set or the classic outer loop), when the enforcement starts, the hysteresis around a limit, the final check that every mode ends with, and the guard that judges narrow ranges and remaining violations."),
  (title = "Traced buses", url = "/help/power_flow.qlimits.trace_buses", kind = "control", text = "Comma-separated bus numbers of the case file whose switching events are written in detail to the Q-limit trace. Empty traces nothing. How the reactive-power limits of PV machines are enforced: the master switch, the enforcement mode (active set or the classic outer loop), when the enforcement starts, the hysteresis around a limit, the final check that every mode ends with, and the guard that judges narrow ranges and remaining violations."),
  (title = "Rescue ladder for failed AC solves", url = "/help/power_flow.rescue", kind = "control", text = "After a non-converged AC solve, retry from the original start through a fixed ladder: alternate start, autodamp, DC seed, settled Q-limits. First success wins. The options every AC run reads: formulation and mode, flat start, tolerance and iteration cap, damping, slack promotion, the rescue ladder and the DC fallback. The Web UI form carries the ones a run is usually tuned with; the rest is YAML only."),
  (title = "Solver", url = "/help/power_flow.solver", kind = "control", text = "Selects the executing solver: AC Newton-Raphson, the APSLF power series (needs AnalyticLoadFlow.jl), or a DC linear model without voltages and reactive results. power_flow.solver selects the executing solver; power_flow.method fixes the AC formulation family (always rectangular ). apslf routes the run through the external-solver bridge ( buildPfModel , solvePf(ApslfSolver(...)) , applyPfSolution! ) to AnalyticLoadFlow.jl's analytic power-series solver (a required dependency; see apslf_solver )."),
  (title = "Accept only if improved", url = "/help/power_flow.start_current_iteration.accept_only_if_improved", kind = "control", text = "Accept the pre-solve candidate only when it improves the mismatch; otherwise the original start values are restored. Keep it on outside expert experiments. power_flow.start_current_iteration.enabled enables a guarded current-injection/current-iteration pre-solve before the Newton-Raphson power-flow solver starts. This is not a separate power-flow solver and it does not replace Newton-Raphson. It is a start-value preconditioner: Sparlectra first builds the initial voltage profile from Start Voltage Mode and Start Angle Mode, then optionally tries a few current-iteration steps to improve that initial profile. The improved voltage profile is accepted only if it passes the voltage and angle guards and improves the existing Sparlectra mismatch metric. If it does not improve the start, the original start values are restored and Newton-Raphson starts normally. Default: disabled. Enable this only for difficult cases where the normal start profile or DC/profile-blend start is not robust enough. Diagnostic artifact: current_iteration_start.log ."),
  (title = "Current-iteration damping", url = "/help/power_flow.start_current_iteration.damping", kind = "control", text = "Damping factor of the pre-solve voltage update; 1.0 applies the full update. Lower it if the candidate is rejected by the voltage or angle guards. power_flow.start_current_iteration.enabled enables a guarded current-injection/current-iteration pre-solve before the Newton-Raphson power-flow solver starts. This is not a separate power-flow solver and it does not replace Newton-Raphson. It is a start-value preconditioner: Sparlectra first builds the initial voltage profile from Start Voltage Mode and Start Angle Mode, then optionally tries a few current-iteration steps to improve that initial profile. The improved voltage profile is accepted only if it passes the voltage and angle guards and improves the existing Sparlectra mismatch metric. If it does not improve the start, the original start values are restored and Newton-Raphson starts normally. Default: disabled. Enable this only for difficult cases where the normal start profile or DC/profile-blend start is not robust enough. Diagnostic artifact: current_iteration_start.log ."),
  (title = "Enable current-iteration pre-solve", url = "/help/power_flow.start_current_iteration.enabled", kind = "control", text = "Guarded current-iteration pre-solve improving the start profile before Newton-Raphson; the result is kept only if it passes the guards and lowers the mismatch. power_flow.start_current_iteration.enabled enables a guarded current-injection/current-iteration pre-solve before the Newton-Raphson power-flow solver starts. This is not a separate power-flow solver and it does not replace Newton-Raphson. It is a start-value preconditioner: Sparlectra first builds the initial voltage profile from Start Voltage Mode and Start Angle Mode, then optionally tries a few current-iteration steps to improve that initial profile. The improved voltage profile is accepted only if it passes the voltage and angle guards and improves the existing Sparlectra mismatch metric. If it does not improve the start, the original start values are restored and Newton-Raphson starts normally. Default: disabled. Enable this only for difficult cases where the normal start profile or DC/profile-blend start is not robust enough. Diagnostic artifact: current_iteration_start.log ."),
  (title = "Maximum angle-step guard [deg]", url = "/help/power_flow.start_current_iteration.max_angle_step_deg", kind = "control", text = "Largest allowed angle change of one pre-solve update; a larger jump rejects the candidate. Lower it for a more conservative pre-solve. power_flow.start_current_iteration.enabled enables a guarded current-injection/current-iteration pre-solve before the Newton-Raphson power-flow solver starts. This is not a separate power-flow solver and it does not replace Newton-Raphson. It is a start-value preconditioner: Sparlectra first builds the initial voltage profile from Start Voltage Mode and Start Angle Mode, then optionally tries a few current-iteration steps to improve that initial profile. The improved voltage profile is accepted only if it passes the voltage and angle guards and improves the existing Sparlectra mismatch metric. If it does not improve the start, the original start values are restored and Newton-Raphson starts normally. Default: disabled. Enable this only for difficult cases where the normal start profile or DC/profile-blend start is not robust enough. Diagnostic artifact: current_iteration_start.log ."),
  (title = "Current-iteration max iterations", url = "/help/power_flow.start_current_iteration.max_iter", kind = "control", text = "Maximum number of pre-solve steps before Newton-Raphson starts. Keep it small; raise it only when the mismatch keeps improving but the pre-solve stops early. power_flow.start_current_iteration.enabled enables a guarded current-injection/current-iteration pre-solve before the Newton-Raphson power-flow solver starts. This is not a separate power-flow solver and it does not replace Newton-Raphson. It is a start-value preconditioner: Sparlectra first builds the initial voltage profile from Start Voltage Mode and Start Angle Mode, then optionally tries a few current-iteration steps to improve that initial profile. The improved voltage profile is accepted only if it passes the voltage and angle guards and improves the existing Sparlectra mismatch metric. If it does not improve the start, the original start values are restored and Newton-Raphson starts normally. Default: disabled. Enable this only for difficult cases where the normal start profile or DC/profile-blend start is not robust enough. Diagnostic artifact: current_iteration_start.log ."),
  (title = "Minimum improvement factor", url = "/help/power_flow.start_current_iteration.min_improvement_factor", kind = "control", text = "Required improvement ratio of the candidate mismatch; 0.98 means at least about 2 percent better. Smaller values demand a stronger improvement. power_flow.start_current_iteration.enabled enables a guarded current-injection/current-iteration pre-solve before the Newton-Raphson power-flow solver starts. This is not a separate power-flow solver and it does not replace Newton-Raphson. It is a start-value preconditioner: Sparlectra first builds the initial voltage profile from Start Voltage Mode and Start Angle Mode, then optionally tries a few current-iteration steps to improve that initial profile. The improved voltage profile is accepted only if it passes the voltage and angle guards and improves the existing Sparlectra mismatch metric. If it does not improve the start, the original start values are restored and Newton-Raphson starts normally. Default: disabled. Enable this only for difficult cases where the normal start profile or DC/profile-blend start is not robust enough. Diagnostic artifact: current_iteration_start.log ."),
  (title = "Only for large cases", url = "/help/power_flow.start_current_iteration.only_for_large_cases", kind = "control", text = "Run the pre-solve only for cases classified as large. Small cases keep their normal start values. power_flow.start_current_iteration.enabled enables a guarded current-injection/current-iteration pre-solve before the Newton-Raphson power-flow solver starts. This is not a separate power-flow solver and it does not replace Newton-Raphson. It is a start-value preconditioner: Sparlectra first builds the initial voltage profile from Start Voltage Mode and Start Angle Mode, then optionally tries a few current-iteration steps to improve that initial profile. The improved voltage profile is accepted only if it passes the voltage and angle guards and improves the existing Sparlectra mismatch metric. If it does not improve the start, the original start values are restored and Newton-Raphson starts normally. Default: disabled. Enable this only for difficult cases where the normal start profile or DC/profile-blend start is not robust enough. Diagnostic artifact: current_iteration_start.log ."),
  (title = "Current-iteration tolerance", url = "/help/power_flow.start_current_iteration.tol", kind = "control", text = "Stopping tolerance of the pre-solve, not the final Newton-Raphson tolerance. A loose value is enough; the goal is a better start, not a solved power flow. power_flow.start_current_iteration.enabled enables a guarded current-injection/current-iteration pre-solve before the Newton-Raphson power-flow solver starts. This is not a separate power-flow solver and it does not replace Newton-Raphson. It is a start-value preconditioner: Sparlectra first builds the initial voltage profile from Start Voltage Mode and Start Angle Mode, then optionally tries a few current-iteration steps to improve that initial profile. The improved voltage profile is accepted only if it passes the voltage and angle guards and improves the existing Sparlectra mismatch metric. If it does not improve the start, the original start values are restored and Newton-Raphson starts normally. Default: disabled. Enable this only for difficult cases where the normal start profile or DC/profile-blend start is not robust enough. Diagnostic artifact: current_iteration_start.log ."),
  (title = "Maximum voltage guard [pu]", url = "/help/power_flow.start_current_iteration.vm_max_pu", kind = "control", text = "Upper voltage guard: a candidate with any bus voltage above it is rejected and the original start values are restored. power_flow.start_current_iteration.enabled enables a guarded current-injection/current-iteration pre-solve before the Newton-Raphson power-flow solver starts. This is not a separate power-flow solver and it does not replace Newton-Raphson. It is a start-value preconditioner: Sparlectra first builds the initial voltage profile from Start Voltage Mode and Start Angle Mode, then optionally tries a few current-iteration steps to improve that initial profile. The improved voltage profile is accepted only if it passes the voltage and angle guards and improves the existing Sparlectra mismatch metric. If it does not improve the start, the original start values are restored and Newton-Raphson starts normally. Default: disabled. Enable this only for difficult cases where the normal start profile or DC/profile-blend start is not robust enough. Diagnostic artifact: current_iteration_start.log ."),
  (title = "Minimum voltage guard [pu]", url = "/help/power_flow.start_current_iteration.vm_min_pu", kind = "control", text = "Lower voltage guard: a candidate with any bus voltage below it is rejected and the original start values are restored. power_flow.start_current_iteration.enabled enables a guarded current-injection/current-iteration pre-solve before the Newton-Raphson power-flow solver starts. This is not a separate power-flow solver and it does not replace Newton-Raphson. It is a start-value preconditioner: Sparlectra first builds the initial voltage profile from Start Voltage Mode and Start Angle Mode, then optionally tries a few current-iteration steps to improve that initial profile. The improved voltage profile is accepted only if it passes the voltage and angle guards and improves the existing Sparlectra mismatch metric. If it does not improve the start, the original start values are restored and Newton-Raphson starts normally. Default: disabled. Enable this only for difficult cases where the normal start profile or DC/profile-blend start is not robust enough. Diagnostic artifact: current_iteration_start.log ."),
  (title = "Start angle mode", url = "/help/power_flow.start_mode.angle_mode", kind = "control", text = "Source of the start angles: classic zero angles, a DC pre-pass (default), or the imported angles. Ignored while the flat start is on. Where the Newton-Raphson iteration starts: the angle and voltage initialisation modes, the profile a start can be taken from, the start projection and the DC and blend attempts that run before the first step. A flat start switches all of them off."),
  (title = "DC start values", url = "/help/power_flow.start_mode.dc_seed_unconditional", kind = "control", text = "Always run a full DC power flow first and seed the Newton-Raphson start angles from it, bypassing the start angle mode and its quality gate. Where the Newton-Raphson iteration starts: the angle and voltage initialisation modes, the profile a start can be taken from, the start projection and the DC and blend attempts that run before the first step. A flat start switches all of them off."),
  (title = "Start voltage mode", url = "/help/power_flow.start_mode.voltage_mode", kind = "control", text = "Source of the start voltage magnitudes: classic flat, generator or bus setpoints, or a blend of the imported profile. Ignored while the flat start is on. Where the Newton-Raphson iteration starts: the angle and voltage initialisation modes, the profile a start can be taken from, the start projection and the DC and blend attempts that run before the first step. A flat start switches all of them off."),
  (title = "PowerFlow tolerance", url = "/help/power_flow.tol", kind = "control", text = "Convergence bound for the largest single bus mismatch, active and reactive alike. 1e-8 pu equals 1 W at a 100 MVA base. The options every AC run reads: formulation and mode, flat start, tolerance and iteration cap, damping, slack promotion, the rescue ladder and the DC fallback. The Web UI form carries the ones a run is usually tuned with; the rest is YAML only."),
  (title = "PowerFlow tolerance in MW", url = "/help/power_flow.tol_MW", kind = "control", text = "Unit of the tolerance value. MW states the bound physically, converted with the case base at run time (1 MW at 100 MVA is 1e-2 pu); pu is the classic form. The options every AC run reads: formulation and mode, flat start, tolerance and iteration cap, damping, slack promotion, the rescue ladder and the DC fallback. The Web UI form carries the ones a run is usually tuned with; the rest is YAML only."),
  (title = "Enable trust-region step control", url = "/help/power_flow.trust_region.enabled", kind = "control", text = "Scaled-Newton trust-region step control as an alternative to autodamping; enabling one disables the other. Suited to difficult flat-start cases. power_flow.trust_region enables an optional scaled-Newton trust-region alternative to power_flow.autodamp : it caps the Newton step norm at an adaptive radius and accepts or rejects trials by merit-function decrease rather than by the max-mismatch criterion. Disabled by default ( enabled: false ); mutually exclusive with power_flow.autodamp = true (both control the step length, enabling both is a configuration error). Background: Trust-Region Step Control."),
  (title = "Trust-region acceptance ratio (eta)", url = "/help/power_flow.trust_region.eta_accept", kind = "control", text = "Minimum actual-to-predicted reduction ratio to accept a trial step. Higher values reject more trials and add shrink-and-retry iterations. power_flow.trust_region enables an optional scaled-Newton trust-region alternative to power_flow.autodamp : it caps the Newton step norm at an adaptive radius and accepts or rejects trials by merit-function decrease rather than by the max-mismatch criterion. Disabled by default ( enabled: false ); mutually exclusive with power_flow.autodamp = true (both control the step length, enabling both is a configuration error). Background: Trust-Region Step Control."),
  (title = "Initial trust-region radius", url = "/help/power_flow.trust_region.initial_radius", kind = "control", text = "Starting trust-region radius in per-unit state-vector norm. Larger values risk more rejected or shrunk first steps on hard cases. power_flow.trust_region enables an optional scaled-Newton trust-region alternative to power_flow.autodamp : it caps the Newton step norm at an adaptive radius and accepts or rejects trials by merit-function decrease rather than by the max-mismatch criterion. Disabled by default ( enabled: false ); mutually exclusive with power_flow.autodamp = true (both control the step length, enabling both is a configuration error). Background: Trust-Region Step Control."),
  (title = "Trust-region step mode", url = "/help/power_flow.trust_region.step_mode", kind = "control", text = "Trial-step construction: scaled rescales the full Newton direction to the radius; dogleg blends it with a steepest-descent step when the radius shrinks. power_flow.trust_region enables an optional scaled-Newton trust-region alternative to power_flow.autodamp : it caps the Newton step norm at an adaptive radius and accepts or rejects trials by merit-function decrease rather than by the max-mismatch criterion. Disabled by default ( enabled: false ); mutually exclusive with power_flow.autodamp = true (both control the step length, enabling both is a configuration error). Background: Trust-Region Step Control."),
  (title = "Wrong-branch detection", url = "/help/power_flow.wrong_branch_detection", kind = "control", text = "Plausibility check of the converged solution on the highest voltage level: warn reports a suspicious result, fail treats it as non-converged, off skips it. power_flow.wrong_branch_detection is a post-convergence plausibility check for rectangular PF results; it is heuristic and does not prove global branch correctness."),
  (title = "System base MVA (PowSyBl)", url = "/help/powsybl_import.base_mva", kind = "control", text = "Per-unit base of the built network; PowSyBl files carry no base, 100 MVA is the default. The powsybl_import scope (canonical section powsybl , alias powsybl_import ), see Configuration:"),
  (title = "HVDC converters (PowSyBl)", url = "/help/powsybl_import.hvdc_mode", kind = "control", text = "HVDC converter model of a PowSyBl network: fixed injections reproduce the OpenLoadFlow snapshot; a paired controller is not implemented yet. The powsybl_import scope (canonical section powsybl , alias powsybl_import ), see Configuration:"),
  (title = "One slack per synchronous component", url = "/help/powsybl_import.multi_slack", kind = "control", text = "Every synchronous component gets its own slack generator, the regulating unit with the largest max_p; unchecked, only the first component has a reference. The powsybl_import scope (canonical section powsybl , alias powsybl_import ), see Configuration:"),
  (title = "Remote voltage regulation (PowSyBl)", url = "/help/powsybl_import.remote_regulation", kind = "control", text = "Generator regulating another bus: hold_local keeps it PV at its own bus, pq fixes P and Q, remote controls the regulated bus in the outer loop. The powsybl_import scope (canonical section powsybl , alias powsybl_import ), see Configuration:"),
  (title = "Slack generator ids (PowSyBl)", url = "/help/powsybl_import.slack_ids", kind = "control", text = "Generator ids that become the slack of their component, separated by semicolons; empty lets the largest max_p decide. The powsybl_import scope (canonical section powsybl , alias powsybl_import ), see Configuration:"),
  (title = "Parallel execution of independent work items", url = "/help/runtime.parallel.enabled", kind = "control", text = "Use Julia threads for independent work items: island solves, short-circuit sweeps, contingency batches. Off forces every site onto the serial path. Process-level settings read once at startup: the thread report, the Julia and BLAS thread counts, and the parallel work split of the sweeps."),
  (title = "SE flat start", url = "/help/state_estimation.flatstart", kind = "control", text = "Start the estimator from a flat voltage profile instead of the model's current state. Uncheck when a trusted start state exists. flatstart , robust_mode , robust , k_eliminate , k_suppress , max_eliminations , topology_precheck , and report_residual_correlation are case-scope keys, like power_flow.solver : they can be saved into a case's configuration file (Web UI: the \"Save settings for this case\" button on the State Estimation page, or the Settings page), and the State Estimation page's form fields show the effective value (case sidecar, else this file, else the default below) instead of a fixed literal. The remaining estimator keys stay installation-wide, set here or via the API only."),
  (title = "Elimination limit (normalized residual)", url = "/help/state_estimation.k_eliminate", kind = "control", text = "Normalized residual from which a measurement is removed from the estimate, not just down-weighted. Applies while the band test is high, within the budget. Both limits work on the normalized residual \$r_{n,i} = r_i / \\sqrt{\\Omega_{ii}}\$, computed with the original sigmas; only the staged knees robust_k1 / robust_k2 stay on the raw ratio \$ r_i /\\sigma_i\$. Down-weighting and elimination read the same quantity, so their limits are directly comparable. Rule of thumb: suppression for online smoothing, elimination for identification."),
  (title = "SE maximum iterations", url = "/help/state_estimation.max_iter", kind = "control", text = "Iteration cap of the estimator, the same limit the service and the configuration use. A solve with released transformer taps can need close to 40 iterations. flatstart , robust_mode , robust , k_eliminate , k_suppress , max_eliminations , topology_precheck , and report_residual_correlation are case-scope keys, like power_flow.solver : they can be saved into a case's configuration file (Web UI: the \"Save settings for this case\" button on the State Estimation page, or the Settings page), and the State Estimation page's form fields show the effective value (case sidecar, else this file, else the default below) instead of a fixed literal. The remaining estimator keys stay installation-wide, set here or via the API only."),
  (title = "Residual-correlation (K-matrix) report", url = "/help/state_estimation.report_residual_correlation", kind = "control", text = "Add residual-correlation columns to the bad-data report: rows correlated above 0.707 form a group where a gross error cannot be told apart. Reporting only. With the correlation report on, each ranking row carries the maximum"),
  (title = "Robust R modification", url = "/help/state_estimation.robust", kind = "control", text = "Deprecated alias for the down-weighting mode staged, read only while that mode is off. Set the down-weighting mode instead, never both. Both limits work on the normalized residual \$r_{n,i} = r_i / \\sqrt{\\Omega_{ii}}\$, computed with the original sigmas; only the staged knees robust_k1 / robust_k2 stay on the raw ratio \$ r_i /\\sigma_i\$. Down-weighting and elimination read the same quantity, so their limits are directly comparable. Rule of thumb: suppression for online smoothing, elimination for identification."),
  (title = "Down-weighting (off / staged / replacement)", url = "/help/state_estimation.robust_mode", kind = "control", text = "Treatment of a large residual: off is plain WLS, staged down-weights the row gradually between two knees, replacement gives it a fixed large sigma. Both limits work on the normalized residual \$r_{n,i} = r_i / \\sqrt{\\Omega_{ii}}\$, computed with the original sigmas; only the staged knees robust_k1 / robust_k2 stay on the raw ratio \$ r_i /\\sigma_i\$. Down-weighting and elimination read the same quantity, so their limits are directly comparable. Rule of thumb: suppression for online smoothing, elimination for identification."),
  (title = "Down-weight limit and replacement sigma", url = "/help/state_estimation.suppression", kind = "control", text = "Replacement mode: from this normalized residual a row is solved with the replacement sigma and loses its influence, but is not removed. Sigma in the row's unit. Both limits work on the normalized residual \$r_{n,i} = r_i / \\sqrt{\\Omega_{ii}}\$, computed with the original sigmas; only the staged knees robust_k1 / robust_k2 stay on the raw ratio \$ r_i /\\sigma_i\$. Down-weighting and elimination read the same quantity, so their limits are directly comparable. Rule of thumb: suppression for online smoothing, elimination for identification."),
  (title = "SE convergence tolerance", url = "/help/state_estimation.tol", kind = "control", text = "WLS convergence tolerance on the state step. The default 1e-6 is the noise floor of the finite-difference Jacobian; a tighter value is raised with a log line. flatstart , robust_mode , robust , k_eliminate , k_suppress , max_eliminations , topology_precheck , and report_residual_correlation are case-scope keys, like power_flow.solver : they can be saved into a case's configuration file (Web UI: the \"Save settings for this case\" button on the State Estimation page, or the Settings page), and the State Estimation page's form fields show the effective value (case sidecar, else this file, else the default below) instead of a fixed literal. The remaining estimator keys stay installation-wide, set here or via the API only."),
  (title = "Write estimated shunts back", url = "/help/state_estimation.update_shunts", kind = "control", text = "Write the estimated shunt susceptances back into the model after a converged run. Off keeps the model data authoritative. flatstart , robust_mode , robust , k_eliminate , k_suppress , max_eliminations , topology_precheck , and report_residual_correlation are case-scope keys, like power_flow.solver : they can be saved into a case's configuration file (Web UI: the \"Save settings for this case\" button on the State Estimation page, or the Settings page), and the State Estimation page's form fields show the effective value (case sidecar, else this file, else the default below) instead of a fixed literal. The remaining estimator keys stay installation-wide, set here or via the API only."),
  (title = "Case input format", url = "/help/webui.case_format", kind = "control", text = "Auto tells MATPOWER, CGMES, SCF/PGM JSON, PowSyBl and DTF apart from the file content. Pick a format only when the file does not say what it is. The settings and run forms offer: - case name or local path, configuration template file, the read-only output root (set only through start_sparlectra_webui(; output_root) ); - tolerance (decimals or scientific notation such as 1e-8 ; the exponent spinner, buttons or Up/Down keys, steps the exponent and keeps the mantissa: 1e-5 down gives 1e-6 , up gives 1e-4 ), maximum iterations, autodamping with its minimum factor; - Q-limit handling : the power_flow.qlimits.enabled checkbox and the enforcement-mode selector in one block; the selector also offers off and shows it whenever the handling is off. Below them, PV/PQ switching shows the hysteresis and the final check bound ( final_q_accept_pu , auto or a value in pu; the two settings the classic modes read), the first switching iteration ( start_iter ), the maximum switches per bus ( guard.max_switches ), freezing after repeated switching and the narrow-range guard switch ( guard.enabled ); Advanced holds the rest of power_flow.qlimits : start rule and auto threshold, cooldown, release voltage margin, the traced buses (bus numbers of the case file) and the buses locked to PQ (case bus numbers for a MATPOWER file, otherwise internal positions), the violation rule and threshold, bounded violations, and the narrow- and zero-range rules with their log line (Q-limit options and guard). Per-unit values take scientific notation like the tolerance, bus lists comma-separated numbers. Everything is grayed while the handling is off; the classic modes solve completely and then check the limits, again after every clamp, so they have no start iteration and gray what they do not read (they use the hysteresis and the final check bound); the guard switch grays the range rules, because the switch cap, freezing and the violation rule act without it. All of it saves to the configuration file and per case like every other run option; - Solver : one radio group power_flow_solver with the peer values rectangular (AC Newton-Raphson), apslf (AnalyticLoadFlow) and dc (linear screening model), writing power_flow.solver , power_flow.apslf. , power_flow.apslf_start. and power_flow.dc. (solver selection, DC power flow); radio buttons are never disabled, so the choice is always submitted; - wrong-branch detection mode, start angle and voltage modes; - Advanced start values : the current-iteration pre-solve fields ( power_flow.start_current_iteration. , guarded pre-solve), a preconditioner between start projection and Newton-Raphson, not a new start mode; - Merit-function line search : power_flow.merit.enabled , power_flow.merit.armijo_c1 , power_flow.merit.fallback_max_mismatch (options), requires power_flow.autodamp = true ; scale_p / scale_q / scale_v are YAML-only; a diagnostic run writes merit_linesearch.log ; - Non-convergence handling (Advanced): power_flow.rescue (retry ladder), power_flow.auto_slack (promote a reference when the case registers none; islands always find their own reference) and power_flow.dc.fallback (standalone DC result when AC has no solution), see Power-Flow Configuration; - MATPOWER import conventions: auto-profile mode ( off , recommend , apply ) plus transformer ratio, phase shift, bus shunt, PV voltage source and comparison reference; - logfile output mode, performance timing and post-run diagnostics. Only keys in GUI_EDITABLE_CONFIG_KEYS are submitted, the selected template is never modified, and each run writes effective_config.yaml . Every control carries a hover text with its operation and effect; a ? next to a control with something technical behind it (solver options, estimator diagnostics, Q-limits, formats) opens its help page in a new tab: the hint, the matching section of this documentation as shipped with the running version (the beginning of a long section), and a link to the section on the published site. webui.docs_base_url (configuration file) points that link at a local docs build or a pinned version. Back returns through the browser history with the entered values intact (fallback /powerflow ). Fields that do not apply to the selected solver or step control (autodamp/trust-region) are grayed out in place, not hidden; a grayed field is disabled and not submitted."),
  (title = "MATPOWER case file", url = "/help/webui.casefile", kind = "control", text = "Choose a case from the list, or type a bare case name or a local path and press Enter to download or copy it into the case directory. The settings and run forms offer: - case name or local path, configuration template file, the read-only output root (set only through start_sparlectra_webui(; output_root) ); - tolerance (decimals or scientific notation such as 1e-8 ; the exponent spinner, buttons or Up/Down keys, steps the exponent and keeps the mantissa: 1e-5 down gives 1e-6 , up gives 1e-4 ), maximum iterations, autodamping with its minimum factor; - Q-limit handling : the power_flow.qlimits.enabled checkbox and the enforcement-mode selector in one block; the selector also offers off and shows it whenever the handling is off. Below them, PV/PQ switching shows the hysteresis and the final check bound ( final_q_accept_pu , auto or a value in pu; the two settings the classic modes read), the first switching iteration ( start_iter ), the maximum switches per bus ( guard.max_switches ), freezing after repeated switching and the narrow-range guard switch ( guard.enabled ); Advanced holds the rest of power_flow.qlimits : start rule and auto threshold, cooldown, release voltage margin, the traced buses (bus numbers of the case file) and the buses locked to PQ (case bus numbers for a MATPOWER file, otherwise internal positions), the violation rule and threshold, bounded violations, and the narrow- and zero-range rules with their log line (Q-limit options and guard). Per-unit values take scientific notation like the tolerance, bus lists comma-separated numbers. Everything is grayed while the handling is off; the classic modes solve completely and then check the limits, again after every clamp, so they have no start iteration and gray what they do not read (they use the hysteresis and the final check bound); the guard switch grays the range rules, because the switch cap, freezing and the violation rule act without it. All of it saves to the configuration file and per case like every other run option; - Solver : one radio group power_flow_solver with the peer values rectangular (AC Newton-Raphson), apslf (AnalyticLoadFlow) and dc (linear screening model), writing power_flow.solver , power_flow.apslf. , power_flow.apslf_start. and power_flow.dc. (solver selection, DC power flow); radio buttons are never disabled, so the choice is always submitted; - wrong-branch detection mode, start angle and voltage modes; - Advanced start values : the current-iteration pre-solve fields ( power_flow.start_current_iteration. , guarded pre-solve), a preconditioner between start projection and Newton-Raphson, not a new start mode; - Merit-function line search : power_flow.merit.enabled , power_flow.merit.armijo_c1 , power_flow.merit.fallback_max_mismatch (options), requires power_flow.autodamp = true ; scale_p / scale_q / scale_v are YAML-only; a diagnostic run writes merit_linesearch.log ; - Non-convergence handling (Advanced): power_flow.rescue (retry ladder), power_flow.auto_slack (promote a reference when the case registers none; islands always find their own reference) and power_flow.dc.fallback (standalone DC result when AC has no solution), see Power-Flow Configuration; - MATPOWER import conventions: auto-profile mode ( off , recommend , apply ) plus transformer ratio, phase shift, bus shunt, PV voltage source and comparison reference; - logfile output mode, performance timing and post-run diagnostics. Only keys in GUI_EDITABLE_CONFIG_KEYS are submitted, the selected template is never modified, and each run writes effective_config.yaml . Every control carries a hover text with its operation and effect; a ? next to a control with something technical behind it (solver options, estimator diagnostics, Q-limits, formats) opens its help page in a new tab: the hint, the matching section of this documentation as shipped with the running version (the beginning of a long section), and a link to the section on the published site. webui.docs_base_url (configuration file) points that link at a local docs build or a pinned version. Back returns through the browser history with the entered values intact (fallback /powerflow ). Fields that do not apply to the selected solver or step control (autodamp/trust-region) are grayed out in place, not hidden; a grayed field is disabled and not submitted."),
  (title = "Configuration template file", url = "/help/webui.config_file", kind = "control", text = "Configuration YAML the run starts from. Form values become per-run overrides on top of it; the file itself stays unchanged. The settings and run forms offer: - case name or local path, configuration template file, the read-only output root (set only through start_sparlectra_webui(; output_root) ); - tolerance (decimals or scientific notation such as 1e-8 ; the exponent spinner, buttons or Up/Down keys, steps the exponent and keeps the mantissa: 1e-5 down gives 1e-6 , up gives 1e-4 ), maximum iterations, autodamping with its minimum factor; - Q-limit handling : the power_flow.qlimits.enabled checkbox and the enforcement-mode selector in one block; the selector also offers off and shows it whenever the handling is off. Below them, PV/PQ switching shows the hysteresis and the final check bound ( final_q_accept_pu , auto or a value in pu; the two settings the classic modes read), the first switching iteration ( start_iter ), the maximum switches per bus ( guard.max_switches ), freezing after repeated switching and the narrow-range guard switch ( guard.enabled ); Advanced holds the rest of power_flow.qlimits : start rule and auto threshold, cooldown, release voltage margin, the traced buses (bus numbers of the case file) and the buses locked to PQ (case bus numbers for a MATPOWER file, otherwise internal positions), the violation rule and threshold, bounded violations, and the narrow- and zero-range rules with their log line (Q-limit options and guard). Per-unit values take scientific notation like the tolerance, bus lists comma-separated numbers. Everything is grayed while the handling is off; the classic modes solve completely and then check the limits, again after every clamp, so they have no start iteration and gray what they do not read (they use the hysteresis and the final check bound); the guard switch grays the range rules, because the switch cap, freezing and the violation rule act without it. All of it saves to the configuration file and per case like every other run option; - Solver : one radio group power_flow_solver with the peer values rectangular (AC Newton-Raphson), apslf (AnalyticLoadFlow) and dc (linear screening model), writing power_flow.solver , power_flow.apslf. , power_flow.apslf_start. and power_flow.dc. (solver selection, DC power flow); radio buttons are never disabled, so the choice is always submitted; - wrong-branch detection mode, start angle and voltage modes; - Advanced start values : the current-iteration pre-solve fields ( power_flow.start_current_iteration. , guarded pre-solve), a preconditioner between start projection and Newton-Raphson, not a new start mode; - Merit-function line search : power_flow.merit.enabled , power_flow.merit.armijo_c1 , power_flow.merit.fallback_max_mismatch (options), requires power_flow.autodamp = true ; scale_p / scale_q / scale_v are YAML-only; a diagnostic run writes merit_linesearch.log ; - Non-convergence handling (Advanced): power_flow.rescue (retry ladder), power_flow.auto_slack (promote a reference when the case registers none; islands always find their own reference) and power_flow.dc.fallback (standalone DC result when AC has no solution), see Power-Flow Configuration; - MATPOWER import conventions: auto-profile mode ( off , recommend , apply ) plus transformer ratio, phase shift, bus shunt, PV voltage source and comparison reference; - logfile output mode, performance timing and post-run diagnostics. Only keys in GUI_EDITABLE_CONFIG_KEYS are submitted, the selected template is never modified, and each run writes effective_config.yaml . Every control carries a hover text with its operation and effect; a ? next to a control with something technical behind it (solver options, estimator diagnostics, Q-limits, formats) opens its help page in a new tab: the hint, the matching section of this documentation as shipped with the running version (the beginning of a long section), and a link to the section on the published site. webui.docs_base_url (configuration file) points that link at a local docs build or a pinned version. Back returns through the browser history with the entered values intact (fallback /powerflow ). Fields that do not apply to the selected solver or step control (autodamp/trust-region) are grayed out in place, not hidden; a grayed field is disabled and not submitted."),
  (title = "Configuration maintenance", url = "/help/webui.config_maintenance", kind = "control", text = "Check compares the YAML with the template and previews the refresh without writing; Refresh adds missing keys after a backup; the Editor edits the file. Check configuration and Refresh configuration bring a local file up to a template that gained options. Check is a dry run against src/config/configuration.yaml.example : missing keys, known deprecated aliases, duplicate YAML keys and a preview of the refreshed YAML, nothing written. Refresh keeps existing values, adds missing keys with template defaults and may normalize deprecated aliases (start-mode settings, legacy matpower_ Q-limit mode names); it never runs at startup, writes a timestamped backup first, refuses on duplicate keys, and offers uploaded or pasted YAML as a download instead of rewriting it. The Configuration Editor opens the active YAML in a textarea, validates it with the same parser and duplicate-key checks, writes only after validation with a timestamped backup, and warns when a case configuration file still overrides the global YAML through the prefilled form. After a save the server reloads the file, so the form shows the new values on the next page load. Form values override the YAML configuration; the order is described in Configuration. Each run writes effective_config.yaml . Ignore Web UI settings and use configuration defaults runs with the YAML values only. model.auto_profile: apply may still adjust MATPOWER import conventions after form and API values are assembled; effective_config.yaml records that. Help in the header opens the help (Web UI) inside the Web UI, as shipped with the running version, and the help links to this reference; Project Docs opens the published documentation ( webui.docs_base_url ). The help pages behind the ? icons carry a section of the help or of this reference in full, or the lead paragraph of a library section with the link to it. Search the help The search field stands at the top of the help and of this reference and in the header of every page. It looks through the help, the reference and the help pages of the controls, headings and tables included. Every word entered must occur, a part of a word is enough, upper and lower case do not matter. The hits appear while you type: the heading of the section as a link to its place, below it a line of the text with the words marked, hits in a heading first. / puts the cursor into the search field, Enter opens the first hit, Esc closes the list. Without a hit the page says so and links to the published documentation, which has a search of its own. The search runs on the own machine on an index that ships with the application; it needs no network. With scripts switched off in the browser the field is a plain form that answers with a page of hits."),
  (title = "Bus/branch CSV files", url = "/help/webui.detailed_result_csv", kind = "control", text = "Write bus_voltages_complex.csv and branch_flows.csv with per-bus voltages and per-branch flows. Off by default because large networks produce large files. - Logfile output mode : classic writes the result report plus a compact timing and status summary ( solver_time , representative_time , iterations, final mismatch, outcome); full adds Full run details with the effective typed configuration, artifact choices and status diagnostics. MATPOWER .m runs also print the \"Original/Final effective MATPOWER import options\" and \"MATPOWER auto-profile recommendations\" tables, because .m files leave shift_sign , shift_unit and ratio ambiguous; DTF .DAT runs never print them, so their shorter run.log is expected. - Performance timing ( off , compact , full ) writes performance.log with the phases of one request (request parsing, case resolution, configuration, case loading and network construction, solve, postprocessing, artifact writing, solver and total time; full adds internal profile entries). A run from the Web UI solves once; repeated timing is the benchmark mode of run_matpower_case in a script (Performance Profiling). Older saved configurations with the former benchmark fields of the form are cleaned by Refresh configuration , which names each removed field. - Export case as CGMES delivery (EQ+TP+SSH+SV, ZIP) writes the case as one re-importable delivery into the run's artifacts, for every case format and also on non-converged runs; see CGMES Export. - Write bus/branch CSV files (API default off, because large networks produce large files) writes bus_voltages_complex.csv (per bus vm_pu , va_deg , numeric v_re and v_im , readable v_complex , nominal and actual voltage, generation, load, Q-limit and control columns) and branch_flows.csv (active and reactive power at both ends, losses, rating, status, overload) from the ACPFlowReport rows. - CSV format is the machine-scope key output.csv_format ( Save settings writes it to the configuration file, a per-case save leaves it out) and applies to every CSV of every run type, state estimation included: technical (default: comma delimiter, decimal point, no grouping), excel_de (semicolon, decimal comma, thousands dot), excel_us (comma, decimal point, thousands comma, grouped numbers quoted). The Excel formats avoid exponent notation where practical; v_complex follows the decimal notation, v_re / v_im stay numeric. Excel may still auto-convert identifiers like 1E5 ; use Data From Text/CSV with text types when that matters."),
  (title = "CSV format (every CSV file of a run)", url = "/help/webui.detailed_result_csv_format", kind = "control", text = "Delimiter and decimal separator of every CSV a run writes: technical (comma, point), excel_de (semicolon, decimal comma) or excel_us. A machine-wide setting. - Logfile output mode : classic writes the result report plus a compact timing and status summary ( solver_time , representative_time , iterations, final mismatch, outcome); full adds Full run details with the effective typed configuration, artifact choices and status diagnostics. MATPOWER .m runs also print the \"Original/Final effective MATPOWER import options\" and \"MATPOWER auto-profile recommendations\" tables, because .m files leave shift_sign , shift_unit and ratio ambiguous; DTF .DAT runs never print them, so their shorter run.log is expected. - Performance timing ( off , compact , full ) writes performance.log with the phases of one request (request parsing, case resolution, configuration, case loading and network construction, solve, postprocessing, artifact writing, solver and total time; full adds internal profile entries). A run from the Web UI solves once; repeated timing is the benchmark mode of run_matpower_case in a script (Performance Profiling). Older saved configurations with the former benchmark fields of the form are cleaned by Refresh configuration , which names each removed field. - Export case as CGMES delivery (EQ+TP+SSH+SV, ZIP) writes the case as one re-importable delivery into the run's artifacts, for every case format and also on non-converged runs; see CGMES Export. - Write bus/branch CSV files (API default off, because large networks produce large files) writes bus_voltages_complex.csv (per bus vm_pu , va_deg , numeric v_re and v_im , readable v_complex , nominal and actual voltage, generation, load, Q-limit and control columns) and branch_flows.csv (active and reactive power at both ends, losses, rating, status, overload) from the ACPFlowReport rows. - CSV format is the machine-scope key output.csv_format ( Save settings writes it to the configuration file, a per-case save leaves it out) and applies to every CSV of every run type, state estimation included: technical (default: comma delimiter, decimal point, no grouping), excel_de (semicolon, decimal comma, thousands dot), excel_us (comma, decimal point, thousands comma, grouped numbers quoted). The Excel formats avoid exponent notation where practical; v_complex follows the decimal notation, v_re / v_im stay numeric. Excel may still auto-convert identifiers like 1E5 ; use Data From Text/CSV with text types when that matters."),
  (title = "Selected DTF outage labels/indices", url = "/help/webui.dtf_outage_selection", kind = "control", text = "One outage label or index of the DTF case, used with the run mode selected. The result page shows a compact outage summary; the rows stay in the artifacts. The settings and run forms offer: - case name or local path, configuration template file, the read-only output root (set only through start_sparlectra_webui(; output_root) ); - tolerance (decimals or scientific notation such as 1e-8 ; the exponent spinner, buttons or Up/Down keys, steps the exponent and keeps the mantissa: 1e-5 down gives 1e-6 , up gives 1e-4 ), maximum iterations, autodamping with its minimum factor; - Q-limit handling : the power_flow.qlimits.enabled checkbox and the enforcement-mode selector in one block; the selector also offers off and shows it whenever the handling is off. Below them, PV/PQ switching shows the hysteresis and the final check bound ( final_q_accept_pu , auto or a value in pu; the two settings the classic modes read), the first switching iteration ( start_iter ), the maximum switches per bus ( guard.max_switches ), freezing after repeated switching and the narrow-range guard switch ( guard.enabled ); Advanced holds the rest of power_flow.qlimits : start rule and auto threshold, cooldown, release voltage margin, the traced buses (bus numbers of the case file) and the buses locked to PQ (case bus numbers for a MATPOWER file, otherwise internal positions), the violation rule and threshold, bounded violations, and the narrow- and zero-range rules with their log line (Q-limit options and guard). Per-unit values take scientific notation like the tolerance, bus lists comma-separated numbers. Everything is grayed while the handling is off; the classic modes solve completely and then check the limits, again after every clamp, so they have no start iteration and gray what they do not read (they use the hysteresis and the final check bound); the guard switch grays the range rules, because the switch cap, freezing and the violation rule act without it. All of it saves to the configuration file and per case like every other run option; - Solver : one radio group power_flow_solver with the peer values rectangular (AC Newton-Raphson), apslf (AnalyticLoadFlow) and dc (linear screening model), writing power_flow.solver , power_flow.apslf. , power_flow.apslf_start. and power_flow.dc. (solver selection, DC power flow); radio buttons are never disabled, so the choice is always submitted; - wrong-branch detection mode, start angle and voltage modes; - Advanced start values : the current-iteration pre-solve fields ( power_flow.start_current_iteration. , guarded pre-solve), a preconditioner between start projection and Newton-Raphson, not a new start mode; - Merit-function line search : power_flow.merit.enabled , power_flow.merit.armijo_c1 , power_flow.merit.fallback_max_mismatch (options), requires power_flow.autodamp = true ; scale_p / scale_q / scale_v are YAML-only; a diagnostic run writes merit_linesearch.log ; - Non-convergence handling (Advanced): power_flow.rescue (retry ladder), power_flow.auto_slack (promote a reference when the case registers none; islands always find their own reference) and power_flow.dc.fallback (standalone DC result when AC has no solution), see Power-Flow Configuration; - MATPOWER import conventions: auto-profile mode ( off , recommend , apply ) plus transformer ratio, phase shift, bus shunt, PV voltage source and comparison reference; - logfile output mode, performance timing and post-run diagnostics. Only keys in GUI_EDITABLE_CONFIG_KEYS are submitted, the selected template is never modified, and each run writes effective_config.yaml . Every control carries a hover text with its operation and effect; a ? next to a control with something technical behind it (solver options, estimator diagnostics, Q-limits, formats) opens its help page in a new tab: the hint, the matching section of this documentation as shipped with the running version (the beginning of a long section), and a link to the section on the published site. webui.docs_base_url (configuration file) points that link at a local docs build or a pinned version. Back returns through the browser history with the entered values intact (fallback /powerflow ). Fields that do not apply to the selected solver or step control (autodamp/trust-region) are grayed out in place, not hidden; a grayed field is disabled and not submitted."),
  (title = "CGMES export artifact", url = "/help/webui.export_cgmes", kind = "control", text = "Write the case as one re-importable CGMES delivery (EQ, TP, SSH, SV in a ZIP) into the run's artifacts, for every case format and also on non-converged runs. The run option Write MATPOWER export artifact works the same way for every case format: the network of the run is written as a new file <case _calc_<YYYYMMDD .m next to the other artifacts, with a header that names the source case, the write time, the Sparlectra version and whether the bus and branch columns carry the calculated state. The input file is never written."),
  (title = "Optional FOR002 reference file", url = "/help/webui.for002_reference_file", kind = "control", text = "Optional FOR002 file for the legacy reference comparison of a DTF run: absolute path, path in the case cache, or an offered candidate. Not a primary case. The settings and run forms offer: - case name or local path, configuration template file, the read-only output root (set only through start_sparlectra_webui(; output_root) ); - tolerance (decimals or scientific notation such as 1e-8 ; the exponent spinner, buttons or Up/Down keys, steps the exponent and keeps the mantissa: 1e-5 down gives 1e-6 , up gives 1e-4 ), maximum iterations, autodamping with its minimum factor; - Q-limit handling : the power_flow.qlimits.enabled checkbox and the enforcement-mode selector in one block; the selector also offers off and shows it whenever the handling is off. Below them, PV/PQ switching shows the hysteresis and the final check bound ( final_q_accept_pu , auto or a value in pu; the two settings the classic modes read), the first switching iteration ( start_iter ), the maximum switches per bus ( guard.max_switches ), freezing after repeated switching and the narrow-range guard switch ( guard.enabled ); Advanced holds the rest of power_flow.qlimits : start rule and auto threshold, cooldown, release voltage margin, the traced buses (bus numbers of the case file) and the buses locked to PQ (case bus numbers for a MATPOWER file, otherwise internal positions), the violation rule and threshold, bounded violations, and the narrow- and zero-range rules with their log line (Q-limit options and guard). Per-unit values take scientific notation like the tolerance, bus lists comma-separated numbers. Everything is grayed while the handling is off; the classic modes solve completely and then check the limits, again after every clamp, so they have no start iteration and gray what they do not read (they use the hysteresis and the final check bound); the guard switch grays the range rules, because the switch cap, freezing and the violation rule act without it. All of it saves to the configuration file and per case like every other run option; - Solver : one radio group power_flow_solver with the peer values rectangular (AC Newton-Raphson), apslf (AnalyticLoadFlow) and dc (linear screening model), writing power_flow.solver , power_flow.apslf. , power_flow.apslf_start. and power_flow.dc. (solver selection, DC power flow); radio buttons are never disabled, so the choice is always submitted; - wrong-branch detection mode, start angle and voltage modes; - Advanced start values : the current-iteration pre-solve fields ( power_flow.start_current_iteration. , guarded pre-solve), a preconditioner between start projection and Newton-Raphson, not a new start mode; - Merit-function line search : power_flow.merit.enabled , power_flow.merit.armijo_c1 , power_flow.merit.fallback_max_mismatch (options), requires power_flow.autodamp = true ; scale_p / scale_q / scale_v are YAML-only; a diagnostic run writes merit_linesearch.log ; - Non-convergence handling (Advanced): power_flow.rescue (retry ladder), power_flow.auto_slack (promote a reference when the case registers none; islands always find their own reference) and power_flow.dc.fallback (standalone DC result when AC has no solution), see Power-Flow Configuration; - MATPOWER import conventions: auto-profile mode ( off , recommend , apply ) plus transformer ratio, phase shift, bus shunt, PV voltage source and comparison reference; - logfile output mode, performance timing and post-run diagnostics. Only keys in GUI_EDITABLE_CONFIG_KEYS are submitted, the selected template is never modified, and each run writes effective_config.yaml . Every control carries a hover text with its operation and effect; a ? next to a control with something technical behind it (solver options, estimator diagnostics, Q-limits, formats) opens its help page in a new tab: the hint, the matching section of this documentation as shipped with the running version (the beginning of a long section), and a link to the section on the published site. webui.docs_base_url (configuration file) points that link at a local docs build or a pinned version. Back returns through the browser history with the entered values intact (fallback /powerflow ). Fields that do not apply to the selected solver or step control (autodamp/trust-region) are grayed out in place, not hidden; a grayed field is disabled and not submitted."),
  (title = "Ignore Web UI settings and use configuration defaults", url = "/help/webui.ignore_webui_settings", kind = "control", text = "Run with the configuration file's values only: the form values and the saved case settings are ignored for this run. Check configuration and Refresh configuration bring a local file up to a template that gained options. Check is a dry run against src/config/configuration.yaml.example : missing keys, known deprecated aliases, duplicate YAML keys and a preview of the refreshed YAML, nothing written. Refresh keeps existing values, adds missing keys with template defaults and may normalize deprecated aliases (start-mode settings, legacy matpower_ Q-limit mode names); it never runs at startup, writes a timestamped backup first, refuses on duplicate keys, and offers uploaded or pasted YAML as a download instead of rewriting it. The Configuration Editor opens the active YAML in a textarea, validates it with the same parser and duplicate-key checks, writes only after validation with a timestamped backup, and warns when a case configuration file still overrides the global YAML through the prefilled form. After a save the server reloads the file, so the form shows the new values on the next page load. Form values override the YAML configuration; the order is described in Configuration. Each run writes effective_config.yaml . Ignore Web UI settings and use configuration defaults runs with the YAML values only. model.auto_profile: apply may still adjust MATPOWER import conventions after form and API values are assembled; effective_config.yaml records that. Help in the header opens the help (Web UI) inside the Web UI, as shipped with the running version, and the help links to this reference; Project Docs opens the published documentation ( webui.docs_base_url ). The help pages behind the ? icons carry a section of the help or of this reference in full, or the lead paragraph of a library section with the link to it. Search the help The search field stands at the top of the help and of this reference and in the header of every page. It looks through the help, the reference and the help pages of the controls, headings and tables included. Every word entered must occur, a part of a word is enough, upper and lower case do not matter. The hits appear while you type: the heading of the section as a link to its place, below it a line of the text with the words marked, hits in a heading first. / puts the cursor into the search field, Enter opens the first hit, Esc closes the list. Without a hit the page says so and links to the published documentation, which has a search of its own. The search runs on the own machine on an index that ships with the application; it needs no network. With scripts switched off in the browser the field is a plain form that answers with a page of hits."),
  (title = "Import case files", url = "/help/webui.import_case_files", kind = "control", text = "Copy MATPOWER, DTF, CGMES (ZIP or profile XML), SCF/PGM JSON or PowSyBl IIDM files into the case directory. Nothing is run; no existing file is overwritten. Import case files opens the native file picker and accepts several files at once: MATPOWER .m / .M , DTF .dat / .DAT , CGMES .zip deliveries, CGMES profile files ( .xml ) and PowSyBl IIDM files ( .xiidm ); the server validates the extension again. An uploaded .xiidm file runs as it is. Several .xml files (the EQ, SSH, TP and SV profiles of one delivery, such as a data/cgmes_demo folder) are packed into one <stem _cgmes.zip named after the common stem; the set must contain the EQ profile. A CGMES ZIP may hold nested ZIPs; the importer opens them in memory. A Sparlectra Case Format .json file is parsed and validated before it is stored. Importing is copy-only: no run, no run directory, no parsing of .m code. Files land in the case directory the form shows ( data/mpower , in a checkout too), the selector is rebuilt from disk, and the first runnable file may be preselected; the run still needs Start PowerFlow run . Limits: 100 MiB per file, 250 MiB per request. An existing file is never overwritten ( already exists , the other files still import), and names that would resolve outside the case directory are refused. Enter in Or type case file path resolves the value the same copy-only way: a bare case name via ensure_casefile , cgmes:<alias as below, or a full local path copied with the same validation; the file then appears in the Existing case file selector. Re-importing a saved set brings the .config.yaml sidecar along with the .scf.json and its measurement set(s) when all are selected together; the .yaml is validated as a case-scope configuration file ( scope: case ) before it is stored, and rejected otherwise."),
  (title = "Performance timing", url = "/help/webui.performance_timing", kind = "control", text = "Write performance.log with the phases of one request (parsing, case loading, solve, artifacts); full adds internal profile entries, off writes nothing. - Logfile output mode : classic writes the result report plus a compact timing and status summary ( solver_time , representative_time , iterations, final mismatch, outcome); full adds Full run details with the effective typed configuration, artifact choices and status diagnostics. MATPOWER .m runs also print the \"Original/Final effective MATPOWER import options\" and \"MATPOWER auto-profile recommendations\" tables, because .m files leave shift_sign , shift_unit and ratio ambiguous; DTF .DAT runs never print them, so their shorter run.log is expected. - Performance timing ( off , compact , full ) writes performance.log with the phases of one request (request parsing, case resolution, configuration, case loading and network construction, solve, postprocessing, artifact writing, solver and total time; full adds internal profile entries). A run from the Web UI solves once; repeated timing is the benchmark mode of run_matpower_case in a script (Performance Profiling). Older saved configurations with the former benchmark fields of the form are cleaned by Refresh configuration , which names each removed field. - Export case as CGMES delivery (EQ+TP+SSH+SV, ZIP) writes the case as one re-importable delivery into the run's artifacts, for every case format and also on non-converged runs; see CGMES Export. - Write bus/branch CSV files (API default off, because large networks produce large files) writes bus_voltages_complex.csv (per bus vm_pu , va_deg , numeric v_re and v_im , readable v_complex , nominal and actual voltage, generation, load, Q-limit and control columns) and branch_flows.csv (active and reactive power at both ends, losses, rating, status, overload) from the ACPFlowReport rows. - CSV format is the machine-scope key output.csv_format ( Save settings writes it to the configuration file, a per-case save leaves it out) and applies to every CSV of every run type, state estimation included: technical (default: comma delimiter, decimal point, no grouping), excel_de (semicolon, decimal comma, thousands dot), excel_us (comma, decimal point, thousands comma, grouped numbers quoted). The Excel formats avoid exponent notation where practical; v_complex follows the decimal notation, v_re / v_im stay numeric. Excel may still auto-convert identifiers like 1E5 ; use Data From Text/CSV with text types when that matters."),
  (title = "Auto mode", url = "/help/webui.power_flow_mode", kind = "control", text = "Pick start-value, step-control and Q-limit strategy from the network, retrying with stronger strategies on non-convergence. Explicit options below always win. The options every AC run reads: formulation and mode, flat start, tolerance and iteration cap, damping, slack promotion, the rescue ladder and the DC fallback. The Web UI form carries the ones a run is usually tuned with; the rest is YAML only."),
  (title = "Case export (SCF / plain PGM)", url = "/help/webui.scf_export", kind = "control", text = "Write the selected case into the case directory as an SCF file (.scf.json) or as a plain power-grid-model dataset (.pgm.json) without the sparlectra block. exportSCF writes a network as one JSON file that reads back machine-exact, with its source, the intended calculations and, on request, the solved start state; the Web UI offers the same export from the Case page."),
  (title = "Generator: flows per branch", url = "/help/webui.se_generator_flow_ends", kind = "control", text = "Flows per branch: both ends writes P and Q at from and to; one end keeps one flow group per branch, preferring the end whose bus has injection telemetry. Truth state, flow placement, passive-node handling and a target number of critical measurements are configurable in the Web UI form."),
  (title = "Generator: bad data rows", url = "/help/webui.se_generator_gross_count", kind = "control", text = "How many measurement rows get the gross error; the seed decides which rows. Used only when bad data k is above 0. Corrupts one measurement, the first active-power flow row, by k times its sigma. 0 = off; 10 is a good value: one clearly detectable bad measurement (for example a stuck transducer). Bad data rows says how many telemetry rows get the gross error; the seed decides which."),
  (title = "Generator: bad data (k·sigma)", url = "/help/webui.se_generator_gross_error", kind = "control", text = "Corrupt seed-randomly drawn measurements by k times their sigma. 0 is off; 10 gives clearly detectable bad data for the elimination and robust workflow. Corrupts one measurement, the first active-power flow row, by k times its sigma. 0 = off; 10 is a good value: one clearly detectable bad measurement (for example a stuck transducer). Bad data rows says how many telemetry rows get the gross error; the seed decides which."),
  (title = "Generator: seeded noise", url = "/help/webui.se_generator_noise", kind = "control", text = "Add seeded Gaussian noise at the sigmas below. Without noise the measurements match the model exactly and J lands near 0 instead of near dof. Adds Gaussian noise at the per-quantity sigmas to every generated value. The random generator is seeded, so regenerating with the same inputs reproduces the identical file."),
  (title = "Generator: passive nodes", url = "/help/webui.se_generator_passive", kind = "control", text = "How a passive node enters the set: on writes a protected zero-injection constraint, off an ordinary zero balance row. The sigma applies to both, floor 1 kW. Truth state, flow placement, passive-node handling and a target number of critical measurements are configurable in the Web UI form."),
  (title = "Generator: measurement sigmas (U, I, P, Q)", url = "/help/webui.se_generator_sigmas", kind = "control", text = "Measurement accuracy per quantity in percent of the measured value, like a transducer class; written into the sigma column of every row and used for the noise. Measurement accuracy per quantity in percent of the measured value (like a transducer accuracy class), written into the sigma column of every generated row and used for the noise, when enabled:"),
  (title = "Generator: tap deviation transformers", url = "/help/webui.se_generator_tap_count", kind = "control", text = "At most this many transformers get the tap deviation; the seed picks them among transformers the tap estimation can absorb. Unused when the deviation is 0. Generates the measurements from a network state whose first in-service transformer runs the given number of mechanical tap steps off the model position (0 = off; whole steps only, a tap changer has no half positions). Transformers (max) bounds how many transformers deviate. The deviation lives on the same tap-fraction grid the estimator's fixation uses, so it is exactly recoverable: tap estimation finds the step and the fixation run ends near J = 0 ."),
  (title = "Generator: tap deviation", url = "/help/webui.se_generator_tap_error", kind = "control", text = "Generate from a state whose seed-selected transformers run this many mechanical tap steps off the model position; 0 is off. Needs truth state fresh solve. Generates the measurements from a network state whose first in-service transformer runs the given number of mechanical tap steps off the model position (0 = off; whole steps only, a tap changer has no half positions). Transformers (max) bounds how many transformers deviate. The deviation lives on the same tap-fraction grid the estimator's fixation uses, so it is exactly recoverable: tap estimation finds the step and the fixation run ends near J = 0 ."),
  (title = "Generator: truth state", url = "/help/webui.se_generator_truth", kind = "control", text = "Where the truth state comes from: fresh solve solves the case now, from run adopts the solved voltages of a successful run of this case without re-solving. Truth state, flow placement, passive-node handling and a target number of critical measurements are configurable in the Web UI form."),
  (title = "Sequential elimination budget", url = "/help/webui.se_max_eliminations", kind = "control", text = "Upper bound of the sequential bad-data elimination: the worst localizable row is removed and the estimation rerun, up to this many times. 0 disables it. Upper bound for the sequential bad-data elimination: while the chi-square band test fails and a suspicious measurement (normalized residual at or above 3) is localizable ( wii 0.3), the worst row is deactivated and the estimation reruns, up to this many times. 0 disables elimination (diagnostics only)."),
  (title = "Measurement set (CSV v1)", url = "/help/webui.se_measurement_file", kind = "control", text = "Measurement CSV v1 set the estimation runs on. The set bound to the selected case is preselected; sets from other cases are labeled. writeMeasurementsCSV(net; file) and readMeasurementsCSV!(net; file, replace = true) persist measurement sets as UTF-8 CSV. The first line is the version comment, the second the header:"),
  (title = "Noise seed", url = "/help/webui.se_noise_seed", kind = "control", text = "Seed of the noise draw. The same seed reproduces the same noisy set, a different seed draws a fresh realization. A Sparlectra Case Format case stores its measurement set inside the file. An estimation on such a case needs no separate CSV; the run still writes measurements.csv into its output directory for reproducibility. Naming a set explicitly takes precedence, and a set generated for the case replaces the one the file carries (the newer data). Every other format requires a CSV."),
  (title = "Estimate transformer taps", url = "/help/webui.se_tap_estimation", kind = "control", text = "Release every in-service ratio tap changer as an extra estimation state, fix it to the nearest mechanical step and rerun. Machine transformers stay untouched. A tap position that disagrees with the model (a stale SCADA position, a local operation) poisons the estimate around the transformer: the band test reports :high and the suspects cluster there although every telemetry row is healthy. Releasing the tap as an estimation state resolves this. The estimator solves with the tap as a continuous state, rounds it to the nearest mechanical step, and solves once more with the tap fixed; the reported result is that of the fixed run."),
]
